DROP TABLE TEMP4TXN PURGE;
DROP TABLE TEMP4AUM PURGE;

CREATE TABLE TEMP4TXN
AS
SELECT PARTY_ID_MASK AS PARTY_ID
,TXN_YYYYMM
,PROD_TYPE_CODE
,PROD_MTYPE_CODE
,PROD_STYPE_CODE
,CURRENCY_CODE
,BUY_SELL_CODE
,TXN_TYPE_CODE
,TXN_TYPE_DETAIL_CODE
,SUM(TXN_AMT_TWD)TXN_AMT_TWD
FROM(
/*****************************************************/
--商品交易
--台股海外股
SELECT PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_TYPE_CODE,TXN_TYPE_DETAIL_CODE,TXN_AMT_TWD FROM DM_S_VIEW.M_AT_STOCK_TXN
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
UNION ALL --期權
SELECT PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_TYPE_CODE,TXN_TYPE_DETAIL_CODE,TXN_AMT_TWD FROM DM_S_VIEW.M_AT_FUTURE_TXN
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
UNION ALL --海外債
SELECT PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_TYPE_CODE,TXN_TYPE_DETAIL_CODE,TXN_AMT_TWD FROM DM_S_VIEW.M_AT_BOND_TXN
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
UNION ALL --基金
SELECT PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_TYPE_CODE,TXN_TYPE_DETAIL_CODE,TXN_AMT_TWD FROM DM_S_VIEW.M_AT_FUND_TXN
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
UNION ALL --結構型
SELECT PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_TYPE_CODE,TXN_TYPE_DETAIL_CODE,TXN_AMT_TWD FROM DM_S_VIEW.M_AT_SN_TXN
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
UNION ALL --壽險
SELECT PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE
,CURRENCY_CODE,'001' AS BUY_SELL_CODE,TXN_TYPE_CODE,TXN_TYPE_DETAIL_CODE,TXN_AMT_TWD FROM DM_S_VIEW.M_AT_INSURANCE_TXN
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym AND POLICY_STATUS_CODE IN(0,1)
) A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
GROUP BY PARTY_ID_MASK,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE,CURRENCY_CODE,BUY_SELL_CODE,TXN_TYPE_CODE,TXN_TYPE_DETAIL_CODE;

CREATE TABLE TEMP4AUM1
AS
SELECT PARTY_ID_MASK AS PARTY_ID 
------台幣 TWD
,SUM(CASE WHEN CURRENCY_CODE='TWD' AND SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END) TWD_AUM_M
,SUM(CASE WHEN CURRENCY_CODE='TWD' AND SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END) TWD_AUM_L
,SUM(CASE WHEN CURRENCY_CODE='TWD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN BAL_AMT_TWD ELSE 0 END) TWD_AUM_3M
,SUM(CASE WHEN CURRENCY_CODE='TWD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END) TWD_AUM_3ML
,SUM(CASE WHEN CURRENCY_CODE='TWD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN BAL_AMT_TWD ELSE 0 END) TWD_AUM_6M
,SUM(CASE WHEN CURRENCY_CODE='TWD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END) TWD_AUM_6ML
,SUM(CASE WHEN CURRENCY_CODE='TWD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN BAL_AMT_TWD ELSE 0 END) TWD_AUM_12M
,SUM(CASE WHEN CURRENCY_CODE='TWD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END) TWD_AUM_12ML     
------美金 USD
,SUM(CASE WHEN CURRENCY_CODE='USD' AND SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END) USD_AUM_M
,SUM(CASE WHEN CURRENCY_CODE='USD' AND SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END) USD_AUM_L
,SUM(CASE WHEN CURRENCY_CODE='USD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN BAL_AMT_TWD ELSE 0 END) USD_AUM_3M
,SUM(CASE WHEN CURRENCY_CODE='USD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END) USD_AUM_3ML
,SUM(CASE WHEN CURRENCY_CODE='USD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN BAL_AMT_TWD ELSE 0 END) USD_AUM_6M
,SUM(CASE WHEN CURRENCY_CODE='USD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END) USD_AUM_6ML
,SUM(CASE WHEN CURRENCY_CODE='USD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN BAL_AMT_TWD ELSE 0 END) USD_AUM_12M
,SUM(CASE WHEN CURRENCY_CODE='USD' AND SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END) USD_AUM_12ML     
------其他幣別 OD
,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END) OD_AUM_M
