FROM DM_S_VIEW.M_AC_ACCOUNT_ASSET A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) C
ON A.PARTY_ID = C.PARTY_ID
inner join(SELECT DISTINCT CUSTOMER_ID FROM DS_SEC.CF_CUSTID where YYYYMM = :ym)b
on C.PARTY_ID_MASK = b.CUSTOMER_ID
WHERE SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK;

