    ,ROUND(CASE WHEN NVL(TWD_TURNOVER_3M,0)=0 AND NVL(TWD_TURNOVER_3ML,0)=0 THEN NULL ELSE TWD_TURNOVER_3M - TWD_TURNOVER_3ML END,4) TWD_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(TWD_TURNOVER_3ML,0)!=0 THEN (NVL(TWD_TURNOVER_3M,0)/NVL(TWD_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS TWD_TURNOVER_3M_RDIFF
    ,ROUND(TWD_NET_TXN_6M,0)TWD_NET_TXN_6M
    ,ROUND(TWD_NET_TXN_6M_MDIFF,0)TWD_NET_TXN_6M_MDIFF
    ,ROUND(TWD_NET_TXN_6M_RDIFF,4)TWD_NET_TXN_6M_RDIFF
    ,ROUND(TWD_TURNOVER_6M,4)TWD_TURNOVER_6M
    ,ROUND(CASE WHEN NVL(TWD_TURNOVER_6M,0)=0 AND NVL(TWD_TURNOVER_6ML,0)=0 THEN NULL ELSE TWD_TURNOVER_6M - TWD_TURNOVER_6ML END,4) TWD_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(TWD_TURNOVER_6ML,0)!=0 THEN (NVL(TWD_TURNOVER_6M,0)/NVL(TWD_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS TWD_TURNOVER_6M_RDIFF
    ,ROUND(TWD_NET_TXN_12M,0)TWD_NET_TXN_12M
    ,ROUND(TWD_NET_TXN_12M_MDIFF,0)TWD_NET_TXN_12M_MDIFF
    ,ROUND(TWD_NET_TXN_12M_RDIFF,4)TWD_NET_TXN_12M_RDIFF
    ,ROUND(TWD_TURNOVER_12M,4)TWD_TURNOVER_12M
    ,ROUND(CASE WHEN NVL(TWD_TURNOVER_12M,0)=0 AND NVL(TWD_TURNOVER_12ML,0)=0 THEN NULL ELSE TWD_TURNOVER_12M - TWD_TURNOVER_12ML END,4) TWD_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(TWD_TURNOVER_12ML,0)!=0 THEN (NVL(TWD_TURNOVER_12M,0)/NVL(TWD_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS TWD_TURNOVER_12M_RDIFF
    
    ,ROUND(USD_NET_TXN_M,0)USD_NET_TXN_M
    ,ROUND(USD_NET_TXN_M_MDIFF,0)USD_NET_TXN_M_MDIFF
    ,ROUND(USD_NET_TXN_M_RDIFF,4)USD_NET_TXN_M_RDIFF
    ,ROUND(USD_TURNOVER_M,4)USD_TURNOVER_M
    ,ROUND(CASE WHEN NVL(USD_TURNOVER_M,0)=0 AND NVL(USD_TURNOVER_L,0)=0 THEN NULL ELSE USD_TURNOVER_M - USD_TURNOVER_L END,4) USD_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(USD_TURNOVER_L,0)!=0 THEN (NVL(USD_TURNOVER_M,0)/NVL(USD_TURNOVER_L,0))-1 ELSE 0 END,4) AS USD_TURNOVER_M_RDIFF
    ,ROUND(USD_NET_TXN_3M,0)USD_NET_TXN_3M
    ,ROUND(USD_NET_TXN_3M_MDIFF,0)USD_NET_TXN_3M_MDIFF
    ,ROUND(USD_NET_TXN_3M_RDIFF,4)USD_NET_TXN_3M_RDIFF
    ,ROUND(USD_TURNOVER_3M,4)USD_TURNOVER_3M
    ,ROUND(CASE WHEN NVL(USD_TURNOVER_3M,0)=0 AND NVL(USD_TURNOVER_3ML,0)=0 THEN NULL ELSE USD_TURNOVER_3M - USD_TURNOVER_3ML END,4) USD_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(USD_TURNOVER_3ML,0)!=0 THEN (NVL(USD_TURNOVER_3M,0)/NVL(USD_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS USD_TURNOVER_3M_RDIFF
    ,ROUND(USD_NET_TXN_6M,0)USD_NET_TXN_6M
    ,ROUND(USD_NET_TXN_6M_MDIFF,0)USD_NET_TXN_6M_MDIFF
    ,ROUND(USD_NET_TXN_6M_RDIFF,4)USD_NET_TXN_6M_RDIFF
    ,ROUND(USD_TURNOVER_6M,4)USD_TURNOVER_6M
    ,ROUND(CASE WHEN NVL(USD_TURNOVER_6M,0)=0 AND NVL(USD_TURNOVER_6ML,0)=0 THEN NULL ELSE USD_TURNOVER_6M - USD_TURNOVER_6ML END,4) USD_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(USD_TURNOVER_6ML,0)!=0 THEN (NVL(USD_TURNOVER_6M,0)/NVL(USD_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS USD_TURNOVER_6M_RDIFF
    ,ROUND(USD_NET_TXN_12M,0)USD_NET_TXN_12M
    ,ROUND(USD_NET_TXN_12M_MDIFF,0)USD_NET_TXN_12M_MDIFF
    ,ROUND(USD_NET_TXN_12M_RDIFF,4)USD_NET_TXN_12M_RDIFF
    ,ROUND(USD_TURNOVER_12M,4)USD_TURNOVER_12M
    ,ROUND(CASE WHEN NVL(USD_TURNOVER_12M,0)=0 AND NVL(USD_TURNOVER_12ML,0)=0 THEN NULL ELSE USD_TURNOVER_12M - USD_TURNOVER_12ML END,4) USD_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(USD_TURNOVER_12ML,0)!=0 THEN (NVL(USD_TURNOVER_12M,0)/NVL(USD_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS USD_TURNOVER_12M_RDIFF
    
    ,ROUND(OD_NET_TXN_M,0)OD_NET_TXN_M
    ,ROUND(OD_NET_TXN_M_MDIFF,0)OD_NET_TXN_M_MDIFF
    ,ROUND(OD_NET_TXN_M_RDIFF,4)OD_NET_TXN_M_RDIFF
    ,ROUND(OD_TURNOVER_M,4)OD_TURNOVER_M
    ,ROUND(CASE WHEN NVL(OD_TURNOVER_M,0)=0 AND NVL(OD_TURNOVER_L,0)=0 THEN NULL ELSE OD_TURNOVER_M - OD_TURNOVER_L END,4) OD_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(OD_TURNOVER_L,0)!=0 THEN (NVL(OD_TURNOVER_M,0)/NVL(OD_TURNOVER_L,0))-1 ELSE 0 END,4) AS OD_TURNOVER_M_RDIFF
    ,ROUND(OD_NET_TXN_3M,0)OD_NET_TXN_3M
    ,ROUND(OD_NET_TXN_3M_MDIFF,0)OD_NET_TXN_3M_MDIFF
    ,ROUND(OD_NET_TXN_3M_RDIFF,4)OD_NET_TXN_3M_RDIFF
    ,ROUND(OD_TURNOVER_3M,4)OD_TURNOVER_3M
    ,ROUND(CASE WHEN NVL(OD_TURNOVER_3M,0)=0 AND NVL(OD_TURNOVER_3ML,0)=0 THEN NULL ELSE OD_TURNOVER_3M - OD_TURNOVER_3ML END,4) OD_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(OD_TURNOVER_3ML,0)!=0 THEN (NVL(OD_TURNOVER_3M,0)/NVL(OD_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS OD_TURNOVER_3M_RDIFF
    ,ROUND(OD_NET_TXN_6M,0)OD_NET_TXN_6M
    ,ROUND(OD_NET_TXN_6M_MDIFF,0)OD_NET_TXN_6M_MDIFF
    ,ROUND(OD_NET_TXN_6M_RDIFF,4)OD_NET_TXN_6M_RDIFF
    ,ROUND(OD_TURNOVER_6M,4)OD_TURNOVER_6M
    ,ROUND(CASE WHEN NVL(OD_TURNOVER_6M,0)=0 AND NVL(OD_TURNOVER_6ML,0)=0 THEN NULL ELSE OD_TURNOVER_6M - OD_TURNOVER_6ML END,4) OD_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(OD_TURNOVER_6ML,0)!=0 THEN (NVL(OD_TURNOVER_6M,0)/NVL(OD_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS OD_TURNOVER_6M_RDIFF
    ,ROUND(OD_NET_TXN_12M,0)OD_NET_TXN_12M
    ,ROUND(OD_NET_TXN_12M_MDIFF,0)OD_NET_TXN_12M_MDIFF
    ,ROUND(OD_NET_TXN_12M_RDIFF,4)OD_NET_TXN_12M_RDIFF
    ,ROUND(OD_TURNOVER_12M,4)OD_TURNOVER_12M
    ,ROUND(CASE WHEN NVL(OD_TURNOVER_12M,0)=0 AND NVL(OD_TURNOVER_12ML,0)=0 THEN NULL ELSE OD_TURNOVER_12M - OD_TURNOVER_12ML END,4) OD_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(OD_TURNOVER_12ML,0)!=0 THEN (NVL(OD_TURNOVER_12M,0)/NVL(OD_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS OD_TURNOVER_12M_RDIFF

FROM(
    SELECT DISTINCT A.CUSTOMER_ID
        ,A.YYYYMM
        ---所有商品淨流
        ,NVL(AP_NET_TXN_M,0)AP_NET_TXN_M
        ,CASE WHEN NVL(AP_NET_TXN_M,0)=0 AND NVL(AP_NET_TXN_L,0)=0 THEN NULL ELSE AP_NET_TXN_M - AP_NET_TXN_L END AP_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(AP_NET_TXN_L,0)!=0 THEN (NVL(AP_NET_TXN_M,0)-NVL(AP_NET_TXN_L,0))/ABS(NVL(AP_NET_TXN_L,0)) ELSE NULL END AS AP_NET_TXN_M_RDIFF
        ,NVL(AP_NET_TXN_3M,0)AP_NET_TXN_3M
        ,CASE WHEN NVL(AP_NET_TXN_3M,0)=0 AND NVL(AP_NET_TXN_3ML,0)=0 THEN NULL ELSE AP_NET_TXN_3M - AP_NET_TXN_3ML END AP_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(AP_NET_TXN_3ML,0)!=0 THEN (NVL(AP_NET_TXN_3M,0)-NVL(AP_NET_TXN_3ML,0))/ABS(NVL(AP_NET_TXN_3ML,0)) ELSE NULL END AS AP_NET_TXN_3M_RDIFF
        ,NVL(AP_NET_TXN_6M,0)AP_NET_TXN_6M
        ,CASE WHEN NVL(AP_NET_TXN_6M,0)=0 AND NVL(AP_NET_TXN_6ML,0)=0 THEN NULL ELSE AP_NET_TXN_6M - AP_NET_TXN_6ML END AP_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(AP_NET_TXN_6ML,0)!=0 THEN (NVL(AP_NET_TXN_6M,0)-NVL(AP_NET_TXN_6ML,0))/ABS(NVL(AP_NET_TXN_6ML,0)) ELSE NULL END AS AP_NET_TXN_6M_RDIFF
        ,NVL(AP_NET_TXN_12M,0)AP_NET_TXN_12M
        ,CASE WHEN NVL(AP_NET_TXN_12M,0)=0 AND NVL(AP_NET_TXN_12ML,0)=0 THEN NULL ELSE AP_NET_TXN_12M - AP_NET_TXN_12ML END AP_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(AP_NET_TXN_12ML,0)!=0 THEN (NVL(AP_NET_TXN_12M,0)-NVL(AP_NET_TXN_12ML,0))/ABS(NVL(AP_NET_TXN_12ML,0)) ELSE NULL END AS AP_NET_TXN_12M_RDIFF
        ----所有商品周轉率
        ,CASE WHEN NVL(AP_AUM_M,0)!=0 THEN (NVL(AP_TXN_M,0)/NVL(AP_AUM_M,0)) ELSE NULL END AS AP_TURNOVER_M
        ,CASE WHEN NVL(AP_AUM_L,0)!=0 THEN (NVL(AP_TXN_L,0)/NVL(AP_AUM_L,0)) ELSE NULL END AS AP_TURNOVER_L
        ,CASE WHEN NVL(AP_AUM_3M,0)!=0 THEN (NVL(AP_TXN_3M,0)/NVL(AP_AUM_3M,0)) ELSE NULL END AS AP_TURNOVER_3M
        ,CASE WHEN NVL(AP_AUM_3ML,0)!=0 THEN (NVL(AP_TXN_3ML,0)/NVL(AP_AUM_3ML,0)) ELSE NULL END AS AP_TURNOVER_3ML
        ,CASE WHEN NVL(AP_AUM_6M,0)!=0 THEN (NVL(AP_TXN_6M,0)/NVL(AP_AUM_6M,0)) ELSE NULL END AS AP_TURNOVER_6M
        ,CASE WHEN NVL(AP_AUM_6ML,0)!=0 THEN (NVL(AP_TXN_6ML,0)/NVL(AP_AUM_6ML,0)) ELSE NULL END AS AP_TURNOVER_6ML
        ,CASE WHEN NVL(AP_AUM_12M,0)!=0 THEN (NVL(AP_TXN_12M,0)/NVL(AP_AUM_12M,0)) ELSE NULL END AS AP_TURNOVER_12M
        ,CASE WHEN NVL(AP_AUM_12ML,0)!=0 THEN (NVL(AP_TXN_12ML,0)/NVL(AP_AUM_12ML,0)) ELSE NULL END AS AP_TURNOVER_12ML
        ---經紀商品淨流
        ,NVL(BR_NET_TXN_M,0)BR_NET_TXN_M
        ,CASE WHEN NVL(BR_NET_TXN_M,0)=0 AND NVL(BR_NET_TXN_L,0)=0 THEN NULL ELSE BR_NET_TXN_M - BR_NET_TXN_L END BR_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(BR_NET_TXN_L,0)!=0 THEN (NVL(BR_NET_TXN_M,0)-NVL(BR_NET_TXN_L,0))/ABS(NVL(BR_NET_TXN_L,0)) ELSE NULL END AS BR_NET_TXN_M_RDIFF
        ,NVL(BR_NET_TXN_3M,0)BR_NET_TXN_3M
        ,CASE WHEN NVL(BR_NET_TXN_3M,0)=0 AND NVL(BR_NET_TXN_3ML,0)=0 THEN NULL ELSE BR_NET_TXN_3M - BR_NET_TXN_3ML END BR_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(BR_NET_TXN_3ML,0)!=0 THEN (NVL(BR_NET_TXN_3M,0)-NVL(BR_NET_TXN_3ML,0))/ABS(NVL(BR_NET_TXN_3ML,0)) ELSE NULL END AS BR_NET_TXN_3M_RDIFF
        ,NVL(BR_NET_TXN_6M,0)BR_NET_TXN_6M
        ,CASE WHEN NVL(BR_NET_TXN_6M,0)=0 AND NVL(BR_NET_TXN_6ML,0)=0 THEN NULL ELSE BR_NET_TXN_6M - BR_NET_TXN_6ML END BR_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(BR_NET_TXN_6ML,0)!=0 THEN (NVL(BR_NET_TXN_6M,0)-NVL(BR_NET_TXN_6ML,0))/ABS(NVL(BR_NET_TXN_6ML,0)) ELSE NULL END AS BR_NET_TXN_6M_RDIFF
        ,NVL(BR_NET_TXN_12M,0)BR_NET_TXN_12M
        ,CASE WHEN NVL(BR_NET_TXN_12M,0)=0 AND NVL(BR_NET_TXN_12ML,0)=0 THEN NULL ELSE BR_NET_TXN_12M - BR_NET_TXN_12ML END BR_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(BR_NET_TXN_12ML,0)!=0 THEN (NVL(BR_NET_TXN_12M,0)-NVL(BR_NET_TXN_12ML,0))/ABS(NVL(BR_NET_TXN_12ML,0)) ELSE NULL END AS BR_NET_TXN_12M_RDIFF
        ----經紀商品周轉率
        ,CASE WHEN NVL(BR_AUM_M,0)!=0 THEN (NVL(BR_TXN_M,0)/NVL(BR_AUM_M,0)) ELSE NULL END AS BR_TURNOVER_M
        ,CASE WHEN NVL(BR_AUM_L,0)!=0 THEN (NVL(BR_TXN_L,0)/NVL(BR_AUM_L,0)) ELSE NULL END AS BR_TURNOVER_L
        ,CASE WHEN NVL(BR_AUM_3M,0)!=0 THEN (NVL(BR_TXN_3M,0)/NVL(BR_AUM_3M,0)) ELSE NULL END AS BR_TURNOVER_3M
        ,CASE WHEN NVL(BR_AUM_3ML,0)!=0 THEN (NVL(BR_TXN_3ML,0)/NVL(BR_AUM_3ML,0)) ELSE NULL END AS BR_TURNOVER_3ML
        ,CASE WHEN NVL(BR_AUM_6M,0)!=0 THEN (NVL(BR_TXN_6M,0)/NVL(BR_AUM_6M,0)) ELSE NULL END AS BR_TURNOVER_6M
        ,CASE WHEN NVL(BR_AUM_6ML,0)!=0 THEN (NVL(BR_TXN_6ML,0)/NVL(BR_AUM_6ML,0)) ELSE NULL END AS BR_TURNOVER_6ML
        ,CASE WHEN NVL(BR_AUM_12M,0)!=0 THEN (NVL(BR_TXN_12M,0)/NVL(BR_AUM_12M,0)) ELSE NULL END AS BR_TURNOVER_12M
        ,CASE WHEN NVL(BR_AUM_12ML,0)!=0 THEN (NVL(BR_TXN_12ML,0)/NVL(BR_AUM_12ML,0)) ELSE NULL END AS BR_TURNOVER_12ML
        ---財管商品淨流
        ,NVL(FP_NET_TXN_M,0)FP_NET_TXN_M
        ,CASE WHEN NVL(FP_NET_TXN_M,0)=0 AND NVL(FP_NET_TXN_L,0)=0 THEN NULL ELSE FP_NET_TXN_M - FP_NET_TXN_L END FP_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FP_NET_TXN_L,0)!=0 THEN (NVL(FP_NET_TXN_M,0)-NVL(FP_NET_TXN_L,0))/ABS(NVL(FP_NET_TXN_L,0)) ELSE NULL END AS FP_NET_TXN_M_RDIFF
        ,NVL(FP_NET_TXN_3M,0)FP_NET_TXN_3M
        ,CASE WHEN NVL(FP_NET_TXN_3M,0)=0 AND NVL(FP_NET_TXN_3ML,0)=0 THEN NULL ELSE FP_NET_TXN_3M - FP_NET_TXN_3ML END FP_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FP_NET_TXN_3ML,0)!=0 THEN (NVL(FP_NET_TXN_3M,0)-NVL(FP_NET_TXN_3ML,0))/ABS(NVL(FP_NET_TXN_3ML,0)) ELSE NULL END AS FP_NET_TXN_3M_RDIFF
        ,NVL(FP_NET_TXN_6M,0)FP_NET_TXN_6M
        ,CASE WHEN NVL(FP_NET_TXN_6M,0)=0 AND NVL(FP_NET_TXN_6ML,0)=0 THEN NULL ELSE FP_NET_TXN_6M - FP_NET_TXN_6ML END FP_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FP_NET_TXN_6ML,0)!=0 THEN (NVL(FP_NET_TXN_6M,0)-NVL(FP_NET_TXN_6ML,0))/ABS(NVL(FP_NET_TXN_6ML,0)) ELSE NULL END AS FP_NET_TXN_6M_RDIFF
        ,NVL(FP_NET_TXN_12M,0)FP_NET_TXN_12M
        ,CASE WHEN NVL(FP_NET_TXN_12M,0)=0 AND NVL(FP_NET_TXN_12ML,0)=0 THEN NULL ELSE FP_NET_TXN_12M - FP_NET_TXN_12ML END FP_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FP_NET_TXN_12ML,0)!=0 THEN (NVL(FP_NET_TXN_12M,0)-NVL(FP_NET_TXN_12ML,0))/ABS(NVL(FP_NET_TXN_12ML,0)) ELSE NULL END AS FP_NET_TXN_12M_RDIFF
        ----財管商品周轉率
        ,CASE WHEN NVL(FP_AUM_M,0)!=0 THEN (NVL(FP_TXN_M,0)/NVL(FP_AUM_M,0)) ELSE NULL END AS FP_TURNOVER_M
        ,CASE WHEN NVL(FP_AUM_L,0)!=0 THEN (NVL(FP_TXN_L,0)/NVL(FP_AUM_L,0)) ELSE NULL END AS FP_TURNOVER_L
        ,CASE WHEN NVL(FP_AUM_3M,0)!=0 THEN (NVL(FP_TXN_3M,0)/NVL(FP_AUM_3M,0)) ELSE NULL END AS FP_TURNOVER_3M
        ,CASE WHEN NVL(FP_AUM_3ML,0)!=0 THEN (NVL(FP_TXN_3ML,0)/NVL(FP_AUM_3ML,0)) ELSE NULL END AS FP_TURNOVER_3ML
        ,CASE WHEN NVL(FP_AUM_6M,0)!=0 THEN (NVL(FP_TXN_6M,0)/NVL(FP_AUM_6M,0)) ELSE NULL END AS FP_TURNOVER_6M
        ,CASE WHEN NVL(FP_AUM_6ML,0)!=0 THEN (NVL(FP_TXN_6ML,0)/NVL(FP_AUM_6ML,0)) ELSE NULL END AS FP_TURNOVER_6ML
        ,CASE WHEN NVL(FP_AUM_12M,0)!=0 THEN (NVL(FP_TXN_12M,0)/NVL(FP_AUM_12M,0)) ELSE NULL END AS FP_TURNOVER_12M
        ,CASE WHEN NVL(FP_AUM_12ML,0)!=0 THEN (NVL(FP_TXN_12ML,0)/NVL(FP_AUM_12ML,0)) ELSE NULL END AS FP_TURNOVER_12ML
        ---台幣淨流
        ,NVL(TWD_NET_TXN_M,0)TWD_NET_TXN_M
        ,CASE WHEN NVL(TWD_NET_TXN_M,0)=0 AND NVL(TWD_NET_TXN_L,0)=0 THEN NULL ELSE TWD_NET_TXN_M - TWD_NET_TXN_L END TWD_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(TWD_NET_TXN_L,0)!=0 THEN (NVL(TWD_NET_TXN_M,0)-NVL(TWD_NET_TXN_L,0))/ABS(NVL(TWD_NET_TXN_L,0)) ELSE NULL END AS TWD_NET_TXN_M_RDIFF
        ,NVL(TWD_NET_TXN_3M,0)TWD_NET_TXN_3M
        ,CASE WHEN NVL(TWD_NET_TXN_3M,0)=0 AND NVL(TWD_NET_TXN_3ML,0)=0 THEN NULL ELSE TWD_NET_TXN_3M - TWD_NET_TXN_3ML END TWD_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(TWD_NET_TXN_3ML,0)!=0 THEN (NVL(TWD_NET_TXN_3M,0)-NVL(TWD_NET_TXN_3ML,0))/ABS(NVL(TWD_NET_TXN_3ML,0)) ELSE NULL END AS TWD_NET_TXN_3M_RDIFF
        ,NVL(TWD_NET_TXN_6M,0)TWD_NET_TXN_6M
        ,CASE WHEN NVL(TWD_NET_TXN_6M,0)=0 AND NVL(TWD_NET_TXN_6ML,0)=0 THEN NULL ELSE TWD_NET_TXN_6M - TWD_NET_TXN_6ML END TWD_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(TWD_NET_TXN_6ML,0)!=0 THEN (NVL(TWD_NET_TXN_6M,0)-NVL(TWD_NET_TXN_6ML,0))/ABS(NVL(TWD_NET_TXN_6ML,0)) ELSE NULL END AS TWD_NET_TXN_6M_RDIFF
        ,NVL(TWD_NET_TXN_12M,0)TWD_NET_TXN_12M
        ,CASE WHEN NVL(TWD_NET_TXN_12M,0)=0 AND NVL(TWD_NET_TXN_12ML,0)=0 THEN NULL ELSE TWD_NET_TXN_12M - TWD_NET_TXN_12ML END TWD_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(TWD_NET_TXN_12ML,0)!=0 THEN (NVL(TWD_NET_TXN_12M,0)-NVL(TWD_NET_TXN_12ML,0))/ABS(NVL(TWD_NET_TXN_12ML,0)) ELSE NULL END AS TWD_NET_TXN_12M_RDIFF
        ----台幣周轉率
        ,CASE WHEN NVL(TWD_AUM_M,0)!=0 THEN (NVL(TWD_TXN_M,0)/NVL(TWD_AUM_M,0)) ELSE NULL END AS TWD_TURNOVER_M
        ,CASE WHEN NVL(TWD_AUM_L,0)!=0 THEN (NVL(TWD_TXN_L,0)/NVL(TWD_AUM_L,0)) ELSE NULL END AS TWD_TURNOVER_L
        ,CASE WHEN NVL(TWD_AUM_3M,0)!=0 THEN (NVL(TWD_TXN_3M,0)/NVL(TWD_AUM_3M,0)) ELSE NULL END AS TWD_TURNOVER_3M
        ,CASE WHEN NVL(TWD_AUM_3ML,0)!=0 THEN (NVL(TWD_TXN_3ML,0)/NVL(TWD_AUM_3ML,0)) ELSE NULL END AS TWD_TURNOVER_3ML
        ,CASE WHEN NVL(TWD_AUM_6M,0)!=0 THEN (NVL(TWD_TXN_6M,0)/NVL(TWD_AUM_6M,0)) ELSE NULL END AS TWD_TURNOVER_6M
        ,CASE WHEN NVL(TWD_AUM_6ML,0)!=0 THEN (NVL(TWD_TXN_6ML,0)/NVL(TWD_AUM_6ML,0)) ELSE NULL END AS TWD_TURNOVER_6ML
        ,CASE WHEN NVL(TWD_AUM_12M,0)!=0 THEN (NVL(TWD_TXN_12M,0)/NVL(TWD_AUM_12M,0)) ELSE NULL END AS TWD_TURNOVER_12M
        ,CASE WHEN NVL(TWD_AUM_12ML,0)!=0 THEN (NVL(TWD_TXN_12ML,0)/NVL(TWD_AUM_12ML,0)) ELSE NULL END AS TWD_TURNOVER_12ML
        ---美金淨流
        ,NVL(USD_NET_TXN_M,0)USD_NET_TXN_M
        ,CASE WHEN NVL(USD_NET_TXN_M,0)=0 AND NVL(USD_NET_TXN_L,0)=0 THEN NULL ELSE USD_NET_TXN_M - USD_NET_TXN_L END USD_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(USD_NET_TXN_L,0)!=0 THEN (NVL(USD_NET_TXN_M,0)-NVL(USD_NET_TXN_L,0))/ABS(NVL(USD_NET_TXN_L,0)) ELSE NULL END AS USD_NET_TXN_M_RDIFF
        ,NVL(USD_NET_TXN_3M,0)USD_NET_TXN_3M
        ,CASE WHEN NVL(USD_NET_TXN_3M,0)=0 AND NVL(USD_NET_TXN_3ML,0)=0 THEN NULL ELSE USD_NET_TXN_3M - USD_NET_TXN_3ML END USD_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(USD_NET_TXN_3ML,0)!=0 THEN (NVL(USD_NET_TXN_3M,0)-NVL(USD_NET_TXN_3ML,0))/ABS(NVL(USD_NET_TXN_3ML,0)) ELSE NULL END AS USD_NET_TXN_3M_RDIFF
        ,NVL(USD_NET_TXN_6M,0)USD_NET_TXN_6M
        ,CASE WHEN NVL(USD_NET_TXN_6M,0)=0 AND NVL(USD_NET_TXN_6ML,0)=0 THEN NULL ELSE USD_NET_TXN_6M - USD_NET_TXN_6ML END USD_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(USD_NET_TXN_6ML,0)!=0 THEN (NVL(USD_NET_TXN_6M,0)-NVL(USD_NET_TXN_6ML,0))/ABS(NVL(USD_NET_TXN_6ML,0)) ELSE NULL END AS USD_NET_TXN_6M_RDIFF
        ,NVL(USD_NET_TXN_12M,0)USD_NET_TXN_12M
        ,CASE WHEN NVL(USD_NET_TXN_12M,0)=0 AND NVL(USD_NET_TXN_12ML,0)=0 THEN NULL ELSE USD_NET_TXN_12M - USD_NET_TXN_12ML END USD_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(USD_NET_TXN_12ML,0)!=0 THEN (NVL(USD_NET_TXN_12M,0)-NVL(USD_NET_TXN_12ML,0))/ABS(NVL(USD_NET_TXN_12ML,0)) ELSE NULL END AS USD_NET_TXN_12M_RDIFF
        ----美金周轉率
        ,CASE WHEN NVL(USD_AUM_M,0)!=0 THEN (NVL(USD_TXN_M,0)/NVL(USD_AUM_M,0)) ELSE NULL END AS USD_TURNOVER_M
        ,CASE WHEN NVL(USD_AUM_L,0)!=0 THEN (NVL(USD_TXN_L,0)/NVL(USD_AUM_L,0)) ELSE NULL END AS USD_TURNOVER_L
        ,CASE WHEN NVL(USD_AUM_3M,0)!=0 THEN (NVL(USD_TXN_3M,0)/NVL(USD_AUM_3M,0)) ELSE NULL END AS USD_TURNOVER_3M
        ,CASE WHEN NVL(USD_AUM_3ML,0)!=0 THEN (NVL(USD_TXN_3ML,0)/NVL(USD_AUM_3ML,0)) ELSE NULL END AS USD_TURNOVER_3ML
        ,CASE WHEN NVL(USD_AUM_6M,0)!=0 THEN (NVL(USD_TXN_6M,0)/NVL(USD_AUM_6M,0)) ELSE NULL END AS USD_TURNOVER_6M
        ,CASE WHEN NVL(USD_AUM_6ML,0)!=0 THEN (NVL(USD_TXN_6ML,0)/NVL(USD_AUM_6ML,0)) ELSE NULL END AS USD_TURNOVER_6ML
        ,CASE WHEN NVL(USD_AUM_12M,0)!=0 THEN (NVL(USD_TXN_12M,0)/NVL(USD_AUM_12M,0)) ELSE NULL END AS USD_TURNOVER_12M
        ,CASE WHEN NVL(USD_AUM_12ML,0)!=0 THEN (NVL(USD_TXN_12ML,0)/NVL(USD_AUM_12ML,0)) ELSE NULL END AS USD_TURNOVER_12ML
        ---其他幣淨流
        ,NVL(OD_NET_TXN_M,0)OD_NET_TXN_M
        ,CASE WHEN NVL(OD_NET_TXN_M,0)=0 AND NVL(OD_NET_TXN_L,0)=0 THEN NULL ELSE OD_NET_TXN_M - OD_NET_TXN_L END OD_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(OD_NET_TXN_L,0)!=0 THEN (NVL(OD_NET_TXN_M,0)-NVL(OD_NET_TXN_L,0))/ABS(NVL(OD_NET_TXN_L,0)) ELSE NULL END AS OD_NET_TXN_M_RDIFF
        ,NVL(OD_NET_TXN_3M,0)OD_NET_TXN_3M
        ,CASE WHEN NVL(OD_NET_TXN_3M,0)=0 AND NVL(OD_NET_TXN_3ML,0)=0 THEN NULL ELSE OD_NET_TXN_3M - OD_NET_TXN_3ML END OD_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(OD_NET_TXN_3ML,0)!=0 THEN (NVL(OD_NET_TXN_3M,0)-NVL(OD_NET_TXN_3ML,0))/ABS(NVL(OD_NET_TXN_3ML,0)) ELSE NULL END AS OD_NET_TXN_3M_RDIFF
        ,NVL(OD_NET_TXN_6M,0)OD_NET_TXN_6M
        ,CASE WHEN NVL(OD_NET_TXN_6M,0)=0 AND NVL(OD_NET_TXN_6ML,0)=0 THEN NULL ELSE OD_NET_TXN_6M - OD_NET_TXN_6ML END OD_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(OD_NET_TXN_6ML,0)!=0 THEN (NVL(OD_NET_TXN_6M,0)-NVL(OD_NET_TXN_6ML,0))/ABS(NVL(OD_NET_TXN_6ML,0)) ELSE NULL END AS OD_NET_TXN_6M_RDIFF
        ,NVL(OD_NET_TXN_12M,0)OD_NET_TXN_12M
        ,CASE WHEN NVL(OD_NET_TXN_12M,0)=0 AND NVL(OD_NET_TXN_12ML,0)=0 THEN NULL ELSE OD_NET_TXN_12M - OD_NET_TXN_12ML END OD_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(OD_NET_TXN_12ML,0)!=0 THEN (NVL(OD_NET_TXN_12M,0)-NVL(OD_NET_TXN_12ML,0))/ABS(NVL(OD_NET_TXN_12ML,0)) ELSE NULL END AS OD_NET_TXN_12M_RDIFF
        ----其他幣周轉率
        ,CASE WHEN NVL(OD_AUM_M,0)!=0 THEN (NVL(OD_TXN_M,0)/NVL(OD_AUM_M,0)) ELSE NULL END AS OD_TURNOVER_M
        ,CASE WHEN NVL(OD_AUM_L,0)!=0 THEN (NVL(OD_TXN_L,0)/NVL(OD_AUM_L,0)) ELSE NULL END AS OD_TURNOVER_L
        ,CASE WHEN NVL(OD_AUM_3M,0)!=0 THEN (NVL(OD_TXN_3M,0)/NVL(OD_AUM_3M,0)) ELSE NULL END AS OD_TURNOVER_3M
        ,CASE WHEN NVL(OD_AUM_3ML,0)!=0 THEN (NVL(OD_TXN_3ML,0)/NVL(OD_AUM_3ML,0)) ELSE NULL END AS OD_TURNOVER_3ML
        ,CASE WHEN NVL(OD_AUM_6M,0)!=0 THEN (NVL(OD_TXN_6M,0)/NVL(OD_AUM_6M,0)) ELSE NULL END AS OD_TURNOVER_6M
        ,CASE WHEN NVL(OD_AUM_6ML,0)!=0 THEN (NVL(OD_TXN_6ML,0)/NVL(OD_AUM_6ML,0)) ELSE NULL END AS OD_TURNOVER_6ML
        ,CASE WHEN NVL(OD_AUM_12M,0)!=0 THEN (NVL(OD_TXN_12M,0)/NVL(OD_AUM_12M,0)) ELSE NULL END AS OD_TURNOVER_12M
        ,CASE WHEN NVL(OD_AUM_12ML,0)!=0 THEN (NVL(OD_TXN_12ML,0)/NVL(OD_AUM_12ML,0)) ELSE NULL END AS OD_TURNOVER_12ML
    FROM DS_SEC.CF_CUSTID A
    LEFT JOIN(
        SELECT PARTY_ID
            ------所有商品 AP
            ,SUM(CASE WHEN TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)AP_NET_TXN_M
            ,SUM(CASE WHEN TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)AP_NET_TXN_L
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)AP_NET_TXN_3M
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)AP_NET_TXN_3ML
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)AP_NET_TXN_6M
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)AP_NET_TXN_6ML
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)AP_NET_TXN_12M
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)AP_NET_TXN_12ML
            ,SUM(CASE WHEN TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)AP_TXN_M
            ,SUM(CASE WHEN TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)AP_TXN_L
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)AP_TXN_3M
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)AP_TXN_3ML
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)AP_TXN_6M
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)AP_TXN_6ML
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)AP_TXN_12M
            ,SUM(CASE WHEN TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)AP_TXN_12ML
            
            ------經紀商品 BR
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)BR_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)BR_NET_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)BR_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)BR_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)BR_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)BR_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)BR_NET_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)BR_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)BR_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)BR_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)BR_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)BR_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)BR_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)BR_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)BR_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110','210','3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)BR_TXN_12ML
            
            ------財管商品 FP
            
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','230','240','420','540','6L0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','230','240','420','540','6L0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FP_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','230','240','420','540','6L0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','230','240','420','540','6L0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FP_NET_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','230','240','420','540','6L0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
