            -SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OD_NET_TXN_6ML
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OD_NET_TXN_12M
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OD_NET_TXN_12ML
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)OD_TXN_M
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OD_TXN_L
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OD_TXN_3M
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OD_TXN_3ML
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OD_TXN_6M
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OD_TXN_6ML
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OD_TXN_12M
            ,SUM(CASE WHEN CURRENCY_CODE NOT IN('USD','TWD') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OD_TXN_12ML

        FROM TEMP4TXN A
        GROUP BY PARTY_ID
    )B ON A.CUSTOMER_ID = B.PARTY_ID
    LEFT JOIN TEMP4AUM C ON A.CUSTOMER_ID = C.CUSTOMER_ID
    WHERE A.YYYYMM = :ym
);
