    ,ROUND(CASE WHEN NVL(FO_TURNOVER_12M,0)=0 AND NVL(FO_TURNOVER_12ML,0)=0 THEN NULL ELSE FO_TURNOVER_12M - FO_TURNOVER_12ML END,4) FO_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FO_TURNOVER_12ML,0)!=0 THEN (NVL(FO_TURNOVER_12M,0)/NVL(FO_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FO_TURNOVER_12M_RDIFF
FROM(
    SELECT DISTINCT A.CUSTOMER_ID
        ,A.YYYYMM
        ---台股淨流
        ,NVL(ST_NET_TXN_M,0)ST_NET_TXN_M
        ,CASE WHEN NVL(ST_NET_TXN_M,0)=0 AND NVL(ST_NET_TXN_L,0)=0 THEN NULL ELSE ST_NET_TXN_M - ST_NET_TXN_L END ST_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(ST_NET_TXN_L,0)!=0 THEN (NVL(ST_NET_TXN_M,0)-NVL(ST_NET_TXN_L,0))/ABS(NVL(ST_NET_TXN_L,0)) ELSE NULL END AS ST_NET_TXN_M_RDIFF
        ,NVL(ST_NET_TXN_3M,0)ST_NET_TXN_3M
        ,CASE WHEN NVL(ST_NET_TXN_3M,0)=0 AND NVL(ST_NET_TXN_3ML,0)=0 THEN NULL ELSE ST_NET_TXN_3M - ST_NET_TXN_3ML END ST_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(ST_NET_TXN_3ML,0)!=0 THEN (NVL(ST_NET_TXN_3M,0)-NVL(ST_NET_TXN_3ML,0))/ABS(NVL(ST_NET_TXN_3ML,0)) ELSE NULL END AS ST_NET_TXN_3M_RDIFF
        ,NVL(ST_NET_TXN_6M,0)ST_NET_TXN_6M
        ,CASE WHEN NVL(ST_NET_TXN_6M,0)=0 AND NVL(ST_NET_TXN_6ML,0)=0 THEN NULL ELSE ST_NET_TXN_6M - ST_NET_TXN_6ML END ST_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(ST_NET_TXN_6ML,0)!=0 THEN (NVL(ST_NET_TXN_6M,0)-NVL(ST_NET_TXN_6ML,0))/ABS(NVL(ST_NET_TXN_6ML,0)) ELSE NULL END AS ST_NET_TXN_6M_RDIFF
        ,NVL(ST_NET_TXN_12M,0)ST_NET_TXN_12M
        ,CASE WHEN NVL(ST_NET_TXN_12M,0)=0 AND NVL(ST_NET_TXN_12ML,0)=0 THEN NULL ELSE ST_NET_TXN_12M - ST_NET_TXN_12ML END ST_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(ST_NET_TXN_12ML,0)!=0 THEN (NVL(ST_NET_TXN_12M,0)-NVL(ST_NET_TXN_12ML,0))/ABS(NVL(ST_NET_TXN_12ML,0)) ELSE NULL END AS ST_NET_TXN_12M_RDIFF
        ----台股周轉率
        ,CASE WHEN NVL(ST_AUM_M,0)!=0 THEN (NVL(ST_TXN_M,0)/NVL(ST_AUM_M,0)) ELSE NULL END AS ST_TURNOVER_M
        ,CASE WHEN NVL(ST_AUM_L,0)!=0 THEN (NVL(ST_TXN_L,0)/NVL(ST_AUM_L,0)) ELSE NULL END AS ST_TURNOVER_L
        ,CASE WHEN NVL(ST_AUM_3M,0)!=0 THEN (NVL(ST_TXN_3M,0)/NVL(ST_AUM_3M,0)) ELSE NULL END AS ST_TURNOVER_3M
        ,CASE WHEN NVL(ST_AUM_3ML,0)!=0 THEN (NVL(ST_TXN_3ML,0)/NVL(ST_AUM_3ML,0)) ELSE NULL END AS ST_TURNOVER_3ML
        ,CASE WHEN NVL(ST_AUM_6M,0)!=0 THEN (NVL(ST_TXN_6M,0)/NVL(ST_AUM_6M,0)) ELSE NULL END AS ST_TURNOVER_6M
        ,CASE WHEN NVL(ST_AUM_6ML,0)!=0 THEN (NVL(ST_TXN_6ML,0)/NVL(ST_AUM_6ML,0)) ELSE NULL END AS ST_TURNOVER_6ML
        ,CASE WHEN NVL(ST_AUM_12M,0)!=0 THEN (NVL(ST_TXN_12M,0)/NVL(ST_AUM_12M,0)) ELSE NULL END AS ST_TURNOVER_12M
        ,CASE WHEN NVL(ST_AUM_12ML,0)!=0 THEN (NVL(ST_TXN_12ML,0)/NVL(ST_AUM_12ML,0)) ELSE NULL END AS ST_TURNOVER_12ML
        ---海外股淨流
        ,NVL(FS_NET_TXN_M,0)FS_NET_TXN_M
        ,CASE WHEN NVL(FS_NET_TXN_M,0)=0 AND NVL(FS_NET_TXN_L,0)=0 THEN NULL ELSE FS_NET_TXN_M - FS_NET_TXN_L END FS_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FS_NET_TXN_L,0)!=0 THEN (NVL(FS_NET_TXN_M,0)-NVL(FS_NET_TXN_L,0))/ABS(NVL(FS_NET_TXN_L,0)) ELSE NULL END AS FS_NET_TXN_M_RDIFF
        ,NVL(FS_NET_TXN_3M,0)FS_NET_TXN_3M
        ,CASE WHEN NVL(FS_NET_TXN_3M,0)=0 AND NVL(FS_NET_TXN_3ML,0)=0 THEN NULL ELSE FS_NET_TXN_3M - FS_NET_TXN_3ML END FS_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FS_NET_TXN_3ML,0)!=0 THEN (NVL(FS_NET_TXN_3M,0)-NVL(FS_NET_TXN_3ML,0))/ABS(NVL(FS_NET_TXN_3ML,0)) ELSE NULL END AS FS_NET_TXN_3M_RDIFF
        ,NVL(FS_NET_TXN_6M,0)FS_NET_TXN_6M
        ,CASE WHEN NVL(FS_NET_TXN_6M,0)=0 AND NVL(FS_NET_TXN_6ML,0)=0 THEN NULL ELSE FS_NET_TXN_6M - FS_NET_TXN_6ML END FS_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FS_NET_TXN_6ML,0)!=0 THEN (NVL(FS_NET_TXN_6M,0)-NVL(FS_NET_TXN_6ML,0))/ABS(NVL(FS_NET_TXN_6ML,0)) ELSE NULL END AS FS_NET_TXN_6M_RDIFF
        ,NVL(FS_NET_TXN_12M,0)FS_NET_TXN_12M
        ,CASE WHEN NVL(FS_NET_TXN_12M,0)=0 AND NVL(FS_NET_TXN_12ML,0)=0 THEN NULL ELSE FS_NET_TXN_12M - FS_NET_TXN_12ML END FS_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FS_NET_TXN_12ML,0)!=0 THEN (NVL(FS_NET_TXN_12M,0)-NVL(FS_NET_TXN_12ML,0))/ABS(NVL(FS_NET_TXN_12ML,0)) ELSE NULL END AS FS_NET_TXN_12M_RDIFF
        ----海外股周轉率
        ,CASE WHEN NVL(FS_AUM_M,0)!=0 THEN (NVL(FS_TXN_M,0)/NVL(FS_AUM_M,0)) ELSE NULL END AS FS_TURNOVER_M
        ,CASE WHEN NVL(FS_AUM_L,0)!=0 THEN (NVL(FS_TXN_L,0)/NVL(FS_AUM_L,0)) ELSE NULL END AS FS_TURNOVER_L
        ,CASE WHEN NVL(FS_AUM_3M,0)!=0 THEN (NVL(FS_TXN_3M,0)/NVL(FS_AUM_3M,0)) ELSE NULL END AS FS_TURNOVER_3M
        ,CASE WHEN NVL(FS_AUM_3ML,0)!=0 THEN (NVL(FS_TXN_3ML,0)/NVL(FS_AUM_3ML,0)) ELSE NULL END AS FS_TURNOVER_3ML
        ,CASE WHEN NVL(FS_AUM_6M,0)!=0 THEN (NVL(FS_TXN_6M,0)/NVL(FS_AUM_6M,0)) ELSE NULL END AS FS_TURNOVER_6M
        ,CASE WHEN NVL(FS_AUM_6ML,0)!=0 THEN (NVL(FS_TXN_6ML,0)/NVL(FS_AUM_6ML,0)) ELSE NULL END AS FS_TURNOVER_6ML
        ,CASE WHEN NVL(FS_AUM_12M,0)!=0 THEN (NVL(FS_TXN_12M,0)/NVL(FS_AUM_12M,0)) ELSE NULL END AS FS_TURNOVER_12M
        ,CASE WHEN NVL(FS_AUM_12ML,0)!=0 THEN (NVL(FS_TXN_12ML,0)/NVL(FS_AUM_12ML,0)) ELSE NULL END AS FS_TURNOVER_12ML
        ---基金淨流
        ,NVL(FD_NET_TXN_M,0)FD_NET_TXN_M
        ,CASE WHEN NVL(FD_NET_TXN_M,0)=0 AND NVL(FD_NET_TXN_L,0)=0 THEN NULL ELSE FD_NET_TXN_M - FD_NET_TXN_L END FD_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FD_NET_TXN_L,0)!=0 THEN (NVL(FD_NET_TXN_M,0)-NVL(FD_NET_TXN_L,0))/ABS(NVL(FD_NET_TXN_L,0)) ELSE NULL END AS FD_NET_TXN_M_RDIFF
        ,NVL(FD_NET_TXN_3M,0)FD_NET_TXN_3M
        ,CASE WHEN NVL(FD_NET_TXN_3M,0)=0 AND NVL(FD_NET_TXN_3ML,0)=0 THEN NULL ELSE FD_NET_TXN_3M - FD_NET_TXN_3ML END FD_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FD_NET_TXN_3ML,0)!=0 THEN (NVL(FD_NET_TXN_3M,0)-NVL(FD_NET_TXN_3ML,0))/ABS(NVL(FD_NET_TXN_3ML,0)) ELSE NULL END AS FD_NET_TXN_3M_RDIFF
        ,NVL(FD_NET_TXN_6M,0)FD_NET_TXN_6M
        ,CASE WHEN NVL(FD_NET_TXN_6M,0)=0 AND NVL(FD_NET_TXN_6ML,0)=0 THEN NULL ELSE FD_NET_TXN_6M - FD_NET_TXN_6ML END FD_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FD_NET_TXN_6ML,0)!=0 THEN (NVL(FD_NET_TXN_6M,0)-NVL(FD_NET_TXN_6ML,0))/ABS(NVL(FD_NET_TXN_6ML,0)) ELSE NULL END AS FD_NET_TXN_6M_RDIFF
        ,NVL(FD_NET_TXN_12M,0)FD_NET_TXN_12M
        ,CASE WHEN NVL(FD_NET_TXN_12M,0)=0 AND NVL(FD_NET_TXN_12ML,0)=0 THEN NULL ELSE FD_NET_TXN_12M - FD_NET_TXN_12ML END FD_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FD_NET_TXN_12ML,0)!=0 THEN (NVL(FD_NET_TXN_12M,0)-NVL(FD_NET_TXN_12ML,0))/ABS(NVL(FD_NET_TXN_12ML,0)) ELSE NULL END AS FD_NET_TXN_12M_RDIFF
        ----基金周轉率
        ,CASE WHEN NVL(FD_AUM_M,0)!=0 THEN (NVL(FD_TXN_M,0)/NVL(FD_AUM_M,0)) ELSE NULL END AS FD_TURNOVER_M
        ,CASE WHEN NVL(FD_AUM_L,0)!=0 THEN (NVL(FD_TXN_L,0)/NVL(FD_AUM_L,0)) ELSE NULL END AS FD_TURNOVER_L
        ,CASE WHEN NVL(FD_AUM_3M,0)!=0 THEN (NVL(FD_TXN_3M,0)/NVL(FD_AUM_3M,0)) ELSE NULL END AS FD_TURNOVER_3M
        ,CASE WHEN NVL(FD_AUM_3ML,0)!=0 THEN (NVL(FD_TXN_3ML,0)/NVL(FD_AUM_3ML,0)) ELSE NULL END AS FD_TURNOVER_3ML
        ,CASE WHEN NVL(FD_AUM_6M,0)!=0 THEN (NVL(FD_TXN_6M,0)/NVL(FD_AUM_6M,0)) ELSE NULL END AS FD_TURNOVER_6M
        ,CASE WHEN NVL(FD_AUM_6ML,0)!=0 THEN (NVL(FD_TXN_6ML,0)/NVL(FD_AUM_6ML,0)) ELSE NULL END AS FD_TURNOVER_6ML
        ,CASE WHEN NVL(FD_AUM_12M,0)!=0 THEN (NVL(FD_TXN_12M,0)/NVL(FD_AUM_12M,0)) ELSE NULL END AS FD_TURNOVER_12M
        ,CASE WHEN NVL(FD_AUM_12ML,0)!=0 THEN (NVL(FD_TXN_12ML,0)/NVL(FD_AUM_12ML,0)) ELSE NULL END AS FD_TURNOVER_12ML
        ---海外債淨流
        ,NVL(FB_NET_TXN_M,0)FB_NET_TXN_M
        ,CASE WHEN NVL(FB_NET_TXN_M,0)=0 AND NVL(FB_NET_TXN_L,0)=0 THEN NULL ELSE FB_NET_TXN_M - FB_NET_TXN_L END FB_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FB_NET_TXN_L,0)!=0 THEN (NVL(FB_NET_TXN_M,0)-NVL(FB_NET_TXN_L,0))/ABS(NVL(FB_NET_TXN_L,0)) ELSE NULL END AS FB_NET_TXN_M_RDIFF
        ,NVL(FB_NET_TXN_3M,0)FB_NET_TXN_3M
        ,CASE WHEN NVL(FB_NET_TXN_3M,0)=0 AND NVL(FB_NET_TXN_3ML,0)=0 THEN NULL ELSE FB_NET_TXN_3M - FB_NET_TXN_3ML END FB_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FB_NET_TXN_3ML,0)!=0 THEN (NVL(FB_NET_TXN_3M,0)-NVL(FB_NET_TXN_3ML,0))/ABS(NVL(FB_NET_TXN_3ML,0)) ELSE NULL END AS FB_NET_TXN_3M_RDIFF
        ,NVL(FB_NET_TXN_6M,0)FB_NET_TXN_6M
        ,CASE WHEN NVL(FB_NET_TXN_6M,0)=0 AND NVL(FB_NET_TXN_6ML,0)=0 THEN NULL ELSE FB_NET_TXN_6M - FB_NET_TXN_6ML END FB_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FB_NET_TXN_6ML,0)!=0 THEN (NVL(FB_NET_TXN_6M,0)-NVL(FB_NET_TXN_6ML,0))/ABS(NVL(FB_NET_TXN_6ML,0)) ELSE NULL END AS FB_NET_TXN_6M_RDIFF
        ,NVL(FB_NET_TXN_12M,0)FB_NET_TXN_12M
        ,CASE WHEN NVL(FB_NET_TXN_12M,0)=0 AND NVL(FB_NET_TXN_12ML,0)=0 THEN NULL ELSE FB_NET_TXN_12M - FB_NET_TXN_12ML END FB_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FB_NET_TXN_12ML,0)!=0 THEN (NVL(FB_NET_TXN_12M,0)-NVL(FB_NET_TXN_12ML,0))/ABS(NVL(FB_NET_TXN_12ML,0)) ELSE NULL END AS FB_NET_TXN_12M_RDIFF
        ----海外債周轉率
        ,CASE WHEN NVL(FB_AUM_M,0)!=0 THEN (NVL(FB_TXN_M,0)/NVL(FB_AUM_M,0)) ELSE NULL END AS FB_TURNOVER_M
        ,CASE WHEN NVL(FB_AUM_L,0)!=0 THEN (NVL(FB_TXN_L,0)/NVL(FB_AUM_L,0)) ELSE NULL END AS FB_TURNOVER_L
        ,CASE WHEN NVL(FB_AUM_3M,0)!=0 THEN (NVL(FB_TXN_3M,0)/NVL(FB_AUM_3M,0)) ELSE NULL END AS FB_TURNOVER_3M
        ,CASE WHEN NVL(FB_AUM_3ML,0)!=0 THEN (NVL(FB_TXN_3ML,0)/NVL(FB_AUM_3ML,0)) ELSE NULL END AS FB_TURNOVER_3ML
        ,CASE WHEN NVL(FB_AUM_6M,0)!=0 THEN (NVL(FB_TXN_6M,0)/NVL(FB_AUM_6M,0)) ELSE NULL END AS FB_TURNOVER_6M
        ,CASE WHEN NVL(FB_AUM_6ML,0)!=0 THEN (NVL(FB_TXN_6ML,0)/NVL(FB_AUM_6ML,0)) ELSE NULL END AS FB_TURNOVER_6ML
        ,CASE WHEN NVL(FB_AUM_12M,0)!=0 THEN (NVL(FB_TXN_12M,0)/NVL(FB_AUM_12M,0)) ELSE NULL END AS FB_TURNOVER_12M
        ,CASE WHEN NVL(FB_AUM_12ML,0)!=0 THEN (NVL(FB_TXN_12ML,0)/NVL(FB_AUM_12ML,0)) ELSE NULL END AS FB_TURNOVER_12ML
        ---結構型商品淨流
        ,NVL(SN_NET_TXN_M,0)SN_NET_TXN_M
        ,CASE WHEN NVL(SN_NET_TXN_M,0)=0 AND NVL(SN_NET_TXN_L,0)=0 THEN NULL ELSE SN_NET_TXN_M - SN_NET_TXN_L END SN_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(SN_NET_TXN_L,0)!=0 THEN (NVL(SN_NET_TXN_M,0)-NVL(SN_NET_TXN_L,0))/ABS(NVL(SN_NET_TXN_L,0)) ELSE NULL END AS SN_NET_TXN_M_RDIFF
        ,NVL(SN_NET_TXN_3M,0)SN_NET_TXN_3M
        ,CASE WHEN NVL(SN_NET_TXN_3M,0)=0 AND NVL(SN_NET_TXN_3ML,0)=0 THEN NULL ELSE SN_NET_TXN_3M - SN_NET_TXN_3ML END SN_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(SN_NET_TXN_3ML,0)!=0 THEN (NVL(SN_NET_TXN_3M,0)-NVL(SN_NET_TXN_3ML,0))/ABS(NVL(SN_NET_TXN_3ML,0)) ELSE NULL END AS SN_NET_TXN_3M_RDIFF
        ,NVL(SN_NET_TXN_6M,0)SN_NET_TXN_6M
        ,CASE WHEN NVL(SN_NET_TXN_6M,0)=0 AND NVL(SN_NET_TXN_6ML,0)=0 THEN NULL ELSE SN_NET_TXN_6M - SN_NET_TXN_6ML END SN_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(SN_NET_TXN_6ML,0)!=0 THEN (NVL(SN_NET_TXN_6M,0)-NVL(SN_NET_TXN_6ML,0))/ABS(NVL(SN_NET_TXN_6ML,0)) ELSE NULL END AS SN_NET_TXN_6M_RDIFF
        ,NVL(SN_NET_TXN_12M,0)SN_NET_TXN_12M
        ,CASE WHEN NVL(SN_NET_TXN_12M,0)=0 AND NVL(SN_NET_TXN_12ML,0)=0 THEN NULL ELSE SN_NET_TXN_12M - SN_NET_TXN_12ML END SN_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(SN_NET_TXN_12ML,0)!=0 THEN (NVL(SN_NET_TXN_12M,0)-NVL(SN_NET_TXN_12ML,0))/ABS(NVL(SN_NET_TXN_12ML,0)) ELSE NULL END AS SN_NET_TXN_12M_RDIFF
        ----結構型商品周轉率
        ,CASE WHEN NVL(SN_AUM_M,0)!=0 THEN (NVL(SN_TXN_M,0)/NVL(SN_AUM_M,0)) ELSE NULL END AS SN_TURNOVER_M
        ,CASE WHEN NVL(SN_AUM_L,0)!=0 THEN (NVL(SN_TXN_L,0)/NVL(SN_AUM_L,0)) ELSE NULL END AS SN_TURNOVER_L
        ,CASE WHEN NVL(SN_AUM_3M,0)!=0 THEN (NVL(SN_TXN_3M,0)/NVL(SN_AUM_3M,0)) ELSE NULL END AS SN_TURNOVER_3M
        ,CASE WHEN NVL(SN_AUM_3ML,0)!=0 THEN (NVL(SN_TXN_3ML,0)/NVL(SN_AUM_3ML,0)) ELSE NULL END AS SN_TURNOVER_3ML
        ,CASE WHEN NVL(SN_AUM_6M,0)!=0 THEN (NVL(SN_TXN_6M,0)/NVL(SN_AUM_6M,0)) ELSE NULL END AS SN_TURNOVER_6M
        ,CASE WHEN NVL(SN_AUM_6ML,0)!=0 THEN (NVL(SN_TXN_6ML,0)/NVL(SN_AUM_6ML,0)) ELSE NULL END AS SN_TURNOVER_6ML
        ,CASE WHEN NVL(SN_AUM_12M,0)!=0 THEN (NVL(SN_TXN_12M,0)/NVL(SN_AUM_12M,0)) ELSE NULL END AS SN_TURNOVER_12M
        ,CASE WHEN NVL(SN_AUM_12ML,0)!=0 THEN (NVL(SN_TXN_12ML,0)/NVL(SN_AUM_12ML,0)) ELSE NULL END AS SN_TURNOVER_12ML
        ---期權淨流
        ,NVL(FO_NET_TXN_M,0)FO_NET_TXN_M
        ,CASE WHEN NVL(FO_NET_TXN_M,0)=0 AND NVL(FO_NET_TXN_L,0)=0 THEN NULL ELSE FO_NET_TXN_M - FO_NET_TXN_L END FO_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FO_NET_TXN_L,0)!=0 THEN (NVL(FO_NET_TXN_M,0)-NVL(FO_NET_TXN_L,0))/ABS(NVL(FO_NET_TXN_L,0)) ELSE NULL END AS FO_NET_TXN_M_RDIFF
        ,NVL(FO_NET_TXN_3M,0)FO_NET_TXN_3M
        ,CASE WHEN NVL(FO_NET_TXN_3M,0)=0 AND NVL(FO_NET_TXN_3ML,0)=0 THEN NULL ELSE FO_NET_TXN_3M - FO_NET_TXN_3ML END FO_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FO_NET_TXN_3ML,0)!=0 THEN (NVL(FO_NET_TXN_3M,0)-NVL(FO_NET_TXN_3ML,0))/ABS(NVL(FO_NET_TXN_3ML,0)) ELSE NULL END AS FO_NET_TXN_3M_RDIFF
        ,NVL(FO_NET_TXN_6M,0)FO_NET_TXN_6M
        ,CASE WHEN NVL(FO_NET_TXN_6M,0)=0 AND NVL(FO_NET_TXN_6ML,0)=0 THEN NULL ELSE FO_NET_TXN_6M - FO_NET_TXN_6ML END FO_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FO_NET_TXN_6ML,0)!=0 THEN (NVL(FO_NET_TXN_6M,0)-NVL(FO_NET_TXN_6ML,0))/ABS(NVL(FO_NET_TXN_6ML,0)) ELSE NULL END AS FO_NET_TXN_6M_RDIFF
        ,NVL(FO_NET_TXN_12M,0)FO_NET_TXN_12M
        ,CASE WHEN NVL(FO_NET_TXN_12M,0)=0 AND NVL(FO_NET_TXN_12ML,0)=0 THEN NULL ELSE FO_NET_TXN_12M - FO_NET_TXN_12ML END FO_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FO_NET_TXN_12ML,0)!=0 THEN (NVL(FO_NET_TXN_12M,0)-NVL(FO_NET_TXN_12ML,0))/ABS(NVL(FO_NET_TXN_12ML,0)) ELSE NULL END AS FO_NET_TXN_12M_RDIFF
        ----期權周轉率
        ,CASE WHEN NVL(FO_AUM_M,0)!=0 THEN (NVL(FO_TXN_M,0)/NVL(FO_AUM_M,0)) ELSE NULL END AS FO_TURNOVER_M
        ,CASE WHEN NVL(FO_AUM_L,0)!=0 THEN (NVL(FO_TXN_L,0)/NVL(FO_AUM_L,0)) ELSE NULL END AS FO_TURNOVER_L
        ,CASE WHEN NVL(FO_AUM_3M,0)!=0 THEN (NVL(FO_TXN_3M,0)/NVL(FO_AUM_3M,0)) ELSE NULL END AS FO_TURNOVER_3M
        ,CASE WHEN NVL(FO_AUM_3ML,0)!=0 THEN (NVL(FO_TXN_3ML,0)/NVL(FO_AUM_3ML,0)) ELSE NULL END AS FO_TURNOVER_3ML
        ,CASE WHEN NVL(FO_AUM_6M,0)!=0 THEN (NVL(FO_TXN_6M,0)/NVL(FO_AUM_6M,0)) ELSE NULL END AS FO_TURNOVER_6M
        ,CASE WHEN NVL(FO_AUM_6ML,0)!=0 THEN (NVL(FO_TXN_6ML,0)/NVL(FO_AUM_6ML,0)) ELSE NULL END AS FO_TURNOVER_6ML
        ,CASE WHEN NVL(FO_AUM_12M,0)!=0 THEN (NVL(FO_TXN_12M,0)/NVL(FO_AUM_12M,0)) ELSE NULL END AS FO_TURNOVER_12M
        ,CASE WHEN NVL(FO_AUM_12ML,0)!=0 THEN (NVL(FO_TXN_12ML,0)/NVL(FO_AUM_12ML,0)) ELSE NULL END AS FO_TURNOVER_12ML
    FROM DS_SEC.CF_CUSTID A
    LEFT JOIN(
        SELECT PARTY_ID
            ------台股 ST
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)ST_NET_TXN_M
