            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('230') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FB_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('230') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FB_TXN_12ML
            
