            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)SN_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)SN_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)SN_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)SN_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)SN_NET_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)SN_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)SN_TXN_M
