            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)SN_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)SN_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)SN_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)SN_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)SN_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240','540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)SN_TXN_12ML
            
            ------期權 FO
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FO_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FO_NET_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FO_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FO_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FO_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FO_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FO_NET_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FO_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)FO_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FO_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FO_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FO_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FO_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FO_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FO_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0','3F0','3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FO_TXN_12ML

        FROM TEMP4TXN A
        GROUP BY PARTY_ID
    )B ON A.CUSTOMER_ID = B.PARTY_ID
    LEFT JOIN TEMP4AUM C ON A.CUSTOMER_ID = C.CUSTOMER_ID
    WHERE A.YYYYMM = :ym
);
INSERT INTO DS_SEC.CF_PROFOLIO3
SELECT CUSTOMER_ID
    ,YYYYMM
    ,ROUND(NSN_NET_TXN_M,0)NSN_NET_TXN_M
    ,ROUND(NSN_NET_TXN_M_MDIFF,0)NSN_NET_TXN_M_MDIFF
    ,ROUND(NSN_NET_TXN_M_RDIFF,4)NSN_NET_TXN_M_RDIFF
    ,ROUND(NSN_TURNOVER_M,4)NSN_TURNOVER_M
    ,ROUND(CASE WHEN NVL(NSN_TURNOVER_M,0)=0 AND NVL(NSN_TURNOVER_L,0)=0 THEN NULL ELSE NSN_TURNOVER_M - NSN_TURNOVER_L END,4) NSN_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(NSN_TURNOVER_L,0)!=0 THEN (NVL(NSN_TURNOVER_M,0)/NVL(NSN_TURNOVER_L,0))-1 ELSE 0 END,4) AS NSN_TURNOVER_M_RDIFF
    ,ROUND(NSN_NET_TXN_3M,0)NSN_NET_TXN_3M
    ,ROUND(NSN_NET_TXN_3M_MDIFF,0)NSN_NET_TXN_3M_MDIFF
    ,ROUND(NSN_NET_TXN_3M_RDIFF,4)NSN_NET_TXN_3M_RDIFF
    ,ROUND(NSN_TURNOVER_3M,4)NSN_TURNOVER_3M
    ,ROUND(CASE WHEN NVL(NSN_TURNOVER_3M,0)=0 AND NVL(NSN_TURNOVER_3ML,0)=0 THEN NULL ELSE NSN_TURNOVER_3M - NSN_TURNOVER_3ML END,4) NSN_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(NSN_TURNOVER_3ML,0)!=0 THEN (NVL(NSN_TURNOVER_3M,0)/NVL(NSN_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS NSN_TURNOVER_3M_RDIFF
    ,ROUND(NSN_NET_TXN_6M,0)NSN_NET_TXN_6M
    ,ROUND(NSN_NET_TXN_6M_MDIFF,0)NSN_NET_TXN_6M_MDIFF
    ,ROUND(NSN_NET_TXN_6M_RDIFF,4)NSN_NET_TXN_6M_RDIFF
    ,ROUND(NSN_TURNOVER_6M,4)NSN_TURNOVER_6M
    ,ROUND(CASE WHEN NVL(NSN_TURNOVER_6M,0)=0 AND NVL(NSN_TURNOVER_6ML,0)=0 THEN NULL ELSE NSN_TURNOVER_6M - NSN_TURNOVER_6ML END,4) NSN_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(NSN_TURNOVER_6ML,0)!=0 THEN (NVL(NSN_TURNOVER_6M,0)/NVL(NSN_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS NSN_TURNOVER_6M_RDIFF
    ,ROUND(NSN_NET_TXN_12M,0)NSN_NET_TXN_12M
    ,ROUND(NSN_NET_TXN_12M_MDIFF,0)NSN_NET_TXN_12M_MDIFF
    ,ROUND(NSN_NET_TXN_12M_RDIFF,4)NSN_NET_TXN_12M_RDIFF
    ,ROUND(NSN_TURNOVER_12M,4)NSN_TURNOVER_12M
    ,ROUND(CASE WHEN NVL(NSN_TURNOVER_12M,0)=0 AND NVL(NSN_TURNOVER_12ML,0)=0 THEN NULL ELSE NSN_TURNOVER_12M - NSN_TURNOVER_12ML END,4) NSN_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(NSN_TURNOVER_12ML,0)!=0 THEN (NVL(NSN_TURNOVER_12M,0)/NVL(NSN_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS NSN_TURNOVER_12M_RDIFF
    
    ,ROUND(FSN_NET_TXN_M,0)FSN_NET_TXN_M
    ,ROUND(FSN_NET_TXN_M_MDIFF,0)FSN_NET_TXN_M_MDIFF
    ,ROUND(FSN_NET_TXN_M_RDIFF,4)FSN_NET_TXN_M_RDIFF
    ,ROUND(FSN_TURNOVER_M,4)FSN_TURNOVER_M
    ,ROUND(CASE WHEN NVL(FSN_TURNOVER_M,0)=0 AND NVL(FSN_TURNOVER_L,0)=0 THEN NULL ELSE FSN_TURNOVER_M - FSN_TURNOVER_L END,4) FSN_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FSN_TURNOVER_L,0)!=0 THEN (NVL(FSN_TURNOVER_M,0)/NVL(FSN_TURNOVER_L,0))-1 ELSE 0 END,4) AS FSN_TURNOVER_M_RDIFF
    ,ROUND(FSN_NET_TXN_3M,0)FSN_NET_TXN_3M
    ,ROUND(FSN_NET_TXN_3M_MDIFF,0)FSN_NET_TXN_3M_MDIFF
    ,ROUND(FSN_NET_TXN_3M_RDIFF,4)FSN_NET_TXN_3M_RDIFF
    ,ROUND(FSN_TURNOVER_3M,4)FSN_TURNOVER_3M
    ,ROUND(CASE WHEN NVL(FSN_TURNOVER_3M,0)=0 AND NVL(FSN_TURNOVER_3ML,0)=0 THEN NULL ELSE FSN_TURNOVER_3M - FSN_TURNOVER_3ML END,4) FSN_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FSN_TURNOVER_3ML,0)!=0 THEN (NVL(FSN_TURNOVER_3M,0)/NVL(FSN_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FSN_TURNOVER_3M_RDIFF
    ,ROUND(FSN_NET_TXN_6M,0)FSN_NET_TXN_6M
    ,ROUND(FSN_NET_TXN_6M_MDIFF,0)FSN_NET_TXN_6M_MDIFF
    ,ROUND(FSN_NET_TXN_6M_RDIFF,4)FSN_NET_TXN_6M_RDIFF
    ,ROUND(FSN_TURNOVER_6M,4)FSN_TURNOVER_6M
    ,ROUND(CASE WHEN NVL(FSN_TURNOVER_6M,0)=0 AND NVL(FSN_TURNOVER_6ML,0)=0 THEN NULL ELSE FSN_TURNOVER_6M - FSN_TURNOVER_6ML END,4) FSN_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FSN_TURNOVER_6ML,0)!=0 THEN (NVL(FSN_TURNOVER_6M,0)/NVL(FSN_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FSN_TURNOVER_6M_RDIFF
    ,ROUND(FSN_NET_TXN_12M,0)FSN_NET_TXN_12M
    ,ROUND(FSN_NET_TXN_12M_MDIFF,0)FSN_NET_TXN_12M_MDIFF
    ,ROUND(FSN_NET_TXN_12M_RDIFF,4)FSN_NET_TXN_12M_RDIFF
    ,ROUND(FSN_TURNOVER_12M,4)FSN_TURNOVER_12M
    ,ROUND(CASE WHEN NVL(FSN_TURNOVER_12M,0)=0 AND NVL(FSN_TURNOVER_12ML,0)=0 THEN NULL ELSE FSN_TURNOVER_12M - FSN_TURNOVER_12ML END,4) FSN_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FSN_TURNOVER_12ML,0)!=0 THEN (NVL(FSN_TURNOVER_12M,0)/NVL(FSN_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FSN_TURNOVER_12M_RDIFF
    
    ,ROUND(UFC_NET_TXN_M,0)UFC_NET_TXN_M
    ,ROUND(UFC_NET_TXN_M_MDIFF,0)UFC_NET_TXN_M_MDIFF
    ,ROUND(UFC_NET_TXN_M_RDIFF,4)UFC_NET_TXN_M_RDIFF
    ,ROUND(UFC_TURNOVER_M,4)UFC_TURNOVER_M
    ,ROUND(CASE WHEN NVL(UFC_TURNOVER_M,0)=0 AND NVL(UFC_TURNOVER_L,0)=0 THEN NULL ELSE UFC_TURNOVER_M - UFC_TURNOVER_L END,4) UFC_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(UFC_TURNOVER_L,0)!=0 THEN (NVL(UFC_TURNOVER_M,0)/NVL(UFC_TURNOVER_L,0))-1 ELSE 0 END,4) AS UFC_TURNOVER_M_RDIFF
    ,ROUND(UFC_NET_TXN_3M,0)UFC_NET_TXN_3M
    ,ROUND(UFC_NET_TXN_3M_MDIFF,0)UFC_NET_TXN_3M_MDIFF
    ,ROUND(UFC_NET_TXN_3M_RDIFF,4)UFC_NET_TXN_3M_RDIFF
    ,ROUND(UFC_TURNOVER_3M,4)UFC_TURNOVER_3M
    ,ROUND(CASE WHEN NVL(UFC_TURNOVER_3M,0)=0 AND NVL(UFC_TURNOVER_3ML,0)=0 THEN NULL ELSE UFC_TURNOVER_3M - UFC_TURNOVER_3ML END,4) UFC_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(UFC_TURNOVER_3ML,0)!=0 THEN (NVL(UFC_TURNOVER_3M,0)/NVL(UFC_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS UFC_TURNOVER_3M_RDIFF
    ,ROUND(UFC_NET_TXN_6M,0)UFC_NET_TXN_6M
    ,ROUND(UFC_NET_TXN_6M_MDIFF,0)UFC_NET_TXN_6M_MDIFF
    ,ROUND(UFC_NET_TXN_6M_RDIFF,4)UFC_NET_TXN_6M_RDIFF
    ,ROUND(UFC_TURNOVER_6M,4)UFC_TURNOVER_6M
    ,ROUND(CASE WHEN NVL(UFC_TURNOVER_6M,0)=0 AND NVL(UFC_TURNOVER_6ML,0)=0 THEN NULL ELSE UFC_TURNOVER_6M - UFC_TURNOVER_6ML END,4) UFC_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(UFC_TURNOVER_6ML,0)!=0 THEN (NVL(UFC_TURNOVER_6M,0)/NVL(UFC_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS UFC_TURNOVER_6M_RDIFF
    ,ROUND(UFC_NET_TXN_12M,0)UFC_NET_TXN_12M
    ,ROUND(UFC_NET_TXN_12M_MDIFF,0)UFC_NET_TXN_12M_MDIFF
    ,ROUND(UFC_NET_TXN_12M_RDIFF,4)UFC_NET_TXN_12M_RDIFF
    ,ROUND(UFC_TURNOVER_12M,4)UFC_TURNOVER_12M
    ,ROUND(CASE WHEN NVL(UFC_TURNOVER_12M,0)=0 AND NVL(UFC_TURNOVER_12ML,0)=0 THEN NULL ELSE UFC_TURNOVER_12M - UFC_TURNOVER_12ML END,4) UFC_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(UFC_TURNOVER_12ML,0)!=0 THEN (NVL(UFC_TURNOVER_12M,0)/NVL(UFC_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS UFC_TURNOVER_12M_RDIFF
    
    ,ROUND(UFF_NET_TXN_M,0)UFF_NET_TXN_M
    ,ROUND(UFF_NET_TXN_M_MDIFF,0)UFF_NET_TXN_M_MDIFF
    ,ROUND(UFF_NET_TXN_M_RDIFF,4)UFF_NET_TXN_M_RDIFF
    ,ROUND(UFF_TURNOVER_M,4)UFF_TURNOVER_M
    ,ROUND(CASE WHEN NVL(UFF_TURNOVER_M,0)=0 AND NVL(UFF_TURNOVER_L,0)=0 THEN NULL ELSE UFF_TURNOVER_M - UFF_TURNOVER_L END,4) UFF_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(UFF_TURNOVER_L,0)!=0 THEN (NVL(UFF_TURNOVER_M,0)/NVL(UFF_TURNOVER_L,0))-1 ELSE 0 END,4) AS UFF_TURNOVER_M_RDIFF
    ,ROUND(UFF_NET_TXN_3M,0)UFF_NET_TXN_3M
    ,ROUND(UFF_NET_TXN_3M_MDIFF,0)UFF_NET_TXN_3M_MDIFF
    ,ROUND(UFF_NET_TXN_3M_RDIFF,4)UFF_NET_TXN_3M_RDIFF
    ,ROUND(UFF_TURNOVER_3M,4)UFF_TURNOVER_3M
    ,ROUND(CASE WHEN NVL(UFF_TURNOVER_3M,0)=0 AND NVL(UFF_TURNOVER_3ML,0)=0 THEN NULL ELSE UFF_TURNOVER_3M - UFF_TURNOVER_3ML END,4) UFF_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(UFF_TURNOVER_3ML,0)!=0 THEN (NVL(UFF_TURNOVER_3M,0)/NVL(UFF_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS UFF_TURNOVER_3M_RDIFF
    ,ROUND(UFF_NET_TXN_6M,0)UFF_NET_TXN_6M
    ,ROUND(UFF_NET_TXN_6M_MDIFF,0)UFF_NET_TXN_6M_MDIFF
    ,ROUND(UFF_NET_TXN_6M_RDIFF,4)UFF_NET_TXN_6M_RDIFF
    ,ROUND(UFF_TURNOVER_6M,4)UFF_TURNOVER_6M
    ,ROUND(CASE WHEN NVL(UFF_TURNOVER_6M,0)=0 AND NVL(UFF_TURNOVER_6ML,0)=0 THEN NULL ELSE UFF_TURNOVER_6M - UFF_TURNOVER_6ML END,4) UFF_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(UFF_TURNOVER_6ML,0)!=0 THEN (NVL(UFF_TURNOVER_6M,0)/NVL(UFF_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS UFF_TURNOVER_6M_RDIFF
    ,ROUND(UFF_NET_TXN_12M,0)UFF_NET_TXN_12M
    ,ROUND(UFF_NET_TXN_12M_MDIFF,0)UFF_NET_TXN_12M_MDIFF
    ,ROUND(UFF_NET_TXN_12M_RDIFF,4)UFF_NET_TXN_12M_RDIFF
    ,ROUND(UFF_TURNOVER_12M,4)UFF_TURNOVER_12M
    ,ROUND(CASE WHEN NVL(UFF_TURNOVER_12M,0)=0 AND NVL(UFF_TURNOVER_12ML,0)=0 THEN NULL ELSE UFF_TURNOVER_12M - UFF_TURNOVER_12ML END,4) UFF_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(UFF_TURNOVER_12ML,0)!=0 THEN (NVL(UFF_TURNOVER_12M,0)/NVL(UFF_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS UFF_TURNOVER_12M_RDIFF
    
    ,ROUND(OP_NET_TXN_M,0)OP_NET_TXN_M
    ,ROUND(OP_NET_TXN_M_MDIFF,0)OP_NET_TXN_M_MDIFF
    ,ROUND(OP_NET_TXN_M_RDIFF,4)OP_NET_TXN_M_RDIFF
    ,ROUND(OP_TURNOVER_M,4)OP_TURNOVER_M
    ,ROUND(CASE WHEN NVL(OP_TURNOVER_M,0)=0 AND NVL(OP_TURNOVER_L,0)=0 THEN NULL ELSE OP_TURNOVER_M - OP_TURNOVER_L END,4) OP_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(OP_TURNOVER_L,0)!=0 THEN (NVL(OP_TURNOVER_M,0)/NVL(OP_TURNOVER_L,0))-1 ELSE 0 END,4) AS OP_TURNOVER_M_RDIFF
    ,ROUND(OP_NET_TXN_3M,0)OP_NET_TXN_3M
    ,ROUND(OP_NET_TXN_3M_MDIFF,0)OP_NET_TXN_3M_MDIFF
    ,ROUND(OP_NET_TXN_3M_RDIFF,4)OP_NET_TXN_3M_RDIFF
    ,ROUND(OP_TURNOVER_3M,4)OP_TURNOVER_3M
    ,ROUND(CASE WHEN NVL(OP_TURNOVER_3M,0)=0 AND NVL(OP_TURNOVER_3ML,0)=0 THEN NULL ELSE OP_TURNOVER_3M - OP_TURNOVER_3ML END,4) OP_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(OP_TURNOVER_3ML,0)!=0 THEN (NVL(OP_TURNOVER_3M,0)/NVL(OP_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS OP_TURNOVER_3M_RDIFF
    ,ROUND(OP_NET_TXN_6M,0)OP_NET_TXN_6M
    ,ROUND(OP_NET_TXN_6M_MDIFF,0)OP_NET_TXN_6M_MDIFF
    ,ROUND(OP_NET_TXN_6M_RDIFF,4)OP_NET_TXN_6M_RDIFF
    ,ROUND(OP_TURNOVER_6M,4)OP_TURNOVER_6M
    ,ROUND(CASE WHEN NVL(OP_TURNOVER_6M,0)=0 AND NVL(OP_TURNOVER_6ML,0)=0 THEN NULL ELSE OP_TURNOVER_6M - OP_TURNOVER_6ML END,4) OP_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(OP_TURNOVER_6ML,0)!=0 THEN (NVL(OP_TURNOVER_6M,0)/NVL(OP_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS OP_TURNOVER_6M_RDIFF
    ,ROUND(OP_NET_TXN_12M,0)OP_NET_TXN_12M
    ,ROUND(OP_NET_TXN_12M_MDIFF,0)OP_NET_TXN_12M_MDIFF
    ,ROUND(OP_NET_TXN_12M_RDIFF,4)OP_NET_TXN_12M_RDIFF
    ,ROUND(OP_TURNOVER_12M,4)OP_TURNOVER_12M
    ,ROUND(CASE WHEN NVL(OP_TURNOVER_12M,0)=0 AND NVL(OP_TURNOVER_12ML,0)=0 THEN NULL ELSE OP_TURNOVER_12M - OP_TURNOVER_12ML END,4) OP_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(OP_TURNOVER_12ML,0)!=0 THEN (NVL(OP_TURNOVER_12M,0)/NVL(OP_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS OP_TURNOVER_12M_RDIFF
FROM(
    SELECT DISTINCT A.CUSTOMER_ID
        ,A.YYYYMM
        ---境內結構型淨流
        ,NVL(NSN_NET_TXN_M,0)NSN_NET_TXN_M
        ,CASE WHEN NVL(NSN_NET_TXN_M,0)=0 AND NVL(NSN_NET_TXN_L,0)=0 THEN NULL ELSE NSN_NET_TXN_M - NSN_NET_TXN_L END NSN_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(NSN_NET_TXN_L,0)!=0 THEN (NVL(NSN_NET_TXN_M,0)-NVL(NSN_NET_TXN_L,0))/ABS(NVL(NSN_NET_TXN_L,0)) ELSE NULL END AS NSN_NET_TXN_M_RDIFF
        ,NVL(NSN_NET_TXN_3M,0)NSN_NET_TXN_3M
        ,CASE WHEN NVL(NSN_NET_TXN_3M,0)=0 AND NVL(NSN_NET_TXN_3ML,0)=0 THEN NULL ELSE NSN_NET_TXN_3M - NSN_NET_TXN_3ML END NSN_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(NSN_NET_TXN_3ML,0)!=0 THEN (NVL(NSN_NET_TXN_3M,0)-NVL(NSN_NET_TXN_3ML,0))/ABS(NVL(NSN_NET_TXN_3ML,0)) ELSE NULL END AS NSN_NET_TXN_3M_RDIFF
        ,NVL(NSN_NET_TXN_6M,0)NSN_NET_TXN_6M
        ,CASE WHEN NVL(NSN_NET_TXN_6M,0)=0 AND NVL(NSN_NET_TXN_6ML,0)=0 THEN NULL ELSE NSN_NET_TXN_6M - NSN_NET_TXN_6ML END NSN_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(NSN_NET_TXN_6ML,0)!=0 THEN (NVL(NSN_NET_TXN_6M,0)-NVL(NSN_NET_TXN_6ML,0))/ABS(NVL(NSN_NET_TXN_6ML,0)) ELSE NULL END AS NSN_NET_TXN_6M_RDIFF
        ,NVL(NSN_NET_TXN_12M,0)NSN_NET_TXN_12M
        ,CASE WHEN NVL(NSN_NET_TXN_12M,0)=0 AND NVL(NSN_NET_TXN_12ML,0)=0 THEN NULL ELSE NSN_NET_TXN_12M - NSN_NET_TXN_12ML END NSN_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(NSN_NET_TXN_12ML,0)!=0 THEN (NVL(NSN_NET_TXN_12M,0)-NVL(NSN_NET_TXN_12ML,0))/ABS(NVL(NSN_NET_TXN_12ML,0)) ELSE NULL END AS NSN_NET_TXN_12M_RDIFF
        ----境內結構型周轉率
        ,CASE WHEN NVL(NSN_AUM_M,0)!=0 THEN (NVL(NSN_TXN_M,0)/NVL(NSN_AUM_M,0)) ELSE NULL END AS NSN_TURNOVER_M
        ,CASE WHEN NVL(NSN_AUM_L,0)!=0 THEN (NVL(NSN_TXN_L,0)/NVL(NSN_AUM_L,0)) ELSE NULL END AS NSN_TURNOVER_L
        ,CASE WHEN NVL(NSN_AUM_3M,0)!=0 THEN (NVL(NSN_TXN_3M,0)/NVL(NSN_AUM_3M,0)) ELSE NULL END AS NSN_TURNOVER_3M
        ,CASE WHEN NVL(NSN_AUM_3ML,0)!=0 THEN (NVL(NSN_TXN_3ML,0)/NVL(NSN_AUM_3ML,0)) ELSE NULL END AS NSN_TURNOVER_3ML
        ,CASE WHEN NVL(NSN_AUM_6M,0)!=0 THEN (NVL(NSN_TXN_6M,0)/NVL(NSN_AUM_6M,0)) ELSE NULL END AS NSN_TURNOVER_6M
        ,CASE WHEN NVL(NSN_AUM_6ML,0)!=0 THEN (NVL(NSN_TXN_6ML,0)/NVL(NSN_AUM_6ML,0)) ELSE NULL END AS NSN_TURNOVER_6ML
        ,CASE WHEN NVL(NSN_AUM_12M,0)!=0 THEN (NVL(NSN_TXN_12M,0)/NVL(NSN_AUM_12M,0)) ELSE NULL END AS NSN_TURNOVER_12M
        ,CASE WHEN NVL(NSN_AUM_12ML,0)!=0 THEN (NVL(NSN_TXN_12ML,0)/NVL(NSN_AUM_12ML,0)) ELSE NULL END AS NSN_TURNOVER_12ML
        ---境外結構型淨流
        ,NVL(FSN_NET_TXN_M,0)FSN_NET_TXN_M
        ,CASE WHEN NVL(FSN_NET_TXN_M,0)=0 AND NVL(FSN_NET_TXN_L,0)=0 THEN NULL ELSE FSN_NET_TXN_M - FSN_NET_TXN_L END FSN_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FSN_NET_TXN_L,0)!=0 THEN (NVL(FSN_NET_TXN_M,0)-NVL(FSN_NET_TXN_L,0))/ABS(NVL(FSN_NET_TXN_L,0)) ELSE NULL END AS FSN_NET_TXN_M_RDIFF
        ,NVL(FSN_NET_TXN_3M,0)FSN_NET_TXN_3M
        ,CASE WHEN NVL(FSN_NET_TXN_3M,0)=0 AND NVL(FSN_NET_TXN_3ML,0)=0 THEN NULL ELSE FSN_NET_TXN_3M - FSN_NET_TXN_3ML END FSN_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FSN_NET_TXN_3ML,0)!=0 THEN (NVL(FSN_NET_TXN_3M,0)-NVL(FSN_NET_TXN_3ML,0))/ABS(NVL(FSN_NET_TXN_3ML,0)) ELSE NULL END AS FSN_NET_TXN_3M_RDIFF
        ,NVL(FSN_NET_TXN_6M,0)FSN_NET_TXN_6M
        ,CASE WHEN NVL(FSN_NET_TXN_6M,0)=0 AND NVL(FSN_NET_TXN_6ML,0)=0 THEN NULL ELSE FSN_NET_TXN_6M - FSN_NET_TXN_6ML END FSN_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FSN_NET_TXN_6ML,0)!=0 THEN (NVL(FSN_NET_TXN_6M,0)-NVL(FSN_NET_TXN_6ML,0))/ABS(NVL(FSN_NET_TXN_6ML,0)) ELSE NULL END AS FSN_NET_TXN_6M_RDIFF
        ,NVL(FSN_NET_TXN_12M,0)FSN_NET_TXN_12M
        ,CASE WHEN NVL(FSN_NET_TXN_12M,0)=0 AND NVL(FSN_NET_TXN_12ML,0)=0 THEN NULL ELSE FSN_NET_TXN_12M - FSN_NET_TXN_12ML END FSN_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FSN_NET_TXN_12ML,0)!=0 THEN (NVL(FSN_NET_TXN_12M,0)-NVL(FSN_NET_TXN_12ML,0))/ABS(NVL(FSN_NET_TXN_12ML,0)) ELSE NULL END AS FSN_NET_TXN_12M_RDIFF
        ----境外結構型周轉率
        ,CASE WHEN NVL(FSN_AUM_M,0)!=0 THEN (NVL(FSN_TXN_M,0)/NVL(FSN_AUM_M,0)) ELSE NULL END AS FSN_TURNOVER_M
        ,CASE WHEN NVL(FSN_AUM_L,0)!=0 THEN (NVL(FSN_TXN_L,0)/NVL(FSN_AUM_L,0)) ELSE NULL END AS FSN_TURNOVER_L
        ,CASE WHEN NVL(FSN_AUM_3M,0)!=0 THEN (NVL(FSN_TXN_3M,0)/NVL(FSN_AUM_3M,0)) ELSE NULL END AS FSN_TURNOVER_3M
        ,CASE WHEN NVL(FSN_AUM_3ML,0)!=0 THEN (NVL(FSN_TXN_3ML,0)/NVL(FSN_AUM_3ML,0)) ELSE NULL END AS FSN_TURNOVER_3ML
        ,CASE WHEN NVL(FSN_AUM_6M,0)!=0 THEN (NVL(FSN_TXN_6M,0)/NVL(FSN_AUM_6M,0)) ELSE NULL END AS FSN_TURNOVER_6M
        ,CASE WHEN NVL(FSN_AUM_6ML,0)!=0 THEN (NVL(FSN_TXN_6ML,0)/NVL(FSN_AUM_6ML,0)) ELSE NULL END AS FSN_TURNOVER_6ML
        ,CASE WHEN NVL(FSN_AUM_12M,0)!=0 THEN (NVL(FSN_TXN_12M,0)/NVL(FSN_AUM_12M,0)) ELSE NULL END AS FSN_TURNOVER_12M
        ,CASE WHEN NVL(FSN_AUM_12ML,0)!=0 THEN (NVL(FSN_TXN_12ML,0)/NVL(FSN_AUM_12ML,0)) ELSE NULL END AS FSN_TURNOVER_12ML
        ---內期淨流
        ,NVL(UFC_NET_TXN_M,0)UFC_NET_TXN_M
        ,CASE WHEN NVL(UFC_NET_TXN_M,0)=0 AND NVL(UFC_NET_TXN_L,0)=0 THEN NULL ELSE UFC_NET_TXN_M - UFC_NET_TXN_L END UFC_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(UFC_NET_TXN_L,0)!=0 THEN (NVL(UFC_NET_TXN_M,0)-NVL(UFC_NET_TXN_L,0))/ABS(NVL(UFC_NET_TXN_L,0)) ELSE NULL END AS UFC_NET_TXN_M_RDIFF
        ,NVL(UFC_NET_TXN_3M,0)UFC_NET_TXN_3M
        ,CASE WHEN NVL(UFC_NET_TXN_3M,0)=0 AND NVL(UFC_NET_TXN_3ML,0)=0 THEN NULL ELSE UFC_NET_TXN_3M - UFC_NET_TXN_3ML END UFC_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(UFC_NET_TXN_3ML,0)!=0 THEN (NVL(UFC_NET_TXN_3M,0)-NVL(UFC_NET_TXN_3ML,0))/ABS(NVL(UFC_NET_TXN_3ML,0)) ELSE NULL END AS UFC_NET_TXN_3M_RDIFF
        ,NVL(UFC_NET_TXN_6M,0)UFC_NET_TXN_6M
        ,CASE WHEN NVL(UFC_NET_TXN_6M,0)=0 AND NVL(UFC_NET_TXN_6ML,0)=0 THEN NULL ELSE UFC_NET_TXN_6M - UFC_NET_TXN_6ML END UFC_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(UFC_NET_TXN_6ML,0)!=0 THEN (NVL(UFC_NET_TXN_6M,0)-NVL(UFC_NET_TXN_6ML,0))/ABS(NVL(UFC_NET_TXN_6ML,0)) ELSE NULL END AS UFC_NET_TXN_6M_RDIFF
        ,NVL(UFC_NET_TXN_12M,0)UFC_NET_TXN_12M
        ,CASE WHEN NVL(UFC_NET_TXN_12M,0)=0 AND NVL(UFC_NET_TXN_12ML,0)=0 THEN NULL ELSE UFC_NET_TXN_12M - UFC_NET_TXN_12ML END UFC_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(UFC_NET_TXN_12ML,0)!=0 THEN (NVL(UFC_NET_TXN_12M,0)-NVL(UFC_NET_TXN_12ML,0))/ABS(NVL(UFC_NET_TXN_12ML,0)) ELSE NULL END AS UFC_NET_TXN_12M_RDIFF
        ----內期周轉率
        ,CASE WHEN NVL(UFC_AUM_M,0)!=0 THEN (NVL(UFC_TXN_M,0)/NVL(UFC_AUM_M,0)) ELSE NULL END AS UFC_TURNOVER_M
        ,CASE WHEN NVL(UFC_AUM_L,0)!=0 THEN (NVL(UFC_TXN_L,0)/NVL(UFC_AUM_L,0)) ELSE NULL END AS UFC_TURNOVER_L
        ,CASE WHEN NVL(UFC_AUM_3M,0)!=0 THEN (NVL(UFC_TXN_3M,0)/NVL(UFC_AUM_3M,0)) ELSE NULL END AS UFC_TURNOVER_3M
        ,CASE WHEN NVL(UFC_AUM_3ML,0)!=0 THEN (NVL(UFC_TXN_3ML,0)/NVL(UFC_AUM_3ML,0)) ELSE NULL END AS UFC_TURNOVER_3ML
        ,CASE WHEN NVL(UFC_AUM_6M,0)!=0 THEN (NVL(UFC_TXN_6M,0)/NVL(UFC_AUM_6M,0)) ELSE NULL END AS UFC_TURNOVER_6M
        ,CASE WHEN NVL(UFC_AUM_6ML,0)!=0 THEN (NVL(UFC_TXN_6ML,0)/NVL(UFC_AUM_6ML,0)) ELSE NULL END AS UFC_TURNOVER_6ML
        ,CASE WHEN NVL(UFC_AUM_12M,0)!=0 THEN (NVL(UFC_TXN_12M,0)/NVL(UFC_AUM_12M,0)) ELSE NULL END AS UFC_TURNOVER_12M
        ,CASE WHEN NVL(UFC_AUM_12ML,0)!=0 THEN (NVL(UFC_TXN_12ML,0)/NVL(UFC_AUM_12ML,0)) ELSE NULL END AS UFC_TURNOVER_12ML
        ---外期淨流
        ,NVL(UFF_NET_TXN_M,0)UFF_NET_TXN_M
        ,CASE WHEN NVL(UFF_NET_TXN_M,0)=0 AND NVL(UFF_NET_TXN_L,0)=0 THEN NULL ELSE UFF_NET_TXN_M - UFF_NET_TXN_L END UFF_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(UFF_NET_TXN_L,0)!=0 THEN (NVL(UFF_NET_TXN_M,0)-NVL(UFF_NET_TXN_L,0))/ABS(NVL(UFF_NET_TXN_L,0)) ELSE NULL END AS UFF_NET_TXN_M_RDIFF
        ,NVL(UFF_NET_TXN_3M,0)UFF_NET_TXN_3M
        ,CASE WHEN NVL(UFF_NET_TXN_3M,0)=0 AND NVL(UFF_NET_TXN_3ML,0)=0 THEN NULL ELSE UFF_NET_TXN_3M - UFF_NET_TXN_3ML END UFF_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(UFF_NET_TXN_3ML,0)!=0 THEN (NVL(UFF_NET_TXN_3M,0)-NVL(UFF_NET_TXN_3ML,0))/ABS(NVL(UFF_NET_TXN_3ML,0)) ELSE NULL END AS UFF_NET_TXN_3M_RDIFF
        ,NVL(UFF_NET_TXN_6M,0)UFF_NET_TXN_6M
        ,CASE WHEN NVL(UFF_NET_TXN_6M,0)=0 AND NVL(UFF_NET_TXN_6ML,0)=0 THEN NULL ELSE UFF_NET_TXN_6M - UFF_NET_TXN_6ML END UFF_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(UFF_NET_TXN_6ML,0)!=0 THEN (NVL(UFF_NET_TXN_6M,0)-NVL(UFF_NET_TXN_6ML,0))/ABS(NVL(UFF_NET_TXN_6ML,0)) ELSE NULL END AS UFF_NET_TXN_6M_RDIFF
        ,NVL(UFF_NET_TXN_12M,0)UFF_NET_TXN_12M
        ,CASE WHEN NVL(UFF_NET_TXN_12M,0)=0 AND NVL(UFF_NET_TXN_12ML,0)=0 THEN NULL ELSE UFF_NET_TXN_12M - UFF_NET_TXN_12ML END UFF_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(UFF_NET_TXN_12ML,0)!=0 THEN (NVL(UFF_NET_TXN_12M,0)-NVL(UFF_NET_TXN_12ML,0))/ABS(NVL(UFF_NET_TXN_12ML,0)) ELSE NULL END AS UFF_NET_TXN_12M_RDIFF
        ----外期周轉率
        ,CASE WHEN NVL(UFF_AUM_M,0)!=0 THEN (NVL(UFF_TXN_M,0)/NVL(UFF_AUM_M,0)) ELSE NULL END AS UFF_TURNOVER_M
        ,CASE WHEN NVL(UFF_AUM_L,0)!=0 THEN (NVL(UFF_TXN_L,0)/NVL(UFF_AUM_L,0)) ELSE NULL END AS UFF_TURNOVER_L
        ,CASE WHEN NVL(UFF_AUM_3M,0)!=0 THEN (NVL(UFF_TXN_3M,0)/NVL(UFF_AUM_3M,0)) ELSE NULL END AS UFF_TURNOVER_3M
        ,CASE WHEN NVL(UFF_AUM_3ML,0)!=0 THEN (NVL(UFF_TXN_3ML,0)/NVL(UFF_AUM_3ML,0)) ELSE NULL END AS UFF_TURNOVER_3ML
        ,CASE WHEN NVL(UFF_AUM_6M,0)!=0 THEN (NVL(UFF_TXN_6M,0)/NVL(UFF_AUM_6M,0)) ELSE NULL END AS UFF_TURNOVER_6M
        ,CASE WHEN NVL(UFF_AUM_6ML,0)!=0 THEN (NVL(UFF_TXN_6ML,0)/NVL(UFF_AUM_6ML,0)) ELSE NULL END AS UFF_TURNOVER_6ML
        ,CASE WHEN NVL(UFF_AUM_12M,0)!=0 THEN (NVL(UFF_TXN_12M,0)/NVL(UFF_AUM_12M,0)) ELSE NULL END AS UFF_TURNOVER_12M
        ,CASE WHEN NVL(UFF_AUM_12ML,0)!=0 THEN (NVL(UFF_TXN_12ML,0)/NVL(UFF_AUM_12ML,0)) ELSE NULL END AS UFF_TURNOVER_12ML
        ---選擇權淨流
        ,NVL(OP_NET_TXN_M,0)OP_NET_TXN_M
        ,CASE WHEN NVL(OP_NET_TXN_M,0)=0 AND NVL(OP_NET_TXN_L,0)=0 THEN NULL ELSE OP_NET_TXN_M - OP_NET_TXN_L END OP_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(OP_NET_TXN_L,0)!=0 THEN (NVL(OP_NET_TXN_M,0)-NVL(OP_NET_TXN_L,0))/ABS(NVL(OP_NET_TXN_L,0)) ELSE NULL END AS OP_NET_TXN_M_RDIFF
        ,NVL(OP_NET_TXN_3M,0)OP_NET_TXN_3M
        ,CASE WHEN NVL(OP_NET_TXN_3M,0)=0 AND NVL(OP_NET_TXN_3ML,0)=0 THEN NULL ELSE OP_NET_TXN_3M - OP_NET_TXN_3ML END OP_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(OP_NET_TXN_3ML,0)!=0 THEN (NVL(OP_NET_TXN_3M,0)-NVL(OP_NET_TXN_3ML,0))/ABS(NVL(OP_NET_TXN_3ML,0)) ELSE NULL END AS OP_NET_TXN_3M_RDIFF
        ,NVL(OP_NET_TXN_6M,0)OP_NET_TXN_6M
        ,CASE WHEN NVL(OP_NET_TXN_6M,0)=0 AND NVL(OP_NET_TXN_6ML,0)=0 THEN NULL ELSE OP_NET_TXN_6M - OP_NET_TXN_6ML END OP_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(OP_NET_TXN_6ML,0)!=0 THEN (NVL(OP_NET_TXN_6M,0)-NVL(OP_NET_TXN_6ML,0))/ABS(NVL(OP_NET_TXN_6ML,0)) ELSE NULL END AS OP_NET_TXN_6M_RDIFF
        ,NVL(OP_NET_TXN_12M,0)OP_NET_TXN_12M
        ,CASE WHEN NVL(OP_NET_TXN_12M,0)=0 AND NVL(OP_NET_TXN_12ML,0)=0 THEN NULL ELSE OP_NET_TXN_12M - OP_NET_TXN_12ML END OP_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(OP_NET_TXN_12ML,0)!=0 THEN (NVL(OP_NET_TXN_12M,0)-NVL(OP_NET_TXN_12ML,0))/ABS(NVL(OP_NET_TXN_12ML,0)) ELSE NULL END AS OP_NET_TXN_12M_RDIFF
        ----選擇權周轉率
        ,CASE WHEN NVL(OP_AUM_M,0)!=0 THEN (NVL(OP_TXN_M,0)/NVL(OP_AUM_M,0)) ELSE NULL END AS OP_TURNOVER_M
        ,CASE WHEN NVL(OP_AUM_L,0)!=0 THEN (NVL(OP_TXN_L,0)/NVL(OP_AUM_L,0)) ELSE NULL END AS OP_TURNOVER_L
        ,CASE WHEN NVL(OP_AUM_3M,0)!=0 THEN (NVL(OP_TXN_3M,0)/NVL(OP_AUM_3M,0)) ELSE NULL END AS OP_TURNOVER_3M
        ,CASE WHEN NVL(OP_AUM_3ML,0)!=0 THEN (NVL(OP_TXN_3ML,0)/NVL(OP_AUM_3ML,0)) ELSE NULL END AS OP_TURNOVER_3ML
        ,CASE WHEN NVL(OP_AUM_6M,0)!=0 THEN (NVL(OP_TXN_6M,0)/NVL(OP_AUM_6M,0)) ELSE NULL END AS OP_TURNOVER_6M
        ,CASE WHEN NVL(OP_AUM_6ML,0)!=0 THEN (NVL(OP_TXN_6ML,0)/NVL(OP_AUM_6ML,0)) ELSE NULL END AS OP_TURNOVER_6ML
        ,CASE WHEN NVL(OP_AUM_12M,0)!=0 THEN (NVL(OP_TXN_12M,0)/NVL(OP_AUM_12M,0)) ELSE NULL END AS OP_TURNOVER_12M
        ,CASE WHEN NVL(OP_AUM_12ML,0)!=0 THEN (NVL(OP_TXN_12ML,0)/NVL(OP_AUM_12ML,0)) ELSE NULL END AS OP_TURNOVER_12ML

    FROM DS_SEC.CF_CUSTID A
    LEFT JOIN(
        SELECT PARTY_ID
            ------境內結構型商品 NSN
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)NSN_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)NSN_NET_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)NSN_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)NSN_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)NSN_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)NSN_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)NSN_NET_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)NSN_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)NSN_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)NSN_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)NSN_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)NSN_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)NSN_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)NSN_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)NSN_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('540') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)NSN_TXN_12ML
            
            ------境外結構型商品 FSN
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FSN_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FSN_NET_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FSN_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FSN_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FSN_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FSN_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FSN_NET_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FSN_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)FSN_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FSN_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FSN_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FSN_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FSN_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FSN_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FSN_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('240') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FSN_TXN_12ML
            
            ------內期 UFC
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)UFC_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
