            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3C0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)UFC_NET_TXN_6ML
