            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3F0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)UFF_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3F0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3F0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)UFF_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3F0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3F0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)UFF_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3F0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
