            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3F0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
