            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OP_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
