            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OP_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OP_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OP_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OP_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OP_NET_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OP_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)OP_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OP_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OP_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OP_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OP_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OP_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OP_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('3P0') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OP_TXN_12ML

        FROM TEMP4TXN A
        GROUP BY PARTY_ID
    )B ON A.CUSTOMER_ID = B.PARTY_ID
    LEFT JOIN TEMP4AUM C ON A.CUSTOMER_ID = C.CUSTOMER_ID
    WHERE A.YYYYMM = :ym
);
INSERT INTO DS_SEC.CF_PROFOLIO4
SELECT CUSTOMER_ID
    ,YYYYMM
    ,ROUND(STLS_NET_TXN_M,0) STLS_NET_TXN_M
    ,ROUND(STLS_NET_TXN_M_MDIFF,0)STLS_NET_TXN_M_MDIFF
    ,ROUND(STLS_NET_TXN_M_RDIFF,4)STLS_NET_TXN_M_RDIFF
    ,ROUND(STLS_TURNOVER_M,4)STLS_TURNOVER_M
    ,ROUND(STLS_TURNOVER_M - STLS_TURNOVER_L,4) STLS_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(STLS_TURNOVER_L,0)!=0 THEN (NVL(STLS_TURNOVER_M,0)/NVL(STLS_TURNOVER_L,0))-1 ELSE 0 END,4) AS STLS_TURNOVER_M_RDIFF
    ,ROUND(STLS_NET_TXN_3M,0) STLS_NET_TXN_3M
    ,ROUND(STLS_NET_TXN_3M_MDIFF,0)STLS_NET_TXN_3M_MDIFF
    ,ROUND(STLS_NET_TXN_3M_RDIFF,4)STLS_NET_TXN_3M_RDIFF
    ,ROUND(STLS_TURNOVER_3M,4)STLS_TURNOVER_3M
    ,ROUND(STLS_TURNOVER_3M - STLS_TURNOVER_3ML,4) STLS_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(STLS_TURNOVER_3ML,0)!=0 THEN (NVL(STLS_TURNOVER_3M,0)/NVL(STLS_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS STLS_TURNOVER_3M_RDIFF
    ,ROUND(STLS_NET_TXN_6M,0) STLS_NET_TXN_6M
    ,ROUND(STLS_NET_TXN_6M_MDIFF,0)STLS_NET_TXN_6M_MDIFF
    ,ROUND(STLS_NET_TXN_6M_RDIFF,4)STLS_NET_TXN_6M_RDIFF
    ,ROUND(STLS_TURNOVER_6M,4)STLS_TURNOVER_6M
    ,ROUND(STLS_TURNOVER_6M - STLS_TURNOVER_6ML,4) STLS_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(STLS_TURNOVER_6ML,0)!=0 THEN (NVL(STLS_TURNOVER_6M,0)/NVL(STLS_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS STLS_TURNOVER_6M_RDIFF
    ,ROUND(STLS_NET_TXN_12M,0) STLS_NET_TXN_12M
    ,ROUND(STLS_NET_TXN_12M_MDIFF,0)STLS_NET_TXN_12M_MDIFF
    ,ROUND(STLS_NET_TXN_12M_RDIFF,4)STLS_NET_TXN_12M_RDIFF
    ,ROUND(STLS_TURNOVER_12M,4)STLS_TURNOVER_12M
    ,ROUND(STLS_TURNOVER_12M - STLS_TURNOVER_12ML,4) STLS_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(STLS_TURNOVER_12ML,0)!=0 THEN (NVL(STLS_TURNOVER_12M,0)/NVL(STLS_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS STLS_TURNOVER_12M_RDIFF
    
    ,ROUND(STDCA_TURNOVER_M,4)STDCA_TURNOVER_M
    ,ROUND(STDCA_TURNOVER_M - STDCA_TURNOVER_L,4) STDCA_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(STDCA_TURNOVER_L,0)!=0 THEN (NVL(STDCA_TURNOVER_M,0)/NVL(STDCA_TURNOVER_L,0))-1 ELSE 0 END,4) AS STDCA_TURNOVER_M_RDIFF
    ,ROUND(STDCA_TURNOVER_3M,4)STDCA_TURNOVER_3M
    ,ROUND(STDCA_TURNOVER_3M - STDCA_TURNOVER_3ML,4) STDCA_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(STDCA_TURNOVER_3ML,0)!=0 THEN (NVL(STDCA_TURNOVER_3M,0)/NVL(STDCA_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS STDCA_TURNOVER_3M_RDIFF
    ,ROUND(STDCA_TURNOVER_6M,4)STDCA_TURNOVER_6M
    ,ROUND(STDCA_TURNOVER_6M - STDCA_TURNOVER_6ML,4) STDCA_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(STDCA_TURNOVER_6ML,0)!=0 THEN (NVL(STDCA_TURNOVER_6M,0)/NVL(STDCA_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS STDCA_TURNOVER_6M_RDIFF
    ,ROUND(STDCA_TURNOVER_12M,4)STDCA_TURNOVER_12M
    ,ROUND(STDCA_TURNOVER_12M - STDCA_TURNOVER_12ML,4) STDCA_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(STDCA_TURNOVER_12ML,0)!=0 THEN (NVL(STDCA_TURNOVER_12M,0)/NVL(STDCA_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS STDCA_TURNOVER_12M_RDIFF
    
    ,ROUND(FDLS_NET_TXN_M,0) FDLS_NET_TXN_M
    ,ROUND(FDLS_NET_TXN_M_MDIFF,0)FDLS_NET_TXN_M_MDIFF
    ,ROUND(FDLS_NET_TXN_M_RDIFF,4)FDLS_NET_TXN_M_RDIFF
    ,ROUND(FDLS_TURNOVER_M,4)FDLS_TURNOVER_M
    ,ROUND(FDLS_TURNOVER_M - FDLS_TURNOVER_L,4) FDLS_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FDLS_TURNOVER_L,0)!=0 THEN (NVL(FDLS_TURNOVER_M,0)/NVL(FDLS_TURNOVER_L,0))-1 ELSE 0 END,4) AS FDLS_TURNOVER_M_RDIFF
    ,ROUND(FDLS_NET_TXN_3M,0) FDLS_NET_TXN_3M
    ,ROUND(FDLS_NET_TXN_3M_MDIFF,0)FDLS_NET_TXN_3M_MDIFF
    ,ROUND(FDLS_NET_TXN_3M_RDIFF,4)FDLS_NET_TXN_3M_RDIFF
    ,ROUND(FDLS_TURNOVER_3M,4)FDLS_TURNOVER_3M
    ,ROUND(FDLS_TURNOVER_3M - FDLS_TURNOVER_3ML,4) FDLS_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FDLS_TURNOVER_3ML,0)!=0 THEN (NVL(FDLS_TURNOVER_3M,0)/NVL(FDLS_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FDLS_TURNOVER_3M_RDIFF
    ,ROUND(FDLS_NET_TXN_6M,0) FDLS_NET_TXN_6M
    ,ROUND(FDLS_NET_TXN_6M_MDIFF,0)FDLS_NET_TXN_6M_MDIFF
    ,ROUND(FDLS_NET_TXN_6M_RDIFF,4)FDLS_NET_TXN_6M_RDIFF
    ,ROUND(FDLS_TURNOVER_6M,4)FDLS_TURNOVER_6M
    ,ROUND(FDLS_TURNOVER_6M - FDLS_TURNOVER_6ML,4) FDLS_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FDLS_TURNOVER_6ML,0)!=0 THEN (NVL(FDLS_TURNOVER_6M,0)/NVL(FDLS_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FDLS_TURNOVER_6M_RDIFF
    ,ROUND(FDLS_NET_TXN_12M,0) FDLS_NET_TXN_12M
    ,ROUND(FDLS_NET_TXN_12M_MDIFF,0)FDLS_NET_TXN_12M_MDIFF
    ,ROUND(FDLS_NET_TXN_12M_RDIFF,4)FDLS_NET_TXN_12M_RDIFF
    ,ROUND(FDLS_TURNOVER_12M,4)FDLS_TURNOVER_12M
    ,ROUND(FDLS_TURNOVER_12M - FDLS_TURNOVER_12ML,4) FDLS_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FDLS_TURNOVER_12ML,0)!=0 THEN (NVL(FDLS_TURNOVER_12M,0)/NVL(FDLS_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FDLS_TURNOVER_12M_RDIFF
    
    ,ROUND(FDDCA_TURNOVER_M,4)FDDCA_TURNOVER_M
    ,ROUND(FDDCA_TURNOVER_M - FDDCA_TURNOVER_L,4) FDDCA_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FDDCA_TURNOVER_L,0)!=0 THEN (NVL(FDDCA_TURNOVER_M,0)/NVL(FDDCA_TURNOVER_L,0))-1 ELSE 0 END,4) AS FDDCA_TURNOVER_M_RDIFF
    ,ROUND(FDDCA_TURNOVER_3M,4)FDDCA_TURNOVER_3M
    ,ROUND(FDDCA_TURNOVER_3M - FDDCA_TURNOVER_3ML,4) FDDCA_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FDDCA_TURNOVER_3ML,0)!=0 THEN (NVL(FDDCA_TURNOVER_3M,0)/NVL(FDDCA_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FDDCA_TURNOVER_3M_RDIFF
    ,ROUND(FDDCA_TURNOVER_6M,4)FDDCA_TURNOVER_6M
    ,ROUND(FDDCA_TURNOVER_6M - FDDCA_TURNOVER_6ML,4) FDDCA_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FDDCA_TURNOVER_6ML,0)!=0 THEN (NVL(FDDCA_TURNOVER_6M,0)/NVL(FDDCA_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FDDCA_TURNOVER_6M_RDIFF
    ,ROUND(FDDCA_TURNOVER_12M,4)FDDCA_TURNOVER_12M
    ,ROUND(FDDCA_TURNOVER_12M - FDDCA_TURNOVER_12ML,4) FDDCA_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FDDCA_TURNOVER_12ML,0)!=0 THEN (NVL(FDDCA_TURNOVER_12M,0)/NVL(FDDCA_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FDDCA_TURNOVER_12M_RDIFF
    
    ,ROUND(FSLS_NET_TXN_M,0) FSLS_NET_TXN_M
    ,ROUND(FSLS_NET_TXN_M_MDIFF,0)FSLS_NET_TXN_M_MDIFF
    ,ROUND(FSLS_NET_TXN_M_RDIFF,4)FSLS_NET_TXN_M_RDIFF
    ,ROUND(FSLS_NET_TXN_3M,0) FSLS_NET_TXN_3M
    ,ROUND(FSLS_NET_TXN_3M_MDIFF,0)FSLS_NET_TXN_3M_MDIFF
    ,ROUND(FSLS_NET_TXN_3M_RDIFF,4)FSLS_NET_TXN_3M_RDIFF
    ,ROUND(FSLS_NET_TXN_6M,0) FSLS_NET_TXN_6M
    ,ROUND(FSLS_NET_TXN_6M_MDIFF,0)FSLS_NET_TXN_6M_MDIFF
    ,ROUND(FSLS_NET_TXN_6M_RDIFF,4)FSLS_NET_TXN_6M_RDIFF
    ,ROUND(FSLS_NET_TXN_12M,0) FSLS_NET_TXN_12M
    ,ROUND(FSLS_NET_TXN_12M_MDIFF,0)FSLS_NET_TXN_12M_MDIFF
    ,ROUND(FSLS_NET_TXN_12M_RDIFF,4)FSLS_NET_TXN_12M_RDIFF
    
    ,ROUND(FSDCA_NET_TXN_M,0) FSDCA_NET_TXN_M
    ,ROUND(FSDCA_NET_TXN_M_MDIFF,0)FSDCA_NET_TXN_M_MDIFF
    ,ROUND(FSDCA_NET_TXN_M_RDIFF,4)FSDCA_NET_TXN_M_RDIFF
    ,ROUND(FSDCA_NET_TXN_3M,0) FSDCA_NET_TXN_3M
    ,ROUND(FSDCA_NET_TXN_3M_MDIFF,0)FSDCA_NET_TXN_3M_MDIFF
    ,ROUND(FSDCA_NET_TXN_3M_RDIFF,4)FSDCA_NET_TXN_3M_RDIFF
    ,ROUND(FSDCA_NET_TXN_6M,0) FSDCA_NET_TXN_6M
    ,ROUND(FSDCA_NET_TXN_6M_MDIFF,0)FSDCA_NET_TXN_6M_MDIFF
    ,ROUND(FSDCA_NET_TXN_6M_RDIFF,4)FSDCA_NET_TXN_6M_RDIFF
    ,ROUND(FSDCA_NET_TXN_12M,0) FSDCA_NET_TXN_12M
    ,ROUND(FSDCA_NET_TXN_12M_MDIFF,0)FSDCA_NET_TXN_12M_MDIFF
    ,ROUND(FSDCA_NET_TXN_12M_RDIFF,4)FSDCA_NET_TXN_12M_RDIFF
    
    ,ROUND(STMT_NET_TXN_M,0) STMT_NET_TXN_M
    ,ROUND(STMT_NET_TXN_M_MDIFF,0)STMT_NET_TXN_M_MDIFF
    ,ROUND(STMT_NET_TXN_M_RDIFF,4)STMT_NET_TXN_M_RDIFF
    ,ROUND(STMT_NET_TXN_3M,0) STMT_NET_TXN_3M
    ,ROUND(STMT_NET_TXN_3M_MDIFF,0)STMT_NET_TXN_3M_MDIFF
    ,ROUND(STMT_NET_TXN_3M_RDIFF,4)STMT_NET_TXN_3M_RDIFF
    ,ROUND(STMT_NET_TXN_6M,0) STMT_NET_TXN_6M
    ,ROUND(STMT_NET_TXN_6M_MDIFF,0)STMT_NET_TXN_6M_MDIFF
    ,ROUND(STMT_NET_TXN_6M_RDIFF,4)STMT_NET_TXN_6M_RDIFF
    ,ROUND(STMT_NET_TXN_12M,0) STMT_NET_TXN_12M
    ,ROUND(STMT_NET_TXN_12M_MDIFF,0)STMT_NET_TXN_12M_MDIFF
    ,ROUND(STMT_NET_TXN_12M_RDIFF,4)STMT_NET_TXN_12M_RDIFF
    
    ,ROUND(STSS_NET_TXN_M,0) STSS_NET_TXN_M
    ,ROUND(STSS_NET_TXN_M_MDIFF,0)STSS_NET_TXN_M_MDIFF
    ,ROUND(STSS_NET_TXN_M_RDIFF,4)STSS_NET_TXN_M_RDIFF
    ,ROUND(STSS_NET_TXN_3M,0) STSS_NET_TXN_3M
    ,ROUND(STSS_NET_TXN_3M_MDIFF,0)STSS_NET_TXN_3M_MDIFF
    ,ROUND(STSS_NET_TXN_3M_RDIFF,4)STSS_NET_TXN_3M_RDIFF
    ,ROUND(STSS_NET_TXN_6M,0) STSS_NET_TXN_6M
    ,ROUND(STSS_NET_TXN_6M_MDIFF,0)STSS_NET_TXN_6M_MDIFF
    ,ROUND(STSS_NET_TXN_6M_RDIFF,4)STSS_NET_TXN_6M_RDIFF
    ,ROUND(STSS_NET_TXN_12M,0) STSS_NET_TXN_12M
    ,ROUND(STSS_NET_TXN_12M_MDIFF,0)STSS_NET_TXN_12M_MDIFF
    ,ROUND(STSS_NET_TXN_12M_RDIFF,4)STSS_NET_TXN_12M_RDIFF

FROM(
    SELECT DISTINCT A.CUSTOMER_ID
        ,A.YYYYMM
        ---台股單筆淨流
        ,NVL(STLS_NET_TXN_M,0)STLS_NET_TXN_M
        ,CASE WHEN NVL(STLS_NET_TXN_M,0)=0 AND NVL(STLS_NET_TXN_L,0)=0 THEN NULL ELSE STLS_NET_TXN_M - STLS_NET_TXN_L END STLS_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(STLS_NET_TXN_L,0)!=0 THEN (NVL(STLS_NET_TXN_M,0)-NVL(STLS_NET_TXN_L,0))/ABS(NVL(STLS_NET_TXN_L,0)) ELSE NULL END AS STLS_NET_TXN_M_RDIFF
        ,NVL(STLS_NET_TXN_3M,0)STLS_NET_TXN_3M
        ,CASE WHEN NVL(STLS_NET_TXN_3M,0)=0 AND NVL(STLS_NET_TXN_3ML,0)=0 THEN NULL ELSE STLS_NET_TXN_3M - STLS_NET_TXN_3ML END STLS_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(STLS_NET_TXN_3ML,0)!=0 THEN (NVL(STLS_NET_TXN_3M,0)-NVL(STLS_NET_TXN_3ML,0))/ABS(NVL(STLS_NET_TXN_3ML,0)) ELSE NULL END AS STLS_NET_TXN_3M_RDIFF
        ,NVL(STLS_NET_TXN_6M,0)STLS_NET_TXN_6M
        ,CASE WHEN NVL(STLS_NET_TXN_6M,0)=0 AND NVL(STLS_NET_TXN_6ML,0)=0 THEN NULL ELSE STLS_NET_TXN_6M - STLS_NET_TXN_6ML END STLS_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(STLS_NET_TXN_6ML,0)!=0 THEN (NVL(STLS_NET_TXN_6M,0)-NVL(STLS_NET_TXN_6ML,0))/ABS(NVL(STLS_NET_TXN_6ML,0)) ELSE NULL END AS STLS_NET_TXN_6M_RDIFF
        ,NVL(STLS_NET_TXN_12M,0)STLS_NET_TXN_12M
        ,CASE WHEN NVL(STLS_NET_TXN_12M,0)=0 AND NVL(STLS_NET_TXN_12ML,0)=0 THEN NULL ELSE STLS_NET_TXN_12M - STLS_NET_TXN_12ML END STLS_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(STLS_NET_TXN_12ML,0)!=0 THEN (NVL(STLS_NET_TXN_12M,0)-NVL(STLS_NET_TXN_12ML,0))/ABS(NVL(STLS_NET_TXN_12ML,0)) ELSE NULL END AS STLS_NET_TXN_12M_RDIFF
        ----台股單筆周轉率
        ,CASE WHEN NVL(STLS_AUM_M,0)!=0 THEN (NVL(STLS_TXN_M,0)/NVL(STLS_AUM_M,0)) ELSE NULL END AS STLS_TURNOVER_M
        ,CASE WHEN NVL(STLS_AUM_L,0)!=0 THEN (NVL(STLS_TXN_L,0)/NVL(STLS_AUM_L,0)) ELSE NULL END AS STLS_TURNOVER_L
        ,CASE WHEN NVL(STLS_AUM_3M,0)!=0 THEN (NVL(STLS_TXN_3M,0)/NVL(STLS_AUM_3M,0)) ELSE NULL END AS STLS_TURNOVER_3M
        ,CASE WHEN NVL(STLS_AUM_3ML,0)!=0 THEN (NVL(STLS_TXN_3ML,0)/NVL(STLS_AUM_3ML,0)) ELSE NULL END AS STLS_TURNOVER_3ML
        ,CASE WHEN NVL(STLS_AUM_6M,0)!=0 THEN (NVL(STLS_TXN_6M,0)/NVL(STLS_AUM_6M,0)) ELSE NULL END AS STLS_TURNOVER_6M
        ,CASE WHEN NVL(STLS_AUM_6ML,0)!=0 THEN (NVL(STLS_TXN_6ML,0)/NVL(STLS_AUM_6ML,0)) ELSE NULL END AS STLS_TURNOVER_6ML
        ,CASE WHEN NVL(STLS_AUM_12M,0)!=0 THEN (NVL(STLS_TXN_12M,0)/NVL(STLS_AUM_12M,0)) ELSE NULL END AS STLS_TURNOVER_12M
        ,CASE WHEN NVL(STLS_AUM_12ML,0)!=0 THEN (NVL(STLS_TXN_12ML,0)/NVL(STLS_AUM_12ML,0)) ELSE NULL END AS STLS_TURNOVER_12ML       
        ----台股定期周轉率
        ,CASE WHEN NVL(STDCA_AUM_M,0)!=0 THEN (NVL(STDCA_TXN_M,0)/NVL(STDCA_AUM_M,0)) ELSE NULL END AS STDCA_TURNOVER_M
        ,CASE WHEN NVL(STDCA_AUM_L,0)!=0 THEN (NVL(STDCA_TXN_L,0)/NVL(STDCA_AUM_L,0)) ELSE NULL END AS STDCA_TURNOVER_L
        ,CASE WHEN NVL(STDCA_AUM_3M,0)!=0 THEN (NVL(STDCA_TXN_3M,0)/NVL(STDCA_AUM_3M,0)) ELSE NULL END AS STDCA_TURNOVER_3M
        ,CASE WHEN NVL(STDCA_AUM_3ML,0)!=0 THEN (NVL(STDCA_TXN_3ML,0)/NVL(STDCA_AUM_3ML,0)) ELSE NULL END AS STDCA_TURNOVER_3ML
        ,CASE WHEN NVL(STDCA_AUM_6M,0)!=0 THEN (NVL(STDCA_TXN_6M,0)/NVL(STDCA_AUM_6M,0)) ELSE NULL END AS STDCA_TURNOVER_6M
        ,CASE WHEN NVL(STDCA_AUM_6ML,0)!=0 THEN (NVL(STDCA_TXN_6ML,0)/NVL(STDCA_AUM_6ML,0)) ELSE NULL END AS STDCA_TURNOVER_6ML
        ,CASE WHEN NVL(STDCA_AUM_12M,0)!=0 THEN (NVL(STDCA_TXN_12M,0)/NVL(STDCA_AUM_12M,0)) ELSE NULL END AS STDCA_TURNOVER_12M
        ,CASE WHEN NVL(STDCA_AUM_12ML,0)!=0 THEN (NVL(STDCA_TXN_12ML,0)/NVL(STDCA_AUM_12ML,0)) ELSE NULL END AS STDCA_TURNOVER_12ML       
        ---基金單筆淨流
        ,NVL(FDLS_NET_TXN_M,0)FDLS_NET_TXN_M
        ,CASE WHEN NVL(FDLS_NET_TXN_M,0)=0 AND NVL(FDLS_NET_TXN_L,0)=0 THEN NULL ELSE FDLS_NET_TXN_M - FDLS_NET_TXN_L END FDLS_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FDLS_NET_TXN_L,0)!=0 THEN (NVL(FDLS_NET_TXN_M,0)-NVL(FDLS_NET_TXN_L,0))/ABS(NVL(FDLS_NET_TXN_L,0)) ELSE NULL END AS FDLS_NET_TXN_M_RDIFF
        ,NVL(FDLS_NET_TXN_3M,0)FDLS_NET_TXN_3M
        ,CASE WHEN NVL(FDLS_NET_TXN_3M,0)=0 AND NVL(FDLS_NET_TXN_3ML,0)=0 THEN NULL ELSE FDLS_NET_TXN_3M - FDLS_NET_TXN_3ML END FDLS_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FDLS_NET_TXN_3ML,0)!=0 THEN (NVL(FDLS_NET_TXN_3M,0)-NVL(FDLS_NET_TXN_3ML,0))/ABS(NVL(FDLS_NET_TXN_3ML,0)) ELSE NULL END AS FDLS_NET_TXN_3M_RDIFF
        ,NVL(FDLS_NET_TXN_6M,0)FDLS_NET_TXN_6M
        ,CASE WHEN NVL(FDLS_NET_TXN_6M,0)=0 AND NVL(FDLS_NET_TXN_6ML,0)=0 THEN NULL ELSE FDLS_NET_TXN_6M - FDLS_NET_TXN_6ML END FDLS_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FDLS_NET_TXN_6ML,0)!=0 THEN (NVL(FDLS_NET_TXN_6M,0)-NVL(FDLS_NET_TXN_6ML,0))/ABS(NVL(FDLS_NET_TXN_6ML,0)) ELSE NULL END AS FDLS_NET_TXN_6M_RDIFF
        ,NVL(FDLS_NET_TXN_12M,0)FDLS_NET_TXN_12M
        ,CASE WHEN NVL(FDLS_NET_TXN_12M,0)=0 AND NVL(FDLS_NET_TXN_12ML,0)=0 THEN NULL ELSE FDLS_NET_TXN_12M - FDLS_NET_TXN_12ML END FDLS_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FDLS_NET_TXN_12ML,0)!=0 THEN (NVL(FDLS_NET_TXN_12M,0)-NVL(FDLS_NET_TXN_12ML,0))/ABS(NVL(FDLS_NET_TXN_12ML,0)) ELSE NULL END AS FDLS_NET_TXN_12M_RDIFF
        ----基金單筆周轉率
        ,CASE WHEN NVL(FDLS_AUM_M,0)!=0 THEN (NVL(FDLS_TXN_M,0)/NVL(FDLS_AUM_M,0)) ELSE NULL END AS FDLS_TURNOVER_M
        ,CASE WHEN NVL(FDLS_AUM_L,0)!=0 THEN (NVL(FDLS_TXN_L,0)/NVL(FDLS_AUM_L,0)) ELSE NULL END AS FDLS_TURNOVER_L
        ,CASE WHEN NVL(FDLS_AUM_3M,0)!=0 THEN (NVL(FDLS_TXN_3M,0)/NVL(FDLS_AUM_3M,0)) ELSE NULL END AS FDLS_TURNOVER_3M
        ,CASE WHEN NVL(FDLS_AUM_3ML,0)!=0 THEN (NVL(FDLS_TXN_3ML,0)/NVL(FDLS_AUM_3ML,0)) ELSE NULL END AS FDLS_TURNOVER_3ML
        ,CASE WHEN NVL(FDLS_AUM_6M,0)!=0 THEN (NVL(FDLS_TXN_6M,0)/NVL(FDLS_AUM_6M,0)) ELSE NULL END AS FDLS_TURNOVER_6M
        ,CASE WHEN NVL(FDLS_AUM_6ML,0)!=0 THEN (NVL(FDLS_TXN_6ML,0)/NVL(FDLS_AUM_6ML,0)) ELSE NULL END AS FDLS_TURNOVER_6ML
        ,CASE WHEN NVL(FDLS_AUM_12M,0)!=0 THEN (NVL(FDLS_TXN_12M,0)/NVL(FDLS_AUM_12M,0)) ELSE NULL END AS FDLS_TURNOVER_12M
        ,CASE WHEN NVL(FDLS_AUM_12ML,0)!=0 THEN (NVL(FDLS_TXN_12ML,0)/NVL(FDLS_AUM_12ML,0)) ELSE NULL END AS FDLS_TURNOVER_12ML       
        ----基金定期周轉率
        ,CASE WHEN NVL(FDDCA_AUM_M,0)!=0 THEN (NVL(FDDCA_TXN_M,0)/NVL(FDDCA_AUM_M,0)) ELSE NULL END AS FDDCA_TURNOVER_M
        ,CASE WHEN NVL(FDDCA_AUM_L,0)!=0 THEN (NVL(FDDCA_TXN_L,0)/NVL(FDDCA_AUM_L,0)) ELSE NULL END AS FDDCA_TURNOVER_L
        ,CASE WHEN NVL(FDDCA_AUM_3M,0)!=0 THEN (NVL(FDDCA_TXN_3M,0)/NVL(FDDCA_AUM_3M,0)) ELSE NULL END AS FDDCA_TURNOVER_3M
        ,CASE WHEN NVL(FDDCA_AUM_3ML,0)!=0 THEN (NVL(FDDCA_TXN_3ML,0)/NVL(FDDCA_AUM_3ML,0)) ELSE NULL END AS FDDCA_TURNOVER_3ML
        ,CASE WHEN NVL(FDDCA_AUM_6M,0)!=0 THEN (NVL(FDDCA_TXN_6M,0)/NVL(FDDCA_AUM_6M,0)) ELSE NULL END AS FDDCA_TURNOVER_6M
        ,CASE WHEN NVL(FDDCA_AUM_6ML,0)!=0 THEN (NVL(FDDCA_TXN_6ML,0)/NVL(FDDCA_AUM_6ML,0)) ELSE NULL END AS FDDCA_TURNOVER_6ML
        ,CASE WHEN NVL(FDDCA_AUM_12M,0)!=0 THEN (NVL(FDDCA_TXN_12M,0)/NVL(FDDCA_AUM_12M,0)) ELSE NULL END AS FDDCA_TURNOVER_12M
        ,CASE WHEN NVL(FDDCA_AUM_12ML,0)!=0 THEN (NVL(FDDCA_TXN_12ML,0)/NVL(FDDCA_AUM_12ML,0)) ELSE NULL END AS FDDCA_TURNOVER_12ML     
        ---海外股單筆淨流
        ,NVL(FSLS_NET_TXN_M,0)FSLS_NET_TXN_M
        ,CASE WHEN NVL(FSLS_NET_TXN_M,0)=0 AND NVL(FSLS_NET_TXN_L,0)=0 THEN NULL ELSE FSLS_NET_TXN_M - FSLS_NET_TXN_L END FSLS_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FSLS_NET_TXN_L,0)!=0 THEN (NVL(FSLS_NET_TXN_M,0)-NVL(FSLS_NET_TXN_L,0))/ABS(NVL(FSLS_NET_TXN_L,0)) ELSE NULL END AS FSLS_NET_TXN_M_RDIFF
        ,NVL(FSLS_NET_TXN_3M,0)FSLS_NET_TXN_3M
        ,CASE WHEN NVL(FSLS_NET_TXN_3M,0)=0 AND NVL(FSLS_NET_TXN_3ML,0)=0 THEN NULL ELSE FSLS_NET_TXN_3M - FSLS_NET_TXN_3ML END FSLS_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FSLS_NET_TXN_3ML,0)!=0 THEN (NVL(FSLS_NET_TXN_3M,0)-NVL(FSLS_NET_TXN_3ML,0))/ABS(NVL(FSLS_NET_TXN_3ML,0)) ELSE NULL END AS FSLS_NET_TXN_3M_RDIFF
        ,NVL(FSLS_NET_TXN_6M,0)FSLS_NET_TXN_6M
        ,CASE WHEN NVL(FSLS_NET_TXN_6M,0)=0 AND NVL(FSLS_NET_TXN_6ML,0)=0 THEN NULL ELSE FSLS_NET_TXN_6M - FSLS_NET_TXN_6ML END FSLS_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FSLS_NET_TXN_6ML,0)!=0 THEN (NVL(FSLS_NET_TXN_6M,0)-NVL(FSLS_NET_TXN_6ML,0))/ABS(NVL(FSLS_NET_TXN_6ML,0)) ELSE NULL END AS FSLS_NET_TXN_6M_RDIFF
        ,NVL(FSLS_NET_TXN_12M,0)FSLS_NET_TXN_12M
        ,CASE WHEN NVL(FSLS_NET_TXN_12M,0)=0 AND NVL(FSLS_NET_TXN_12ML,0)=0 THEN NULL ELSE FSLS_NET_TXN_12M - FSLS_NET_TXN_12ML END FSLS_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FSLS_NET_TXN_12ML,0)!=0 THEN (NVL(FSLS_NET_TXN_12M,0)-NVL(FSLS_NET_TXN_12ML,0))/ABS(NVL(FSLS_NET_TXN_12ML,0)) ELSE NULL END AS FSLS_NET_TXN_12M_RDIFF     
        ---海外股定期淨流
        ,NVL(FSDCA_NET_TXN_M,0)FSDCA_NET_TXN_M
        ,CASE WHEN NVL(FSDCA_NET_TXN_M,0)=0 AND NVL(FSDCA_NET_TXN_L,0)=0 THEN NULL ELSE FSDCA_NET_TXN_M - FSDCA_NET_TXN_L END FSDCA_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FSDCA_NET_TXN_L,0)!=0 THEN (NVL(FSDCA_NET_TXN_M,0)-NVL(FSDCA_NET_TXN_L,0))/ABS(NVL(FSDCA_NET_TXN_L,0)) ELSE NULL END AS FSDCA_NET_TXN_M_RDIFF
        ,NVL(FSDCA_NET_TXN_3M,0)FSDCA_NET_TXN_3M
        ,CASE WHEN NVL(FSDCA_NET_TXN_3M,0)=0 AND NVL(FSDCA_NET_TXN_3ML,0)=0 THEN NULL ELSE FSDCA_NET_TXN_3M - FSDCA_NET_TXN_3ML END FSDCA_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FSDCA_NET_TXN_3ML,0)!=0 THEN (NVL(FSDCA_NET_TXN_3M,0)-NVL(FSDCA_NET_TXN_3ML,0))/ABS(NVL(FSDCA_NET_TXN_3ML,0)) ELSE NULL END AS FSDCA_NET_TXN_3M_RDIFF
        ,NVL(FSDCA_NET_TXN_6M,0)FSDCA_NET_TXN_6M
        ,CASE WHEN NVL(FSDCA_NET_TXN_6M,0)=0 AND NVL(FSDCA_NET_TXN_6ML,0)=0 THEN NULL ELSE FSDCA_NET_TXN_6M - FSDCA_NET_TXN_6ML END FSDCA_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FSDCA_NET_TXN_6ML,0)!=0 THEN (NVL(FSDCA_NET_TXN_6M,0)-NVL(FSDCA_NET_TXN_6ML,0))/ABS(NVL(FSDCA_NET_TXN_6ML,0)) ELSE NULL END AS FSDCA_NET_TXN_6M_RDIFF
        ,NVL(FSDCA_NET_TXN_12M,0)FSDCA_NET_TXN_12M
        ,CASE WHEN NVL(FSDCA_NET_TXN_12M,0)=0 AND NVL(FSDCA_NET_TXN_12ML,0)=0 THEN NULL ELSE FSDCA_NET_TXN_12M - FSDCA_NET_TXN_12ML END FSDCA_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FSDCA_NET_TXN_12ML,0)!=0 THEN (NVL(FSDCA_NET_TXN_12M,0)-NVL(FSDCA_NET_TXN_12ML,0))/ABS(NVL(FSDCA_NET_TXN_12ML,0)) ELSE NULL END AS FSDCA_NET_TXN_12M_RDIFF    
        ---台股融資淨流
        ,NVL(STMT_NET_TXN_M,0)STMT_NET_TXN_M
        ,CASE WHEN NVL(STMT_NET_TXN_M,0)=0 AND NVL(STMT_NET_TXN_L,0)=0 THEN NULL ELSE STMT_NET_TXN_M - STMT_NET_TXN_L END STMT_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(STMT_NET_TXN_L,0)!=0 THEN (NVL(STMT_NET_TXN_M,0)-NVL(STMT_NET_TXN_L,0))/ABS(NVL(STMT_NET_TXN_L,0)) ELSE NULL END AS STMT_NET_TXN_M_RDIFF
        ,NVL(STMT_NET_TXN_3M,0)STMT_NET_TXN_3M
        ,CASE WHEN NVL(STMT_NET_TXN_3M,0)=0 AND NVL(STMT_NET_TXN_3ML,0)=0 THEN NULL ELSE STMT_NET_TXN_3M - STMT_NET_TXN_3ML END STMT_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(STMT_NET_TXN_3ML,0)!=0 THEN (NVL(STMT_NET_TXN_3M,0)-NVL(STMT_NET_TXN_3ML,0))/ABS(NVL(STMT_NET_TXN_3ML,0)) ELSE NULL END AS STMT_NET_TXN_3M_RDIFF
        ,NVL(STMT_NET_TXN_6M,0)STMT_NET_TXN_6M
        ,CASE WHEN NVL(STMT_NET_TXN_6M,0)=0 AND NVL(STMT_NET_TXN_6ML,0)=0 THEN NULL ELSE STMT_NET_TXN_6M - STMT_NET_TXN_6ML END STMT_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(STMT_NET_TXN_6ML,0)!=0 THEN (NVL(STMT_NET_TXN_6M,0)-NVL(STMT_NET_TXN_6ML,0))/ABS(NVL(STMT_NET_TXN_6ML,0)) ELSE NULL END AS STMT_NET_TXN_6M_RDIFF
        ,NVL(STMT_NET_TXN_12M,0)STMT_NET_TXN_12M
        ,CASE WHEN NVL(STMT_NET_TXN_12M,0)=0 AND NVL(STMT_NET_TXN_12ML,0)=0 THEN NULL ELSE STMT_NET_TXN_12M - STMT_NET_TXN_12ML END STMT_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(STMT_NET_TXN_12ML,0)!=0 THEN (NVL(STMT_NET_TXN_12M,0)-NVL(STMT_NET_TXN_12ML,0))/ABS(NVL(STMT_NET_TXN_12ML,0)) ELSE NULL END AS STMT_NET_TXN_12M_RDIFF      
        ---台股融券淨流
        ,NVL(STSS_NET_TXN_M,0)STSS_NET_TXN_M
        ,CASE WHEN NVL(STSS_NET_TXN_M,0)=0 AND NVL(STSS_NET_TXN_L,0)=0 THEN NULL ELSE STSS_NET_TXN_M - STSS_NET_TXN_L END STSS_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(STSS_NET_TXN_L,0)!=0 THEN (NVL(STSS_NET_TXN_M,0)-NVL(STSS_NET_TXN_L,0))/ABS(NVL(STSS_NET_TXN_L,0)) ELSE NULL END AS STSS_NET_TXN_M_RDIFF
        ,NVL(STSS_NET_TXN_3M,0)STSS_NET_TXN_3M
        ,CASE WHEN NVL(STSS_NET_TXN_3M,0)=0 AND NVL(STSS_NET_TXN_3ML,0)=0 THEN NULL ELSE STSS_NET_TXN_3M - STSS_NET_TXN_3ML END STSS_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(STSS_NET_TXN_3ML,0)!=0 THEN (NVL(STSS_NET_TXN_3M,0)-NVL(STSS_NET_TXN_3ML,0))/ABS(NVL(STSS_NET_TXN_3ML,0)) ELSE NULL END AS STSS_NET_TXN_3M_RDIFF
        ,NVL(STSS_NET_TXN_6M,0)STSS_NET_TXN_6M
        ,CASE WHEN NVL(STSS_NET_TXN_6M,0)=0 AND NVL(STSS_NET_TXN_6ML,0)=0 THEN NULL ELSE STSS_NET_TXN_6M - STSS_NET_TXN_6ML END STSS_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(STSS_NET_TXN_6ML,0)!=0 THEN (NVL(STSS_NET_TXN_6M,0)-NVL(STSS_NET_TXN_6ML,0))/ABS(NVL(STSS_NET_TXN_6ML,0)) ELSE NULL END AS STSS_NET_TXN_6M_RDIFF
        ,NVL(STSS_NET_TXN_12M,0)STSS_NET_TXN_12M
        ,CASE WHEN NVL(STSS_NET_TXN_12M,0)=0 AND NVL(STSS_NET_TXN_12ML,0)=0 THEN NULL ELSE STSS_NET_TXN_12M - STSS_NET_TXN_12ML END STSS_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(STSS_NET_TXN_12ML,0)!=0 THEN (NVL(STSS_NET_TXN_12M,0)-NVL(STSS_NET_TXN_12ML,0))/ABS(NVL(STSS_NET_TXN_12ML,0)) ELSE NULL END AS STSS_NET_TXN_12M_RDIFF      
    FROM DS_SEC.CF_CUSTID A
    LEFT JOIN(  
        SELECT PARTY_ID
            ------台股單筆 STLS
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STLS_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STLS_NET_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STLS_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STLS_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STLS_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STLS_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STLS_NET_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STLS_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)STLS_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STLS_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STLS_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STLS_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STLS_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STLS_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STLS_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STLS_TXN_12ML
            
            ------台股定期 STDCA
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('102') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)STDCA_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('102') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STDCA_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('102') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STDCA_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('102') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STDCA_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('102') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STDCA_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('102') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STDCA_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('102') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STDCA_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_CODE IN('102') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STDCA_TXN_12ML
            
            ------基金單筆 FDLS
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDLS_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDLS_NET_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDLS_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDLS_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('120','220','420') AND TXN_TYPE_CODE IN('101') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
