            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('005','007') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STMT_NET_TXN_12ML
            
            ------台股融券 STSS
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STSS_NET_TXN_M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STSS_NET_TXN_L
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STSS_NET_TXN_3M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STSS_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STSS_NET_TXN_6M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STSS_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STSS_NET_TXN_12M
            ,SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_MTYPE_CODE IN ('110') AND TXN_TYPE_DETAIL_CODE IN('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STSS_NET_TXN_12ML
        FROM TEMP4TXN A
        GROUP BY PARTY_ID
    )B ON A.CUSTOMER_ID = B.PARTY_ID
    LEFT JOIN TEMP4AUM C ON A.CUSTOMER_ID = C.CUSTOMER_ID
    WHERE A.YYYYMM = :ym
)
ORDER BY CUSTOMER_ID;
INSERT INTO DS_SEC.CF_PROFOLIO5 
SELECT CUSTOMER_ID
    ,YYYYMM
    ,ROUND(STETF_NET_TXN_M,0) STETF_NET_TXN_M
    ,ROUND(STETF_NET_TXN_M_MDIFF,0) STETF_NET_TXN_M_MDIFF
    ,ROUND(STETF_NET_TXN_M_RDIFF,4) STETF_NET_TXN_M_RDIFF
    ,ROUND(STETF_TURNOVER_M,4) STETF_TURNOVER_M
    ,ROUND(STETF_TURNOVER_M - STETF_TURNOVER_L,4) STETF_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(STETF_TURNOVER_L,0)!=0 THEN (NVL(STETF_TURNOVER_M,0)/NVL(STETF_TURNOVER_L,0))-1 ELSE 0 END,4) AS STETF_TURNOVER_M_RDIFF   
    ,ROUND(STETF_NET_TXN_3M,0) STETF_NET_TXN_3M
    ,ROUND(STETF_NET_TXN_3M_MDIFF,0) STETF_NET_TXN_3M_MDIFF
    ,ROUND(STETF_NET_TXN_3M_RDIFF,4) STETF_NET_TXN_3M_RDIFF
    ,ROUND(STETF_TURNOVER_3M,4) STETF_TURNOVER_3M
    ,ROUND(STETF_TURNOVER_3M - STETF_TURNOVER_3ML,4) STETF_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(STETF_TURNOVER_3ML,0)!=0 THEN (NVL(STETF_TURNOVER_3M,0)/NVL(STETF_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS STETF_TURNOVER_3M_RDIFF
    ,ROUND(STETF_NET_TXN_6M,0) STETF_NET_TXN_6M
    ,ROUND(STETF_NET_TXN_6M_MDIFF,0) STETF_NET_TXN_6M_MDIFF
    ,ROUND(STETF_NET_TXN_6M_RDIFF,4) STETF_NET_TXN_6M_RDIFF
