    ,ROUND(CASE WHEN NVL(STETF_TURNOVER_6ML,0)!=0 THEN (NVL(STETF_TURNOVER_6M,0)/NVL(STETF_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS STETF_TURNOVER_6M_RDIFF
    ,ROUND(STETF_NET_TXN_12M,0) STETF_NET_TXN_12M
    ,ROUND(STETF_NET_TXN_12M_MDIFF,0) STETF_NET_TXN_12M_MDIFF
    ,ROUND(STETF_NET_TXN_12M_RDIFF,4) STETF_NET_TXN_12M_RDIFF
