    ,ROUND(CASE WHEN NVL(STETF_TURNOVER_12ML,0)!=0 THEN (NVL(STETF_TURNOVER_12M,0)/NVL(STETF_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS STETF_TURNOVER_12M_RDIFF
    
    ,ROUND(STWA_NET_TXN_M,0) STWA_NET_TXN_M
    ,ROUND(STWA_NET_TXN_M_MDIFF,0) STWA_NET_TXN_M_MDIFF
    ,ROUND(STWA_NET_TXN_M_RDIFF,4) STWA_NET_TXN_M_RDIFF
    ,ROUND(STWA_TURNOVER_M,4) STWA_TURNOVER_M
    ,ROUND(STWA_TURNOVER_M - STWA_TURNOVER_L,4) STWA_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(STWA_TURNOVER_L,0)!=0 THEN (NVL(STWA_TURNOVER_M,0)/NVL(STWA_TURNOVER_L,0))-1 ELSE 0 END,4) AS STWA_TURNOVER_M_RDIFF
    ,ROUND(STWA_NET_TXN_3M,0) STWA_NET_TXN_3M
    ,ROUND(STWA_NET_TXN_3M_MDIFF,0) STWA_NET_TXN_3M_MDIFF
    ,ROUND(STWA_NET_TXN_3M_RDIFF,4) STWA_NET_TXN_3M_RDIFF
    ,ROUND(STWA_TURNOVER_3M,4) STWA_TURNOVER_3M
    ,ROUND(STWA_TURNOVER_3M - STWA_TURNOVER_3ML,4) STWA_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(STWA_TURNOVER_3ML,0)!=0 THEN (NVL(STWA_TURNOVER_3M,0)/NVL(STWA_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS STWA_TURNOVER_3M_RDIFF
    ,ROUND(STWA_NET_TXN_6M,0) STWA_NET_TXN_6M
    ,ROUND(STWA_NET_TXN_6M_MDIFF,0) STWA_NET_TXN_6M_MDIFF
    ,ROUND(STWA_NET_TXN_6M_RDIFF,4) STWA_NET_TXN_6M_RDIFF
    ,ROUND(STWA_TURNOVER_6M,4) STWA_TURNOVER_6M
    ,ROUND(STWA_TURNOVER_6M - STWA_TURNOVER_6ML,4) STWA_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(STWA_TURNOVER_6ML,0)!=0 THEN (NVL(STWA_TURNOVER_6M,0)/NVL(STWA_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS STWA_TURNOVER_6M_RDIFF
    ,ROUND(STWA_NET_TXN_12M,0) STWA_NET_TXN_12M
    ,ROUND(STWA_NET_TXN_12M_MDIFF,0) STWA_NET_TXN_12M_MDIFF
    ,ROUND(STWA_NET_TXN_12M_RDIFF,4) STWA_NET_TXN_12M_RDIFF
    ,ROUND(STWA_TURNOVER_12M,4) STWA_TURNOVER_12M
    ,ROUND(STWA_TURNOVER_12M - STWA_TURNOVER_12ML,4) STWA_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(STWA_TURNOVER_12ML,0)!=0 THEN (NVL(STWA_TURNOVER_12M,0)/NVL(STWA_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS STWA_TURNOVER_12M_RDIFF
    
    ,ROUND(STGS_NET_TXN_M,0) STGS_NET_TXN_M
    ,ROUND(STGS_NET_TXN_M_MDIFF,0) STGS_NET_TXN_M_MDIFF
    ,ROUND(STGS_NET_TXN_M_RDIFF,4) STGS_NET_TXN_M_RDIFF
    ,ROUND(STGS_TURNOVER_M,4) STGS_TURNOVER_M
    ,ROUND(STGS_TURNOVER_M - STGS_TURNOVER_L,4) STGS_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(STGS_TURNOVER_L,0)!=0 THEN (NVL(STGS_TURNOVER_M,0)/NVL(STGS_TURNOVER_L,0))-1 ELSE 0 END,4) AS STGS_TURNOVER_M_RDIFF
    ,ROUND(STGS_NET_TXN_3M,0) STGS_NET_TXN_3M
    ,ROUND(STGS_NET_TXN_3M_MDIFF,0) STGS_NET_TXN_3M_MDIFF
    ,ROUND(STGS_NET_TXN_3M_RDIFF,4) STGS_NET_TXN_3M_RDIFF
    ,ROUND(STGS_TURNOVER_3M,4) STGS_TURNOVER_3M
    ,ROUND(STGS_TURNOVER_3M - STGS_TURNOVER_3ML,4) STGS_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(STGS_TURNOVER_3ML,0)!=0 THEN (NVL(STGS_TURNOVER_3M,0)/NVL(STGS_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS STGS_TURNOVER_3M_RDIFF
    ,ROUND(STGS_NET_TXN_6M,0) STGS_NET_TXN_6M
    ,ROUND(STGS_NET_TXN_6M_MDIFF,0) STGS_NET_TXN_6M_MDIFF
    ,ROUND(STGS_NET_TXN_6M_RDIFF,4) STGS_NET_TXN_6M_RDIFF
    ,ROUND(STGS_TURNOVER_6M,4) STGS_TURNOVER_6M
    ,ROUND(STGS_TURNOVER_6M - STGS_TURNOVER_6ML,4) STGS_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(STGS_TURNOVER_6ML,0)!=0 THEN (NVL(STGS_TURNOVER_6M,0)/NVL(STGS_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS STGS_TURNOVER_6M_RDIFF
    ,ROUND(STGS_NET_TXN_12M,0) STGS_NET_TXN_12M
    ,ROUND(STGS_NET_TXN_12M_MDIFF,0) STGS_NET_TXN_12M_MDIFF
    ,ROUND(STGS_NET_TXN_12M_RDIFF,4) STGS_NET_TXN_12M_RDIFF
    ,ROUND(STGS_TURNOVER_12M,4) STGS_TURNOVER_12M
    ,ROUND(STGS_TURNOVER_12M - STGS_TURNOVER_12ML,4) STGS_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(STGS_TURNOVER_12ML,0)!=0 THEN (NVL(STGS_TURNOVER_12M,0)/NVL(STGS_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS STGS_TURNOVER_12M_RDIFF
    
    ,ROUND(OST_NET_TXN_M,0) OST_NET_TXN_M
    ,ROUND(OST_NET_TXN_M_MDIFF,0) OST_NET_TXN_M_MDIFF
    ,ROUND(OST_NET_TXN_M_RDIFF,4) OST_NET_TXN_M_RDIFF
    ,ROUND(OST_TURNOVER_M,4) OST_TURNOVER_M
    ,ROUND(OST_TURNOVER_M - OST_TURNOVER_L,4) OST_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(OST_TURNOVER_L,0)!=0 THEN (NVL(OST_TURNOVER_M,0)/NVL(OST_TURNOVER_L,0))-1 ELSE 0 END,4) AS OST_TURNOVER_M_RDIFF
    ,ROUND(OST_NET_TXN_3M,0) OST_NET_TXN_3M
    ,ROUND(OST_NET_TXN_3M_MDIFF,0) OST_NET_TXN_3M_MDIFF
    ,ROUND(OST_NET_TXN_3M_RDIFF,4) OST_NET_TXN_3M_RDIFF
    ,ROUND(OST_TURNOVER_3M,4)OST_TURNOVER_3M
    ,ROUND(OST_TURNOVER_3M - OST_TURNOVER_3ML,4) OST_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(OST_TURNOVER_3ML,0)!=0 THEN (NVL(OST_TURNOVER_3M,0)/NVL(OST_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS OST_TURNOVER_3M_RDIFF
    ,ROUND(OST_NET_TXN_6M,0) OST_NET_TXN_6M
    ,ROUND(OST_NET_TXN_6M_MDIFF,0) OST_NET_TXN_6M_MDIFF
    ,ROUND(OST_NET_TXN_6M_RDIFF,4) OST_NET_TXN_6M_RDIFF
    ,ROUND(OST_TURNOVER_6M,4) OST_TURNOVER_6M
    ,ROUND(OST_TURNOVER_6M - OST_TURNOVER_6ML,4) OST_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(OST_TURNOVER_6ML,0)!=0 THEN (NVL(OST_TURNOVER_6M,0)/NVL(OST_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS OST_TURNOVER_6M_RDIFF
    ,ROUND(OST_NET_TXN_12M,0) OST_NET_TXN_12M
    ,ROUND(OST_NET_TXN_12M_MDIFF,0) OST_NET_TXN_12M_MDIFF
    ,ROUND(OST_NET_TXN_12M_RDIFF,4) OST_NET_TXN_12M_RDIFF
    ,ROUND(OST_TURNOVER_12M,4) OST_TURNOVER_12M
    ,ROUND(OST_TURNOVER_12M - OST_TURNOVER_12ML,4) OST_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(OST_TURNOVER_12ML,0)!=0 THEN (NVL(OST_TURNOVER_12M,0)/NVL(OST_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS OST_TURNOVER_12M_RDIFF
FROM(
    SELECT DISTINCT A.CUSTOMER_ID
        ,A.YYYYMM
        ---股票ETF淨流
        ,NVL(STETF_NET_TXN_M,0)STETF_NET_TXN_M
        ,CASE WHEN NVL(STETF_NET_TXN_M,0)=0 AND NVL(STETF_NET_TXN_L,0)=0 THEN NULL ELSE STETF_NET_TXN_M - STETF_NET_TXN_L END STETF_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(STETF_NET_TXN_L,0)!=0 THEN (NVL(STETF_NET_TXN_M,0)-NVL(STETF_NET_TXN_L,0))/ABS(NVL(STETF_NET_TXN_L,0)) ELSE NULL END AS STETF_NET_TXN_M_RDIFF
        ,NVL(STETF_NET_TXN_3M,0)STETF_NET_TXN_3M
        ,CASE WHEN NVL(STETF_NET_TXN_3M,0)=0 AND NVL(STETF_NET_TXN_3ML,0)=0 THEN NULL ELSE STETF_NET_TXN_3M - STETF_NET_TXN_3ML END STETF_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(STETF_NET_TXN_3ML,0)!=0 THEN (NVL(STETF_NET_TXN_3M,0)-NVL(STETF_NET_TXN_3ML,0))/ABS(NVL(STETF_NET_TXN_3ML,0)) ELSE NULL END AS STETF_NET_TXN_3M_RDIFF
        ,NVL(STETF_NET_TXN_6M,0)STETF_NET_TXN_6M
        ,CASE WHEN NVL(STETF_NET_TXN_6M,0)=0 AND NVL(STETF_NET_TXN_6ML,0)=0 THEN NULL ELSE STETF_NET_TXN_6M - STETF_NET_TXN_6ML END STETF_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(STETF_NET_TXN_6ML,0)!=0 THEN (NVL(STETF_NET_TXN_6M,0)-NVL(STETF_NET_TXN_6ML,0))/ABS(NVL(STETF_NET_TXN_6ML,0)) ELSE NULL END AS STETF_NET_TXN_6M_RDIFF
        ,NVL(STETF_NET_TXN_12M,0)STETF_NET_TXN_12M
        ,CASE WHEN NVL(STETF_NET_TXN_12M,0)=0 AND NVL(STETF_NET_TXN_12ML,0)=0 THEN NULL ELSE STETF_NET_TXN_12M - STETF_NET_TXN_12ML END STETF_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(STETF_NET_TXN_12ML,0)!=0 THEN (NVL(STETF_NET_TXN_12M,0)-NVL(STETF_NET_TXN_12ML,0))/ABS(NVL(STETF_NET_TXN_12ML,0)) ELSE NULL END AS STETF_NET_TXN_12M_RDIFF
        ----股票ETF周轉率
        ,CASE WHEN NVL(STETF_AUM_M,0)!=0 THEN (NVL(STETF_TXN_M,0)/NVL(STETF_AUM_M,0)) ELSE NULL END AS STETF_TURNOVER_M
        ,CASE WHEN NVL(STETF_AUM_L,0)!=0 THEN (NVL(STETF_TXN_L,0)/NVL(STETF_AUM_L,0)) ELSE NULL END AS STETF_TURNOVER_L
        ,CASE WHEN NVL(STETF_AUM_3M,0)!=0 THEN (NVL(STETF_TXN_3M,0)/NVL(STETF_AUM_3M,0)) ELSE NULL END AS STETF_TURNOVER_3M
        ,CASE WHEN NVL(STETF_AUM_3ML,0)!=0 THEN (NVL(STETF_TXN_3ML,0)/NVL(STETF_AUM_3ML,0)) ELSE NULL END AS STETF_TURNOVER_3ML
        ,CASE WHEN NVL(STETF_AUM_6M,0)!=0 THEN (NVL(STETF_TXN_6M,0)/NVL(STETF_AUM_6M,0)) ELSE NULL END AS STETF_TURNOVER_6M
        ,CASE WHEN NVL(STETF_AUM_6ML,0)!=0 THEN (NVL(STETF_TXN_6ML,0)/NVL(STETF_AUM_6ML,0)) ELSE NULL END AS STETF_TURNOVER_6ML
        ,CASE WHEN NVL(STETF_AUM_12M,0)!=0 THEN (NVL(STETF_TXN_12M,0)/NVL(STETF_AUM_12M,0)) ELSE NULL END AS STETF_TURNOVER_12M
        ,CASE WHEN NVL(STETF_AUM_12ML,0)!=0 THEN (NVL(STETF_TXN_12ML,0)/NVL(STETF_AUM_12ML,0)) ELSE NULL END AS STETF_TURNOVER_12ML
        ---認股權證淨流
        ,NVL(STWA_NET_TXN_M,0)STWA_NET_TXN_M
        ,CASE WHEN NVL(STWA_NET_TXN_M,0)=0 AND NVL(STWA_NET_TXN_L,0)=0 THEN NULL ELSE STWA_NET_TXN_M - STWA_NET_TXN_L END STWA_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(STWA_NET_TXN_L,0)!=0 THEN (NVL(STWA_NET_TXN_M,0)-NVL(STWA_NET_TXN_L,0))/ABS(NVL(STWA_NET_TXN_L,0)) ELSE NULL END AS STWA_NET_TXN_M_RDIFF
        ,NVL(STWA_NET_TXN_3M,0)STWA_NET_TXN_3M
        ,CASE WHEN NVL(STWA_NET_TXN_3M,0)=0 AND NVL(STWA_NET_TXN_3ML,0)=0 THEN NULL ELSE STWA_NET_TXN_3M - STWA_NET_TXN_3ML END STWA_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(STWA_NET_TXN_3ML,0)!=0 THEN (NVL(STWA_NET_TXN_3M,0)-NVL(STWA_NET_TXN_3ML,0))/ABS(NVL(STWA_NET_TXN_3ML,0)) ELSE NULL END AS STWA_NET_TXN_3M_RDIFF
        ,NVL(STWA_NET_TXN_6M,0)STWA_NET_TXN_6M
        ,CASE WHEN NVL(STWA_NET_TXN_6M,0)=0 AND NVL(STWA_NET_TXN_6ML,0)=0 THEN NULL ELSE STWA_NET_TXN_6M - STWA_NET_TXN_6ML END STWA_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(STWA_NET_TXN_6ML,0)!=0 THEN (NVL(STWA_NET_TXN_6M,0)-NVL(STWA_NET_TXN_6ML,0))/ABS(NVL(STWA_NET_TXN_6ML,0)) ELSE NULL END AS STWA_NET_TXN_6M_RDIFF
        ,NVL(STWA_NET_TXN_12M,0)STWA_NET_TXN_12M
        ,CASE WHEN NVL(STWA_NET_TXN_12M,0)=0 AND NVL(STWA_NET_TXN_12ML,0)=0 THEN NULL ELSE STWA_NET_TXN_12M - STWA_NET_TXN_12ML END STWA_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(STWA_NET_TXN_12ML,0)!=0 THEN (NVL(STWA_NET_TXN_12M,0)-NVL(STWA_NET_TXN_12ML,0))/ABS(NVL(STWA_NET_TXN_12ML,0)) ELSE NULL END AS STWA_NET_TXN_12M_RDIFF
        ----認股權證周轉率
        ,CASE WHEN NVL(STWA_AUM_M,0)!=0 THEN (NVL(STWA_TXN_M,0)/NVL(STWA_AUM_M,0)) ELSE NULL END AS STWA_TURNOVER_M
        ,CASE WHEN NVL(STWA_AUM_L,0)!=0 THEN (NVL(STWA_TXN_L,0)/NVL(STWA_AUM_L,0)) ELSE NULL END AS STWA_TURNOVER_L
        ,CASE WHEN NVL(STWA_AUM_3M,0)!=0 THEN (NVL(STWA_TXN_3M,0)/NVL(STWA_AUM_3M,0)) ELSE NULL END AS STWA_TURNOVER_3M
        ,CASE WHEN NVL(STWA_AUM_3ML,0)!=0 THEN (NVL(STWA_TXN_3ML,0)/NVL(STWA_AUM_3ML,0)) ELSE NULL END AS STWA_TURNOVER_3ML
        ,CASE WHEN NVL(STWA_AUM_6M,0)!=0 THEN (NVL(STWA_TXN_6M,0)/NVL(STWA_AUM_6M,0)) ELSE NULL END AS STWA_TURNOVER_6M
        ,CASE WHEN NVL(STWA_AUM_6ML,0)!=0 THEN (NVL(STWA_TXN_6ML,0)/NVL(STWA_AUM_6ML,0)) ELSE NULL END AS STWA_TURNOVER_6ML
        ,CASE WHEN NVL(STWA_AUM_12M,0)!=0 THEN (NVL(STWA_TXN_12M,0)/NVL(STWA_AUM_12M,0)) ELSE NULL END AS STWA_TURNOVER_12M
        ,CASE WHEN NVL(STWA_AUM_12ML,0)!=0 THEN (NVL(STWA_TXN_12ML,0)/NVL(STWA_AUM_12ML,0)) ELSE NULL END AS STWA_TURNOVER_12ML
        ---一般股票淨流
        ,NVL(STGS_NET_TXN_M,0)STGS_NET_TXN_M
        ,CASE WHEN NVL(STGS_NET_TXN_M,0)=0 AND NVL(STGS_NET_TXN_L,0)=0 THEN NULL ELSE STGS_NET_TXN_M - STGS_NET_TXN_L END STGS_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(STGS_NET_TXN_L,0)!=0 THEN (NVL(STGS_NET_TXN_M,0)-NVL(STGS_NET_TXN_L,0))/ABS(NVL(STGS_NET_TXN_L,0)) ELSE NULL END AS STGS_NET_TXN_M_RDIFF
        ,NVL(STGS_NET_TXN_3M,0)STGS_NET_TXN_3M
        ,CASE WHEN NVL(STGS_NET_TXN_3M,0)=0 AND NVL(STGS_NET_TXN_3ML,0)=0 THEN NULL ELSE STGS_NET_TXN_3M - STGS_NET_TXN_3ML END STGS_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(STGS_NET_TXN_3ML,0)!=0 THEN (NVL(STGS_NET_TXN_3M,0)-NVL(STGS_NET_TXN_3ML,0))/ABS(NVL(STGS_NET_TXN_3ML,0)) ELSE NULL END AS STGS_NET_TXN_3M_RDIFF
        ,NVL(STGS_NET_TXN_6M,0)STGS_NET_TXN_6M
        ,CASE WHEN NVL(STGS_NET_TXN_6M,0)=0 AND NVL(STGS_NET_TXN_6ML,0)=0 THEN NULL ELSE STGS_NET_TXN_6M - STGS_NET_TXN_6ML END STGS_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(STGS_NET_TXN_6ML,0)!=0 THEN (NVL(STGS_NET_TXN_6M,0)-NVL(STGS_NET_TXN_6ML,0))/ABS(NVL(STGS_NET_TXN_6ML,0)) ELSE NULL END AS STGS_NET_TXN_6M_RDIFF
        ,NVL(STGS_NET_TXN_12M,0)STGS_NET_TXN_12M
        ,CASE WHEN NVL(STGS_NET_TXN_12M,0)=0 AND NVL(STGS_NET_TXN_12ML,0)=0 THEN NULL ELSE STGS_NET_TXN_12M - STGS_NET_TXN_12ML END STGS_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(STGS_NET_TXN_12ML,0)!=0 THEN (NVL(STGS_NET_TXN_12M,0)-NVL(STGS_NET_TXN_12ML,0))/ABS(NVL(STGS_NET_TXN_12ML,0)) ELSE NULL END AS STGS_NET_TXN_12M_RDIFF
        ----一般股票周轉率
        ,CASE WHEN NVL(STGS_AUM_M,0)!=0 THEN (NVL(STGS_TXN_M,0)/NVL(STGS_AUM_M,0)) ELSE NULL END AS STGS_TURNOVER_M
        ,CASE WHEN NVL(STGS_AUM_L,0)!=0 THEN (NVL(STGS_TXN_L,0)/NVL(STGS_AUM_L,0)) ELSE NULL END AS STGS_TURNOVER_L
        ,CASE WHEN NVL(STGS_AUM_3M,0)!=0 THEN (NVL(STGS_TXN_3M,0)/NVL(STGS_AUM_3M,0)) ELSE NULL END AS STGS_TURNOVER_3M
        ,CASE WHEN NVL(STGS_AUM_3ML,0)!=0 THEN (NVL(STGS_TXN_3ML,0)/NVL(STGS_AUM_3ML,0)) ELSE NULL END AS STGS_TURNOVER_3ML
        ,CASE WHEN NVL(STGS_AUM_6M,0)!=0 THEN (NVL(STGS_TXN_6M,0)/NVL(STGS_AUM_6M,0)) ELSE NULL END AS STGS_TURNOVER_6M
        ,CASE WHEN NVL(STGS_AUM_6ML,0)!=0 THEN (NVL(STGS_TXN_6ML,0)/NVL(STGS_AUM_6ML,0)) ELSE NULL END AS STGS_TURNOVER_6ML
        ,CASE WHEN NVL(STGS_AUM_12M,0)!=0 THEN (NVL(STGS_TXN_12M,0)/NVL(STGS_AUM_12M,0)) ELSE NULL END AS STGS_TURNOVER_12M
        ,CASE WHEN NVL(STGS_AUM_12ML,0)!=0 THEN (NVL(STGS_TXN_12ML,0)/NVL(STGS_AUM_12ML,0)) ELSE NULL END AS STGS_TURNOVER_12ML
        ---其他類股票淨流
        ,NVL(OST_NET_TXN_M,0)OST_NET_TXN_M
        ,CASE WHEN NVL(OST_NET_TXN_M,0)=0 AND NVL(OST_NET_TXN_L,0)=0 THEN NULL ELSE OST_NET_TXN_M - OST_NET_TXN_L END OST_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(OST_NET_TXN_L,0)!=0 THEN (NVL(OST_NET_TXN_M,0)-NVL(OST_NET_TXN_L,0))/ABS(NVL(OST_NET_TXN_L,0)) ELSE NULL END AS OST_NET_TXN_M_RDIFF
        ,NVL(OST_NET_TXN_3M,0)OST_NET_TXN_3M
        ,CASE WHEN NVL(OST_NET_TXN_3M,0)=0 AND NVL(OST_NET_TXN_3ML,0)=0 THEN NULL ELSE OST_NET_TXN_3M - OST_NET_TXN_3ML END OST_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(OST_NET_TXN_3ML,0)!=0 THEN (NVL(OST_NET_TXN_3M,0)-NVL(OST_NET_TXN_3ML,0))/ABS(NVL(OST_NET_TXN_3ML,0)) ELSE NULL END AS OST_NET_TXN_3M_RDIFF
        ,NVL(OST_NET_TXN_6M,0)OST_NET_TXN_6M
        ,CASE WHEN NVL(OST_NET_TXN_6M,0)=0 AND NVL(OST_NET_TXN_6ML,0)=0 THEN NULL ELSE OST_NET_TXN_6M - OST_NET_TXN_6ML END OST_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(OST_NET_TXN_6ML,0)!=0 THEN (NVL(OST_NET_TXN_6M,0)-NVL(OST_NET_TXN_6ML,0))/ABS(NVL(OST_NET_TXN_6ML,0)) ELSE NULL END AS OST_NET_TXN_6M_RDIFF
        ,NVL(OST_NET_TXN_12M,0)OST_NET_TXN_12M
        ,CASE WHEN NVL(OST_NET_TXN_12M,0)=0 AND NVL(OST_NET_TXN_12ML,0)=0 THEN NULL ELSE OST_NET_TXN_12M - OST_NET_TXN_12ML END OST_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(OST_NET_TXN_12ML,0)!=0 THEN (NVL(OST_NET_TXN_12M,0)-NVL(OST_NET_TXN_12ML,0))/ABS(NVL(OST_NET_TXN_12ML,0)) ELSE NULL END AS OST_NET_TXN_12M_RDIFF
        ----其他類股票周轉率
        ,CASE WHEN NVL(OST_AUM_M,0)!=0 THEN (NVL(OST_TXN_M,0)/NVL(OST_AUM_M,0)) ELSE NULL END AS OST_TURNOVER_M
        ,CASE WHEN NVL(OST_AUM_L,0)!=0 THEN (NVL(OST_TXN_L,0)/NVL(OST_AUM_L,0)) ELSE NULL END AS OST_TURNOVER_L
        ,CASE WHEN NVL(OST_AUM_3M,0)!=0 THEN (NVL(OST_TXN_3M,0)/NVL(OST_AUM_3M,0)) ELSE NULL END AS OST_TURNOVER_3M
        ,CASE WHEN NVL(OST_AUM_3ML,0)!=0 THEN (NVL(OST_TXN_3ML,0)/NVL(OST_AUM_3ML,0)) ELSE NULL END AS OST_TURNOVER_3ML
        ,CASE WHEN NVL(OST_AUM_6M,0)!=0 THEN (NVL(OST_TXN_6M,0)/NVL(OST_AUM_6M,0)) ELSE NULL END AS OST_TURNOVER_6M
        ,CASE WHEN NVL(OST_AUM_6ML,0)!=0 THEN (NVL(OST_TXN_6ML,0)/NVL(OST_AUM_6ML,0)) ELSE NULL END AS OST_TURNOVER_6ML
        ,CASE WHEN NVL(OST_AUM_12M,0)!=0 THEN (NVL(OST_TXN_12M,0)/NVL(OST_AUM_12M,0)) ELSE NULL END AS OST_TURNOVER_12M
        ,CASE WHEN NVL(OST_AUM_12ML,0)!=0 THEN (NVL(OST_TXN_12ML,0)/NVL(OST_AUM_12ML,0)) ELSE NULL END AS OST_TURNOVER_12ML    
    FROM DS_SEC.CF_CUSTID A
    LEFT JOIN(  
        SELECT PARTY_ID
            ------股票ETF STETF
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STETF_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STETF_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STETF_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STETF_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STETF_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STETF_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STETF_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STETF_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)STETF_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STETF_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STETF_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STETF_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STETF_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STETF_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STETF_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('019') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STETF_TXN_12ML
            
            ------認股權證 STWA
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STWA_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STWA_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STWA_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STWA_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STWA_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STWA_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STWA_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STWA_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)STWA_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STWA_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STWA_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STWA_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STWA_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STWA_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STWA_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('012') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STWA_TXN_12ML
            
            ------一般股票 STGS
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STGS_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STGS_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STGS_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STGS_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STGS_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STGS_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STGS_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)STGS_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)STGS_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STGS_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STGS_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STGS_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STGS_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STGS_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)STGS_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('011') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)STGS_TXN_12ML
            
            ------其他股票 OST
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OST_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OST_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OST_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OST_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OST_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OST_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OST_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OST_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)OST_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OST_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OST_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OST_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OST_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OST_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OST_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('015','017','018','01C') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OST_TXN_12ML
        FROM TEMP4TXN A
        GROUP BY PARTY_ID
    )B ON A.CUSTOMER_ID = B.PARTY_ID
    LEFT JOIN TEMP4AUM C ON A.CUSTOMER_ID = C.CUSTOMER_ID
    WHERE A.YYYYMM = :ym
)
ORDER BY CUSTOMER_ID;
INSERT INTO DS_SEC.CF_PROFOLIO6
SELECT CUSTOMER_ID
    ,YYYYMM
    ,ROUND(FDCU_NET_TXN_M,0) FDCU_NET_TXN_M
    ,ROUND(FDCU_NET_TXN_M_MDIFF,0) FDCU_NET_TXN_M_MDIFF
    ,ROUND(FDCU_NET_TXN_M_RDIFF,4) FDCU_NET_TXN_M_RDIFF
    ,ROUND(FDCU_TURNOVER_M,4) FDCU_TURNOVER_M
    ,ROUND(FDCU_TURNOVER_M - FDCU_TURNOVER_L,4) FDCU_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FDCU_TURNOVER_L,0)!=0 THEN (NVL(FDCU_TURNOVER_M,0)/NVL(FDCU_TURNOVER_L,0))-1 ELSE 0 END,4) AS FDCU_TURNOVER_M_RDIFF
    ,ROUND(FDCU_NET_TXN_3M,0) FDCU_NET_TXN_3M
    ,ROUND(FDCU_NET_TXN_3M_MDIFF,0) FDCU_NET_TXN_3M_MDIFF
    ,ROUND(FDCU_NET_TXN_3M_RDIFF,4) FDCU_NET_TXN_3M_RDIFF
    ,ROUND(FDCU_TURNOVER_3M,4) FDCU_TURNOVER_3M
    ,ROUND(FDCU_TURNOVER_3M - FDCU_TURNOVER_3ML,4) FDCU_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FDCU_TURNOVER_3ML,0)!=0 THEN (NVL(FDCU_TURNOVER_3M,0)/NVL(FDCU_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FDCU_TURNOVER_3M_RDIFF
    ,ROUND(FDCU_NET_TXN_6M,0) FDCU_NET_TXN_6M
    ,ROUND(FDCU_NET_TXN_6M_MDIFF,0) FDCU_NET_TXN_6M_MDIFF
    ,ROUND(FDCU_NET_TXN_6M_RDIFF,4) FDCU_NET_TXN_6M_RDIFF
    ,ROUND(FDCU_TURNOVER_6M,4) FDCU_TURNOVER_6M
    ,ROUND(FDCU_TURNOVER_6M - FDCU_TURNOVER_6ML,4) FDCU_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FDCU_TURNOVER_6ML,0)!=0 THEN (NVL(FDCU_TURNOVER_6M,0)/NVL(FDCU_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FDCU_TURNOVER_6M_RDIFF
    ,ROUND(FDCU_NET_TXN_12M,0) FDCU_NET_TXN_12M
    ,ROUND(FDCU_NET_TXN_12M_MDIFF,0) FDCU_NET_TXN_12M_MDIFF
    ,ROUND(FDCU_NET_TXN_12M_RDIFF,4) FDCU_NET_TXN_12M_RDIFF
    ,ROUND(FDCU_TURNOVER_12M,4) FDCU_TURNOVER_12M
    ,ROUND(FDCU_TURNOVER_12M - FDCU_TURNOVER_12ML,4) FDCU_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FDCU_TURNOVER_12ML,0)!=0 THEN (NVL(FDCU_TURNOVER_12M,0)/NVL(FDCU_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FDCU_TURNOVER_12M_RDIFF
    
    ,ROUND(FDB_NET_TXN_M,0) FDB_NET_TXN_M
    ,ROUND(FDB_NET_TXN_M_MDIFF,0) FDB_NET_TXN_M_MDIFF
    ,ROUND(FDB_NET_TXN_M_RDIFF,4) FDB_NET_TXN_M_RDIFF
    ,ROUND(FDB_TURNOVER_M,4) FDB_TURNOVER_M
    ,ROUND(FDB_TURNOVER_M - FDB_TURNOVER_L,4) FDB_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FDB_TURNOVER_L,0)!=0 THEN (NVL(FDB_TURNOVER_M,0)/NVL(FDB_TURNOVER_L,0))-1 ELSE 0 END,4) AS FDB_TURNOVER_M_RDIFF
    ,ROUND(FDB_NET_TXN_3M,0) FDB_NET_TXN_3M
    ,ROUND(FDB_NET_TXN_3M_MDIFF,0) FDB_NET_TXN_3M_MDIFF
    ,ROUND(FDB_NET_TXN_3M_RDIFF,4) FDB_NET_TXN_3M_RDIFF
    ,ROUND(FDB_TURNOVER_3M,4) FDB_TURNOVER_3M
    ,ROUND(FDB_TURNOVER_3M - FDB_TURNOVER_3ML,4) FDB_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FDB_TURNOVER_3ML,0)!=0 THEN (NVL(FDB_TURNOVER_3M,0)/NVL(FDB_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FDB_TURNOVER_3M_RDIFF
    ,ROUND(FDB_NET_TXN_6M,0) FDB_NET_TXN_6M
    ,ROUND(FDB_NET_TXN_6M_MDIFF,0) FDB_NET_TXN_6M_MDIFF
    ,ROUND(FDB_NET_TXN_6M_RDIFF,4) FDB_NET_TXN_6M_RDIFF
    ,ROUND(FDB_TURNOVER_6M,4) FDB_TURNOVER_6M
    ,ROUND(FDB_TURNOVER_6M - FDB_TURNOVER_6ML,4) FDB_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FDB_TURNOVER_6ML,0)!=0 THEN (NVL(FDB_TURNOVER_6M,0)/NVL(FDB_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FDB_TURNOVER_6M_RDIFF
    ,ROUND(FDB_NET_TXN_12M,0) FDB_NET_TXN_12M
    ,ROUND(FDB_NET_TXN_12M_MDIFF,0) FDB_NET_TXN_12M_MDIFF
    ,ROUND(FDB_NET_TXN_12M_RDIFF,4) FDB_NET_TXN_12M_RDIFF
    ,ROUND(FDB_TURNOVER_12M,4) FDB_TURNOVER_12M
    ,ROUND(FDB_TURNOVER_12M - FDB_TURNOVER_12ML,4) FDB_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FDB_TURNOVER_12ML,0)!=0 THEN (NVL(FDB_TURNOVER_12M,0)/NVL(FDB_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FDB_TURNOVER_12M_RDIFF
    
    ,ROUND(FDST_NET_TXN_M,0) FDST_NET_TXN_M
    ,ROUND(FDST_NET_TXN_M_MDIFF,0) FDST_NET_TXN_M_MDIFF
    ,ROUND(FDST_NET_TXN_M_RDIFF,4) FDST_NET_TXN_M_RDIFF
    ,ROUND(FDST_TURNOVER_M,4) FDST_TURNOVER_M
    ,ROUND(FDST_TURNOVER_M - FDST_TURNOVER_L,4) FDST_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FDST_TURNOVER_L,0)!=0 THEN (NVL(FDST_TURNOVER_M,0)/NVL(FDST_TURNOVER_L,0))-1 ELSE 0 END,4) AS FDST_TURNOVER_M_RDIFF
    ,ROUND(FDST_NET_TXN_3M,0) FDST_NET_TXN_3M
    ,ROUND(FDST_NET_TXN_3M_MDIFF,0) FDST_NET_TXN_3M_MDIFF
    ,ROUND(FDST_NET_TXN_3M_RDIFF,4) FDST_NET_TXN_3M_RDIFF
    ,ROUND(FDST_TURNOVER_3M,4) FDST_TURNOVER_3M
    ,ROUND(FDST_TURNOVER_3M - FDST_TURNOVER_3ML,4) FDST_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FDST_TURNOVER_3ML,0)!=0 THEN (NVL(FDST_TURNOVER_3M,0)/NVL(FDST_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FDST_TURNOVER_3M_RDIFF
    ,ROUND(FDST_NET_TXN_6M,0) FDST_NET_TXN_6M
    ,ROUND(FDST_NET_TXN_6M_MDIFF,0) FDST_NET_TXN_6M_MDIFF
    ,ROUND(FDST_NET_TXN_6M_RDIFF,4) FDST_NET_TXN_6M_RDIFF
    ,ROUND(FDST_TURNOVER_6M,4) FDST_TURNOVER_6M
    ,ROUND(FDST_TURNOVER_6M - FDST_TURNOVER_6ML,4) FDST_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FDST_TURNOVER_6ML,0)!=0 THEN (NVL(FDST_TURNOVER_6M,0)/NVL(FDST_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FDST_TURNOVER_6M_RDIFF
    ,ROUND(FDST_NET_TXN_12M,0) FDST_NET_TXN_12M
    ,ROUND(FDST_NET_TXN_12M_MDIFF,0) FDST_NET_TXN_12M_MDIFF
    ,ROUND(FDST_NET_TXN_12M_RDIFF,4) FDST_NET_TXN_12M_RDIFF
    ,ROUND(FDST_TURNOVER_12M,4) FDST_TURNOVER_12M
    ,ROUND(FDST_TURNOVER_12M - FDST_TURNOVER_12ML,4) FDST_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FDST_TURNOVER_12ML,0)!=0 THEN (NVL(FDST_TURNOVER_12M,0)/NVL(FDST_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FDST_TURNOVER_12M_RDIFF
    
    ,ROUND(FDBA_NET_TXN_M,0) FDBA_NET_TXN_M
    ,ROUND(FDBA_NET_TXN_M_MDIFF,0) FDBA_NET_TXN_M_MDIFF
    ,ROUND(FDBA_NET_TXN_M_RDIFF,4) FDBA_NET_TXN_M_RDIFF
    ,ROUND(FDBA_TURNOVER_M,4) FDBA_TURNOVER_M
    ,ROUND(FDBA_TURNOVER_M - FDBA_TURNOVER_L,4) FDBA_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FDBA_TURNOVER_L,0)!=0 THEN (NVL(FDBA_TURNOVER_M,0)/NVL(FDBA_TURNOVER_L,0))-1 ELSE 0 END,4) AS FDBA_TURNOVER_M_RDIFF
    ,ROUND(FDBA_NET_TXN_3M,0) FDBA_NET_TXN_3M
    ,ROUND(FDBA_NET_TXN_3M_MDIFF,0) FDBA_NET_TXN_3M_MDIFF
    ,ROUND(FDBA_NET_TXN_3M_RDIFF,4) FDBA_NET_TXN_3M_RDIFF
    ,ROUND(FDBA_TURNOVER_3M,4) FDBA_TURNOVER_3M
    ,ROUND(FDBA_TURNOVER_3M - FDBA_TURNOVER_3ML,4) FDBA_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FDBA_TURNOVER_3ML,0)!=0 THEN (NVL(FDBA_TURNOVER_3M,0)/NVL(FDBA_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FDBA_TURNOVER_3M_RDIFF
    ,ROUND(FDBA_NET_TXN_6M,0) FDBA_NET_TXN_6M
    ,ROUND(FDBA_NET_TXN_6M_MDIFF,0) FDBA_NET_TXN_6M_MDIFF
    ,ROUND(FDBA_NET_TXN_6M_RDIFF,4) FDBA_NET_TXN_6M_RDIFF
    ,ROUND(FDBA_TURNOVER_6M,4) FDBA_TURNOVER_6M
    ,ROUND(FDBA_TURNOVER_6M - FDBA_TURNOVER_6ML,4) FDBA_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FDBA_TURNOVER_6ML,0)!=0 THEN (NVL(FDBA_TURNOVER_6M,0)/NVL(FDBA_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FDBA_TURNOVER_6M_RDIFF
    ,ROUND(FDBA_NET_TXN_12M,0) FDBA_NET_TXN_12M
    ,ROUND(FDBA_NET_TXN_12M_MDIFF,0) FDBA_NET_TXN_12M_MDIFF
    ,ROUND(FDBA_NET_TXN_12M_RDIFF,4) FDBA_NET_TXN_12M_RDIFF
    ,ROUND(FDBA_TURNOVER_12M,4) FDBA_TURNOVER_12M
    ,ROUND(FDBA_TURNOVER_12M - FDBA_TURNOVER_12ML,4) FDBA_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FDBA_TURNOVER_12ML,0)!=0 THEN (NVL(FDBA_TURNOVER_12M,0)/NVL(FDBA_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FDBA_TURNOVER_12M_RDIFF
    
    ,ROUND(OFD_NET_TXN_M,0) OFD_NET_TXN_M
    ,ROUND(OFD_NET_TXN_M_MDIFF,0) OFD_NET_TXN_M_MDIFF
    ,ROUND(OFD_NET_TXN_M_RDIFF,4) OFD_NET_TXN_M_RDIFF
    ,ROUND(OFD_TURNOVER_M,4) OFD_TURNOVER_M
    ,ROUND(OFD_TURNOVER_M - OFD_TURNOVER_L,4) OFD_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(OFD_TURNOVER_L,0)!=0 THEN (NVL(OFD_TURNOVER_M,0)/NVL(OFD_TURNOVER_L,0))-1 ELSE 0 END,4) AS OFD_TURNOVER_M_RDIFF
    ,ROUND(OFD_NET_TXN_3M,0) OFD_NET_TXN_3M
    ,ROUND(OFD_NET_TXN_3M_MDIFF,0) OFD_NET_TXN_3M_MDIFF
    ,ROUND(OFD_NET_TXN_3M_RDIFF,4) OFD_NET_TXN_3M_RDIFF
    ,ROUND(OFD_TURNOVER_3M,4) OFD_TURNOVER_3M
    ,ROUND(OFD_TURNOVER_3M - OFD_TURNOVER_3ML,4) OFD_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(OFD_TURNOVER_3ML,0)!=0 THEN (NVL(OFD_TURNOVER_3M,0)/NVL(OFD_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS OFD_TURNOVER_3M_RDIFF
    ,ROUND(OFD_NET_TXN_6M,0) OFD_NET_TXN_6M
    ,ROUND(OFD_NET_TXN_6M_MDIFF,0) OFD_NET_TXN_6M_MDIFF
    ,ROUND(OFD_NET_TXN_6M_RDIFF,4) OFD_NET_TXN_6M_RDIFF
    ,ROUND(OFD_TURNOVER_6M,4) OFD_TURNOVER_6M
    ,ROUND(OFD_TURNOVER_6M - OFD_TURNOVER_6ML,4) OFD_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(OFD_TURNOVER_6ML,0)!=0 THEN (NVL(OFD_TURNOVER_6M,0)/NVL(OFD_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS OFD_TURNOVER_6M_RDIFF
    ,ROUND(OFD_NET_TXN_12M,0) OFD_NET_TXN_12M
    ,ROUND(OFD_NET_TXN_12M_MDIFF,0) OFD_NET_TXN_12M_MDIFF
    ,ROUND(OFD_NET_TXN_12M_RDIFF,4) OFD_NET_TXN_12M_RDIFF
    ,ROUND(OFD_TURNOVER_12M,4) OFD_TURNOVER_12M
    ,ROUND(OFD_TURNOVER_12M - OFD_TURNOVER_12ML,4) OFD_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(OFD_TURNOVER_12ML,0)!=0 THEN (NVL(OFD_TURNOVER_12M,0)/NVL(OFD_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS OFD_TURNOVER_12M_RDIFF

FROM(
    SELECT DISTINCT A.CUSTOMER_ID
        ,A.YYYYMM
        ----貨幣型基金淨流
        ,NVL(FDCU_NET_TXN_M,0)FDCU_NET_TXN_M
        ,CASE WHEN NVL(FDCU_NET_TXN_M,0)=0 AND NVL(FDCU_NET_TXN_L,0)=0 THEN NULL ELSE FDCU_NET_TXN_M - FDCU_NET_TXN_L END FDCU_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FDCU_NET_TXN_L,0)!=0 THEN (NVL(FDCU_NET_TXN_M,0)-NVL(FDCU_NET_TXN_L,0))/ABS(NVL(FDCU_NET_TXN_L,0)) ELSE NULL END AS FDCU_NET_TXN_M_RDIFF
        ,NVL(FDCU_NET_TXN_3M,0)FDCU_NET_TXN_3M
        ,CASE WHEN NVL(FDCU_NET_TXN_3M,0)=0 AND NVL(FDCU_NET_TXN_3ML,0)=0 THEN NULL ELSE FDCU_NET_TXN_3M - FDCU_NET_TXN_3ML END FDCU_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FDCU_NET_TXN_3ML,0)!=0 THEN (NVL(FDCU_NET_TXN_3M,0)-NVL(FDCU_NET_TXN_3ML,0))/ABS(NVL(FDCU_NET_TXN_3ML,0)) ELSE NULL END AS FDCU_NET_TXN_3M_RDIFF
        ,NVL(FDCU_NET_TXN_6M,0)FDCU_NET_TXN_6M
        ,CASE WHEN NVL(FDCU_NET_TXN_6M,0)=0 AND NVL(FDCU_NET_TXN_6ML,0)=0 THEN NULL ELSE FDCU_NET_TXN_6M - FDCU_NET_TXN_6ML END FDCU_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FDCU_NET_TXN_6ML,0)!=0 THEN (NVL(FDCU_NET_TXN_6M,0)-NVL(FDCU_NET_TXN_6ML,0))/ABS(NVL(FDCU_NET_TXN_6ML,0)) ELSE NULL END AS FDCU_NET_TXN_6M_RDIFF
        ,NVL(FDCU_NET_TXN_12M,0)FDCU_NET_TXN_12M
        ,CASE WHEN NVL(FDCU_NET_TXN_12M,0)=0 AND NVL(FDCU_NET_TXN_12ML,0)=0 THEN NULL ELSE FDCU_NET_TXN_12M - FDCU_NET_TXN_12ML END FDCU_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FDCU_NET_TXN_12ML,0)!=0 THEN (NVL(FDCU_NET_TXN_12M,0)-NVL(FDCU_NET_TXN_12ML,0))/ABS(NVL(FDCU_NET_TXN_12ML,0)) ELSE NULL END AS FDCU_NET_TXN_12M_RDIFF
        ----貨幣型基金周轉率
        ,CASE WHEN NVL(FDCU_AUM_M,0)!=0 THEN (NVL(FDCU_TXN_M,0)/NVL(FDCU_AUM_M,0)) ELSE NULL END AS FDCU_TURNOVER_M
        ,CASE WHEN NVL(FDCU_AUM_L,0)!=0 THEN (NVL(FDCU_TXN_L,0)/NVL(FDCU_AUM_L,0)) ELSE NULL END AS FDCU_TURNOVER_L
        ,CASE WHEN NVL(FDCU_AUM_3M,0)!=0 THEN (NVL(FDCU_TXN_3M,0)/NVL(FDCU_AUM_3M,0)) ELSE NULL END AS FDCU_TURNOVER_3M
        ,CASE WHEN NVL(FDCU_AUM_3ML,0)!=0 THEN (NVL(FDCU_TXN_3ML,0)/NVL(FDCU_AUM_3ML,0)) ELSE NULL END AS FDCU_TURNOVER_3ML
        ,CASE WHEN NVL(FDCU_AUM_6M,0)!=0 THEN (NVL(FDCU_TXN_6M,0)/NVL(FDCU_AUM_6M,0)) ELSE NULL END AS FDCU_TURNOVER_6M
        ,CASE WHEN NVL(FDCU_AUM_6ML,0)!=0 THEN (NVL(FDCU_TXN_6ML,0)/NVL(FDCU_AUM_6ML,0)) ELSE NULL END AS FDCU_TURNOVER_6ML
        ,CASE WHEN NVL(FDCU_AUM_12M,0)!=0 THEN (NVL(FDCU_TXN_12M,0)/NVL(FDCU_AUM_12M,0)) ELSE NULL END AS FDCU_TURNOVER_12M
        ,CASE WHEN NVL(FDCU_AUM_12ML,0)!=0 THEN (NVL(FDCU_TXN_12ML,0)/NVL(FDCU_AUM_12ML,0)) ELSE NULL END AS FDCU_TURNOVER_12ML
        ----債券型基金淨流
        ,NVL(FDB_NET_TXN_M,0)FDB_NET_TXN_M
        ,CASE WHEN NVL(FDB_NET_TXN_M,0)=0 AND NVL(FDB_NET_TXN_L,0)=0 THEN NULL ELSE FDB_NET_TXN_M - FDB_NET_TXN_L END FDB_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FDB_NET_TXN_L,0)!=0 THEN (NVL(FDB_NET_TXN_M,0)-NVL(FDB_NET_TXN_L,0))/ABS(NVL(FDB_NET_TXN_L,0)) ELSE NULL END AS FDB_NET_TXN_M_RDIFF
        ,NVL(FDB_NET_TXN_3M,0)FDB_NET_TXN_3M
        ,CASE WHEN NVL(FDB_NET_TXN_3M,0)=0 AND NVL(FDB_NET_TXN_3ML,0)=0 THEN NULL ELSE FDB_NET_TXN_3M - FDB_NET_TXN_3ML END FDB_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FDB_NET_TXN_3ML,0)!=0 THEN (NVL(FDB_NET_TXN_3M,0)-NVL(FDB_NET_TXN_3ML,0))/ABS(NVL(FDB_NET_TXN_3ML,0)) ELSE NULL END AS FDB_NET_TXN_3M_RDIFF
        ,NVL(FDB_NET_TXN_6M,0)FDB_NET_TXN_6M
        ,CASE WHEN NVL(FDB_NET_TXN_6M,0)=0 AND NVL(FDB_NET_TXN_6ML,0)=0 THEN NULL ELSE FDB_NET_TXN_6M - FDB_NET_TXN_6ML END FDB_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FDB_NET_TXN_6ML,0)!=0 THEN (NVL(FDB_NET_TXN_6M,0)-NVL(FDB_NET_TXN_6ML,0))/ABS(NVL(FDB_NET_TXN_6ML,0)) ELSE NULL END AS FDB_NET_TXN_6M_RDIFF
        ,NVL(FDB_NET_TXN_12M,0)FDB_NET_TXN_12M
        ,CASE WHEN NVL(FDB_NET_TXN_12M,0)=0 AND NVL(FDB_NET_TXN_12ML,0)=0 THEN NULL ELSE FDB_NET_TXN_12M - FDB_NET_TXN_12ML END FDB_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FDB_NET_TXN_12ML,0)!=0 THEN (NVL(FDB_NET_TXN_12M,0)-NVL(FDB_NET_TXN_12ML,0))/ABS(NVL(FDB_NET_TXN_12ML,0)) ELSE NULL END AS FDB_NET_TXN_12M_RDIFF
        ----債券型基金周轉率
        ,CASE WHEN NVL(FDB_AUM_M,0)!=0 THEN (NVL(FDB_TXN_M,0)/NVL(FDB_AUM_M,0)) ELSE NULL END AS FDB_TURNOVER_M
        ,CASE WHEN NVL(FDB_AUM_L,0)!=0 THEN (NVL(FDB_TXN_L,0)/NVL(FDB_AUM_L,0)) ELSE NULL END AS FDB_TURNOVER_L
        ,CASE WHEN NVL(FDB_AUM_3M,0)!=0 THEN (NVL(FDB_TXN_3M,0)/NVL(FDB_AUM_3M,0)) ELSE NULL END AS FDB_TURNOVER_3M
        ,CASE WHEN NVL(FDB_AUM_3ML,0)!=0 THEN (NVL(FDB_TXN_3ML,0)/NVL(FDB_AUM_3ML,0)) ELSE NULL END AS FDB_TURNOVER_3ML
        ,CASE WHEN NVL(FDB_AUM_6M,0)!=0 THEN (NVL(FDB_TXN_6M,0)/NVL(FDB_AUM_6M,0)) ELSE NULL END AS FDB_TURNOVER_6M
        ,CASE WHEN NVL(FDB_AUM_6ML,0)!=0 THEN (NVL(FDB_TXN_6ML,0)/NVL(FDB_AUM_6ML,0)) ELSE NULL END AS FDB_TURNOVER_6ML
        ,CASE WHEN NVL(FDB_AUM_12M,0)!=0 THEN (NVL(FDB_TXN_12M,0)/NVL(FDB_AUM_12M,0)) ELSE NULL END AS FDB_TURNOVER_12M
        ,CASE WHEN NVL(FDB_AUM_12ML,0)!=0 THEN (NVL(FDB_TXN_12ML,0)/NVL(FDB_AUM_12ML,0)) ELSE NULL END AS FDB_TURNOVER_12ML
        ----股票型基金淨流
        ,NVL(FDST_NET_TXN_M,0)FDST_NET_TXN_M
        ,CASE WHEN NVL(FDST_NET_TXN_M,0)=0 AND NVL(FDST_NET_TXN_L,0)=0 THEN NULL ELSE FDST_NET_TXN_M - FDST_NET_TXN_L END FDST_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FDST_NET_TXN_L,0)!=0 THEN (NVL(FDST_NET_TXN_M,0)-NVL(FDST_NET_TXN_L,0))/ABS(NVL(FDST_NET_TXN_L,0)) ELSE NULL END AS FDST_NET_TXN_M_RDIFF
        ,NVL(FDST_NET_TXN_3M,0)FDST_NET_TXN_3M
        ,CASE WHEN NVL(FDST_NET_TXN_3M,0)=0 AND NVL(FDST_NET_TXN_3ML,0)=0 THEN NULL ELSE FDST_NET_TXN_3M - FDST_NET_TXN_3ML END FDST_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FDST_NET_TXN_3ML,0)!=0 THEN (NVL(FDST_NET_TXN_3M,0)-NVL(FDST_NET_TXN_3ML,0))/ABS(NVL(FDST_NET_TXN_3ML,0)) ELSE NULL END AS FDST_NET_TXN_3M_RDIFF
        ,NVL(FDST_NET_TXN_6M,0)FDST_NET_TXN_6M
        ,CASE WHEN NVL(FDST_NET_TXN_6M,0)=0 AND NVL(FDST_NET_TXN_6ML,0)=0 THEN NULL ELSE FDST_NET_TXN_6M - FDST_NET_TXN_6ML END FDST_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FDST_NET_TXN_6ML,0)!=0 THEN (NVL(FDST_NET_TXN_6M,0)-NVL(FDST_NET_TXN_6ML,0))/ABS(NVL(FDST_NET_TXN_6ML,0)) ELSE NULL END AS FDST_NET_TXN_6M_RDIFF
        ,NVL(FDST_NET_TXN_12M,0)FDST_NET_TXN_12M
        ,CASE WHEN NVL(FDST_NET_TXN_12M,0)=0 AND NVL(FDST_NET_TXN_12ML,0)=0 THEN NULL ELSE FDST_NET_TXN_12M - FDST_NET_TXN_12ML END FDST_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FDST_NET_TXN_12ML,0)!=0 THEN (NVL(FDST_NET_TXN_12M,0)-NVL(FDST_NET_TXN_12ML,0))/ABS(NVL(FDST_NET_TXN_12ML,0)) ELSE NULL END AS FDST_NET_TXN_12M_RDIFF
        ----股票型基金周轉率
        ,CASE WHEN NVL(FDST_AUM_M,0)!=0 THEN (NVL(FDST_TXN_M,0)/NVL(FDST_AUM_M,0)) ELSE NULL END AS FDST_TURNOVER_M
        ,CASE WHEN NVL(FDST_AUM_L,0)!=0 THEN (NVL(FDST_TXN_L,0)/NVL(FDST_AUM_L,0)) ELSE NULL END AS FDST_TURNOVER_L
        ,CASE WHEN NVL(FDST_AUM_3M,0)!=0 THEN (NVL(FDST_TXN_3M,0)/NVL(FDST_AUM_3M,0)) ELSE NULL END AS FDST_TURNOVER_3M
        ,CASE WHEN NVL(FDST_AUM_3ML,0)!=0 THEN (NVL(FDST_TXN_3ML,0)/NVL(FDST_AUM_3ML,0)) ELSE NULL END AS FDST_TURNOVER_3ML
        ,CASE WHEN NVL(FDST_AUM_6M,0)!=0 THEN (NVL(FDST_TXN_6M,0)/NVL(FDST_AUM_6M,0)) ELSE NULL END AS FDST_TURNOVER_6M
        ,CASE WHEN NVL(FDST_AUM_6ML,0)!=0 THEN (NVL(FDST_TXN_6ML,0)/NVL(FDST_AUM_6ML,0)) ELSE NULL END AS FDST_TURNOVER_6ML
        ,CASE WHEN NVL(FDST_AUM_12M,0)!=0 THEN (NVL(FDST_TXN_12M,0)/NVL(FDST_AUM_12M,0)) ELSE NULL END AS FDST_TURNOVER_12M
        ,CASE WHEN NVL(FDST_AUM_12ML,0)!=0 THEN (NVL(FDST_TXN_12ML,0)/NVL(FDST_AUM_12ML,0)) ELSE NULL END AS FDST_TURNOVER_12ML
        ----平衡多重基金淨流
        ,NVL(FDBA_NET_TXN_M,0)FDBA_NET_TXN_M
        ,CASE WHEN NVL(FDBA_NET_TXN_M,0)=0 AND NVL(FDBA_NET_TXN_L,0)=0 THEN NULL ELSE FDBA_NET_TXN_M - FDBA_NET_TXN_L END FDBA_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FDBA_NET_TXN_L,0)!=0 THEN (NVL(FDBA_NET_TXN_M,0)-NVL(FDBA_NET_TXN_L,0))/ABS(NVL(FDBA_NET_TXN_L,0)) ELSE NULL END AS FDBA_NET_TXN_M_RDIFF
        ,NVL(FDBA_NET_TXN_3M,0)FDBA_NET_TXN_3M
        ,CASE WHEN NVL(FDBA_NET_TXN_3M,0)=0 AND NVL(FDBA_NET_TXN_3ML,0)=0 THEN NULL ELSE FDBA_NET_TXN_3M - FDBA_NET_TXN_3ML END FDBA_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FDBA_NET_TXN_3ML,0)!=0 THEN (NVL(FDBA_NET_TXN_3M,0)-NVL(FDBA_NET_TXN_3ML,0))/ABS(NVL(FDBA_NET_TXN_3ML,0)) ELSE NULL END AS FDBA_NET_TXN_3M_RDIFF
        ,NVL(FDBA_NET_TXN_6M,0)FDBA_NET_TXN_6M
        ,CASE WHEN NVL(FDBA_NET_TXN_6M,0)=0 AND NVL(FDBA_NET_TXN_6ML,0)=0 THEN NULL ELSE FDBA_NET_TXN_6M - FDBA_NET_TXN_6ML END FDBA_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FDBA_NET_TXN_6ML,0)!=0 THEN (NVL(FDBA_NET_TXN_6M,0)-NVL(FDBA_NET_TXN_6ML,0))/ABS(NVL(FDBA_NET_TXN_6ML,0)) ELSE NULL END AS FDBA_NET_TXN_6M_RDIFF
        ,NVL(FDBA_NET_TXN_12M,0)FDBA_NET_TXN_12M
        ,CASE WHEN NVL(FDBA_NET_TXN_12M,0)=0 AND NVL(FDBA_NET_TXN_12ML,0)=0 THEN NULL ELSE FDBA_NET_TXN_12M - FDBA_NET_TXN_12ML END FDBA_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FDBA_NET_TXN_12ML,0)!=0 THEN (NVL(FDBA_NET_TXN_12M,0)-NVL(FDBA_NET_TXN_12ML,0))/ABS(NVL(FDBA_NET_TXN_12ML,0)) ELSE NULL END AS FDBA_NET_TXN_12M_RDIFF
        ----平衡多重基金周轉率
        ,CASE WHEN NVL(FDBA_AUM_M,0)!=0 THEN (NVL(FDBA_TXN_M,0)/NVL(FDBA_AUM_M,0)) ELSE NULL END AS FDBA_TURNOVER_M
        ,CASE WHEN NVL(FDBA_AUM_L,0)!=0 THEN (NVL(FDBA_TXN_L,0)/NVL(FDBA_AUM_L,0)) ELSE NULL END AS FDBA_TURNOVER_L
        ,CASE WHEN NVL(FDBA_AUM_3M,0)!=0 THEN (NVL(FDBA_TXN_3M,0)/NVL(FDBA_AUM_3M,0)) ELSE NULL END AS FDBA_TURNOVER_3M
        ,CASE WHEN NVL(FDBA_AUM_3ML,0)!=0 THEN (NVL(FDBA_TXN_3ML,0)/NVL(FDBA_AUM_3ML,0)) ELSE NULL END AS FDBA_TURNOVER_3ML
        ,CASE WHEN NVL(FDBA_AUM_6M,0)!=0 THEN (NVL(FDBA_TXN_6M,0)/NVL(FDBA_AUM_6M,0)) ELSE NULL END AS FDBA_TURNOVER_6M
        ,CASE WHEN NVL(FDBA_AUM_6ML,0)!=0 THEN (NVL(FDBA_TXN_6ML,0)/NVL(FDBA_AUM_6ML,0)) ELSE NULL END AS FDBA_TURNOVER_6ML
        ,CASE WHEN NVL(FDBA_AUM_12M,0)!=0 THEN (NVL(FDBA_TXN_12M,0)/NVL(FDBA_AUM_12M,0)) ELSE NULL END AS FDBA_TURNOVER_12M
        ,CASE WHEN NVL(FDBA_AUM_12ML,0)!=0 THEN (NVL(FDBA_TXN_12ML,0)/NVL(FDBA_AUM_12ML,0)) ELSE NULL END AS FDBA_TURNOVER_12ML
        ----其他型基金淨流
        ,NVL(OFD_NET_TXN_M,0)OFD_NET_TXN_M
        ,CASE WHEN NVL(OFD_NET_TXN_M,0)=0 AND NVL(OFD_NET_TXN_L,0)=0 THEN NULL ELSE OFD_NET_TXN_M - OFD_NET_TXN_L END OFD_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(OFD_NET_TXN_L,0)!=0 THEN (NVL(OFD_NET_TXN_M,0)-NVL(OFD_NET_TXN_L,0))/ABS(NVL(OFD_NET_TXN_L,0)) ELSE NULL END AS OFD_NET_TXN_M_RDIFF
        ,NVL(OFD_NET_TXN_3M,0)OFD_NET_TXN_3M
        ,CASE WHEN NVL(OFD_NET_TXN_3M,0)=0 AND NVL(OFD_NET_TXN_3ML,0)=0 THEN NULL ELSE OFD_NET_TXN_3M - OFD_NET_TXN_3ML END OFD_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(OFD_NET_TXN_3ML,0)!=0 THEN (NVL(OFD_NET_TXN_3M,0)-NVL(OFD_NET_TXN_3ML,0))/ABS(NVL(OFD_NET_TXN_3ML,0)) ELSE NULL END AS OFD_NET_TXN_3M_RDIFF
        ,NVL(OFD_NET_TXN_6M,0)OFD_NET_TXN_6M
        ,CASE WHEN NVL(OFD_NET_TXN_6M,0)=0 AND NVL(OFD_NET_TXN_6ML,0)=0 THEN NULL ELSE OFD_NET_TXN_6M - OFD_NET_TXN_6ML END OFD_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(OFD_NET_TXN_6ML,0)!=0 THEN (NVL(OFD_NET_TXN_6M,0)-NVL(OFD_NET_TXN_6ML,0))/ABS(NVL(OFD_NET_TXN_6ML,0)) ELSE NULL END AS OFD_NET_TXN_6M_RDIFF
        ,NVL(OFD_NET_TXN_12M,0)OFD_NET_TXN_12M
        ,CASE WHEN NVL(OFD_NET_TXN_12M,0)=0 AND NVL(OFD_NET_TXN_12ML,0)=0 THEN NULL ELSE OFD_NET_TXN_12M - OFD_NET_TXN_12ML END OFD_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(OFD_NET_TXN_12ML,0)!=0 THEN (NVL(OFD_NET_TXN_12M,0)-NVL(OFD_NET_TXN_12ML,0))/ABS(NVL(OFD_NET_TXN_12ML,0)) ELSE NULL END AS OFD_NET_TXN_12M_RDIFF
        ----其他型基金周轉率
        ,CASE WHEN NVL(OFD_AUM_M,0)!=0 THEN (NVL(OFD_TXN_M,0)/NVL(OFD_AUM_M,0)) ELSE NULL END AS OFD_TURNOVER_M
        ,CASE WHEN NVL(OFD_AUM_L,0)!=0 THEN (NVL(OFD_TXN_L,0)/NVL(OFD_AUM_L,0)) ELSE NULL END AS OFD_TURNOVER_L
        ,CASE WHEN NVL(OFD_AUM_3M,0)!=0 THEN (NVL(OFD_TXN_3M,0)/NVL(OFD_AUM_3M,0)) ELSE NULL END AS OFD_TURNOVER_3M
        ,CASE WHEN NVL(OFD_AUM_3ML,0)!=0 THEN (NVL(OFD_TXN_3ML,0)/NVL(OFD_AUM_3ML,0)) ELSE NULL END AS OFD_TURNOVER_3ML
        ,CASE WHEN NVL(OFD_AUM_6M,0)!=0 THEN (NVL(OFD_TXN_6M,0)/NVL(OFD_AUM_6M,0)) ELSE NULL END AS OFD_TURNOVER_6M
        ,CASE WHEN NVL(OFD_AUM_6ML,0)!=0 THEN (NVL(OFD_TXN_6ML,0)/NVL(OFD_AUM_6ML,0)) ELSE NULL END AS OFD_TURNOVER_6ML
        ,CASE WHEN NVL(OFD_AUM_12M,0)!=0 THEN (NVL(OFD_TXN_12M,0)/NVL(OFD_AUM_12M,0)) ELSE NULL END AS OFD_TURNOVER_12M
        ,CASE WHEN NVL(OFD_AUM_12ML,0)!=0 THEN (NVL(OFD_TXN_12ML,0)/NVL(OFD_AUM_12ML,0)) ELSE NULL END AS OFD_TURNOVER_12ML
    FROM DS_SEC.CF_CUSTID A
    LEFT JOIN(  
        SELECT PARTY_ID
            ------貨幣型基金 FDCU
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDCU_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDCU_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDCU_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDCU_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDCU_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDCU_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDCU_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDCU_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)FDCU_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDCU_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDCU_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDCU_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDCU_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDCU_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDCU_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('024') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDCU_TXN_12ML
            
            ------債券型基金 FDB
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDB_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDB_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDB_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDB_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDB_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDB_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDB_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDB_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)FDB_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDB_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDB_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDB_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDB_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDB_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDB_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('022','027') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDB_TXN_12ML
            
            ------股票型基金 FDST
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDST_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDST_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDST_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDST_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDST_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDST_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDST_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDST_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)FDST_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDST_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDST_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDST_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDST_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDST_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDST_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('021') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDST_TXN_12ML
            
            ------平衡及多重基金 FDBA
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDBA_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDBA_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDBA_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDBA_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDBA_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDBA_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDBA_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FDBA_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)FDBA_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDBA_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDBA_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDBA_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDBA_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDBA_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)FDBA_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('023') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)FDBA_TXN_12ML
            
            ------其他基金 OFD
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OFD_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OFD_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OFD_NET_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OFD_NET_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OFD_NET_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OFD_NET_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OFD_NET_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)OFD_NET_TXN_12ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM = :ym THEN TXN_AMT_TWD ELSE 0 END)OFD_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OFD_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OFD_TXN_3M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OFD_TXN_3ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OFD_TXN_6M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OFD_TXN_6ML
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN TXN_AMT_TWD ELSE 0 END)OFD_TXN_12M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('025','026') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN TXN_AMT_TWD ELSE 0 END)OFD_TXN_12ML

        FROM TEMP4TXN A
        GROUP BY PARTY_ID
    )B ON A.CUSTOMER_ID = B.PARTY_ID
    LEFT JOIN TEMP4AUM C ON A.CUSTOMER_ID = C.CUSTOMER_ID
    WHERE A.YYYYMM = :ym
)
ORDER BY CUSTOMER_ID;
INSERT INTO DS_SEC.CF_PROFOLIO7
SELECT CUSTOMER_ID
    ,YYYYMM
    ,ROUND(FBG_NET_TXN_M,0) FBG_NET_TXN_M
    ,ROUND(FBG_NET_TXN_M_MDIFF,0) FBG_NET_TXN_M_MDIFF
    ,ROUND(FBG_NET_TXN_M_RDIFF,4) FBG_NET_TXN_M_RDIFF
    ,ROUND(FBG_TURNOVER_M,4) FBG_TURNOVER_M
    ,ROUND(FBG_TURNOVER_M - FBG_TURNOVER_L,4) FBG_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FBG_TURNOVER_L,0)!=0 THEN (NVL(FBG_TURNOVER_M,0)/NVL(FBG_TURNOVER_L,0))-1 ELSE 0 END,4) AS FBG_TURNOVER_M_RDIFF
    ,ROUND(FBG_NET_TXN_3M,0) FBG_NET_TXN_3M
    ,ROUND(FBG_NET_TXN_3M_MDIFF,0) FBG_NET_TXN_3M_MDIFF
    ,ROUND(FBG_NET_TXN_3M_RDIFF,4) FBG_NET_TXN_3M_RDIFF
    ,ROUND(FBG_TURNOVER_3M,4) FBG_TURNOVER_3M
    ,ROUND(FBG_TURNOVER_3M - FBG_TURNOVER_3ML,4) FBG_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FBG_TURNOVER_3ML,0)!=0 THEN (NVL(FBG_TURNOVER_3M,0)/NVL(FBG_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FBG_TURNOVER_3M_RDIFF
    ,ROUND(FBG_NET_TXN_6M,0) FBG_NET_TXN_6M
    ,ROUND(FBG_NET_TXN_6M_MDIFF,0) FBG_NET_TXN_6M_MDIFF
    ,ROUND(FBG_NET_TXN_6M_RDIFF,4) FBG_NET_TXN_6M_RDIFF
    ,ROUND(FBG_TURNOVER_6M,4) FBG_TURNOVER_6M
    ,ROUND(FBG_TURNOVER_6M - FBG_TURNOVER_6ML,4) FBG_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FBG_TURNOVER_6ML,0)!=0 THEN (NVL(FBG_TURNOVER_6M,0)/NVL(FBG_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FBG_TURNOVER_6M_RDIFF
    ,ROUND(FBG_NET_TXN_12M,0) FBG_NET_TXN_12M
    ,ROUND(FBG_NET_TXN_12M_MDIFF,0) FBG_NET_TXN_12M_MDIFF
    ,ROUND(FBG_NET_TXN_12M_RDIFF,4) FBG_NET_TXN_12M_RDIFF
    ,ROUND(FBG_TURNOVER_12M,4) FBG_TURNOVER_12M
    ,ROUND(FBG_TURNOVER_12M - FBG_TURNOVER_12ML,4) FBG_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FBG_TURNOVER_12ML,0)!=0 THEN (NVL(FBG_TURNOVER_12M,0)/NVL(FBG_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FBG_TURNOVER_12M_RDIFF
    ,ROUND(FBC_NET_TXN_M,0) FBC_NET_TXN_M
    ,ROUND(FBC_NET_TXN_M_MDIFF,0) FBC_NET_TXN_M_MDIFF
    ,ROUND(FBC_NET_TXN_M_RDIFF,4) FBC_NET_TXN_M_RDIFF
    ,ROUND(FBC_TURNOVER_M,4) FBC_TURNOVER_M
    ,ROUND(FBC_TURNOVER_M - FBC_TURNOVER_L,4) FBC_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FBC_TURNOVER_L,0)!=0 THEN (NVL(FBC_TURNOVER_M,0)/NVL(FBC_TURNOVER_L,0))-1 ELSE 0 END,4) AS FBC_TURNOVER_M_RDIFF
    ,ROUND(FBC_NET_TXN_3M,0) FBC_NET_TXN_3M
    ,ROUND(FBC_NET_TXN_3M_MDIFF,0) FBC_NET_TXN_3M_MDIFF
    ,ROUND(FBC_NET_TXN_3M_RDIFF,4) FBC_NET_TXN_3M_RDIFF
    ,ROUND(FBC_TURNOVER_3M,4) FBC_TURNOVER_3M
    ,ROUND(FBC_TURNOVER_3M - FBC_TURNOVER_3ML,4) FBC_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FBC_TURNOVER_3ML,0)!=0 THEN (NVL(FBC_TURNOVER_3M,0)/NVL(FBC_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FBC_TURNOVER_3M_RDIFF
    ,ROUND(FBC_NET_TXN_6M,0) FBC_NET_TXN_6M
    ,ROUND(FBC_NET_TXN_6M_MDIFF,0) FBC_NET_TXN_6M_MDIFF
    ,ROUND(FBC_NET_TXN_6M_RDIFF,4) FBC_NET_TXN_6M_RDIFF
    ,ROUND(FBC_TURNOVER_6M,4) FBC_TURNOVER_6M
    ,ROUND(FBC_TURNOVER_6M - FBC_TURNOVER_6ML,4) FBC_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FBC_TURNOVER_6ML,0)!=0 THEN (NVL(FBC_TURNOVER_6M,0)/NVL(FBC_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FBC_TURNOVER_6M_RDIFF
    ,ROUND(FBC_NET_TXN_12M,0) FBC_NET_TXN_12M
    ,ROUND(FBC_NET_TXN_12M_MDIFF,0) FBC_NET_TXN_12M_MDIFF
    ,ROUND(FBC_NET_TXN_12M_RDIFF,4) FBC_NET_TXN_12M_RDIFF
    ,ROUND(FBC_TURNOVER_12M,4) FBC_TURNOVER_12M
    ,ROUND(FBC_TURNOVER_12M - FBC_TURNOVER_12ML,4) FBC_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FBC_TURNOVER_12ML,0)!=0 THEN (NVL(FBC_TURNOVER_12M,0)/NVL(FBC_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FBC_TURNOVER_12M_RDIFF
    ,ROUND(FBF_NET_TXN_M,0) FBF_NET_TXN_M
    ,ROUND(FBF_NET_TXN_M_MDIFF,0) FBF_NET_TXN_M_MDIFF
    ,ROUND(FBF_NET_TXN_M_RDIFF,4) FBF_NET_TXN_M_RDIFF
    ,ROUND(FBF_TURNOVER_M,4) FBF_TURNOVER_M
    ,ROUND(FBF_TURNOVER_M - FBF_TURNOVER_L,4) FBF_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(FBF_TURNOVER_L,0)!=0 THEN (NVL(FBF_TURNOVER_M,0)/NVL(FBF_TURNOVER_L,0))-1 ELSE 0 END,4) AS FBF_TURNOVER_M_RDIFF
    ,ROUND(FBF_NET_TXN_3M,0) FBF_NET_TXN_3M
    ,ROUND(FBF_NET_TXN_3M_MDIFF,0) FBF_NET_TXN_3M_MDIFF
    ,ROUND(FBF_NET_TXN_3M_RDIFF,4) FBF_NET_TXN_3M_RDIFF
    ,ROUND(FBF_TURNOVER_3M,4) FBF_TURNOVER_3M
    ,ROUND(FBF_TURNOVER_3M - FBF_TURNOVER_3ML,4) FBF_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(FBF_TURNOVER_3ML,0)!=0 THEN (NVL(FBF_TURNOVER_3M,0)/NVL(FBF_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS FBF_TURNOVER_3M_RDIFF
    ,ROUND(FBF_NET_TXN_6M,0) FBF_NET_TXN_6M
    ,ROUND(FBF_NET_TXN_6M_MDIFF,0) FBF_NET_TXN_6M_MDIFF
    ,ROUND(FBF_NET_TXN_6M_RDIFF,4) FBF_NET_TXN_6M_RDIFF
    ,ROUND(FBF_TURNOVER_6M,4) FBF_TURNOVER_6M
    ,ROUND(FBF_TURNOVER_6M - FBF_TURNOVER_6ML,4) FBF_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(FBF_TURNOVER_6ML,0)!=0 THEN (NVL(FBF_TURNOVER_6M,0)/NVL(FBF_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS FBF_TURNOVER_6M_RDIFF
    ,ROUND(FBF_NET_TXN_12M,0) FBF_NET_TXN_12M
    ,ROUND(FBF_NET_TXN_12M_MDIFF,0) FBF_NET_TXN_12M_MDIFF
    ,ROUND(FBF_NET_TXN_12M_RDIFF,4) FBF_NET_TXN_12M_RDIFF
    ,ROUND(FBF_TURNOVER_12M,4) FBF_TURNOVER_12M
    ,ROUND(FBF_TURNOVER_12M - FBF_TURNOVER_12ML,4) FBF_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(FBF_TURNOVER_12ML,0)!=0 THEN (NVL(FBF_TURNOVER_12M,0)/NVL(FBF_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS FBF_TURNOVER_12M_RDIFF
    ,ROUND(OFB_NET_TXN_M,0) OFB_NET_TXN_M
    ,ROUND(OFB_NET_TXN_M_MDIFF,0) OFB_NET_TXN_M_MDIFF
    ,ROUND(OFB_NET_TXN_M_RDIFF,4) OFB_NET_TXN_M_RDIFF
    ,ROUND(OFB_TURNOVER_M,4) OFB_TURNOVER_M
    ,ROUND(OFB_TURNOVER_M - OFB_TURNOVER_L,4) OFB_TURNOVER_M_MDIFF
    ,ROUND(CASE WHEN NVL(OFB_TURNOVER_L,0)!=0 THEN (NVL(OFB_TURNOVER_M,0)/NVL(OFB_TURNOVER_L,0))-1 ELSE 0 END,4) AS OFB_TURNOVER_M_RDIFF
    ,ROUND(OFB_NET_TXN_3M,0) OFB_NET_TXN_3M
    ,ROUND(OFB_NET_TXN_3M_MDIFF,0) OFB_NET_TXN_3M_MDIFF
    ,ROUND(OFB_NET_TXN_3M_RDIFF,4) OFB_NET_TXN_3M_RDIFF
    ,ROUND(OFB_TURNOVER_3M,4) OFB_TURNOVER_3M
    ,ROUND(OFB_TURNOVER_3M - OFB_TURNOVER_3ML,4) OFB_TURNOVER_3M_MDIFF
    ,ROUND(CASE WHEN NVL(OFB_TURNOVER_3ML,0)!=0 THEN (NVL(OFB_TURNOVER_3M,0)/NVL(OFB_TURNOVER_3ML,0))-1 ELSE 0 END,4) AS OFB_TURNOVER_3M_RDIFF
    ,ROUND(OFB_NET_TXN_6M,0) OFB_NET_TXN_6M
    ,ROUND(OFB_NET_TXN_6M_MDIFF,0) OFB_NET_TXN_6M_MDIFF
    ,ROUND(OFB_NET_TXN_6M_RDIFF,4) OFB_NET_TXN_6M_RDIFF
    ,ROUND(OFB_TURNOVER_6M,4) OFB_TURNOVER_6M
    ,ROUND(OFB_TURNOVER_6M - OFB_TURNOVER_6ML,4) OFB_TURNOVER_6M_MDIFF
    ,ROUND(CASE WHEN NVL(OFB_TURNOVER_6ML,0)!=0 THEN (NVL(OFB_TURNOVER_6M,0)/NVL(OFB_TURNOVER_6ML,0))-1 ELSE 0 END,4) AS OFB_TURNOVER_6M_RDIFF
    ,ROUND(OFB_NET_TXN_12M,0) OFB_NET_TXN_12M
    ,ROUND(OFB_NET_TXN_12M_MDIFF,0) OFB_NET_TXN_12M_MDIFF
    ,ROUND(OFB_NET_TXN_12M_RDIFF,4) OFB_NET_TXN_12M_RDIFF
    ,ROUND(OFB_TURNOVER_12M,4) OFB_TURNOVER_12M
    ,ROUND(OFB_TURNOVER_12M - OFB_TURNOVER_12ML,4) OFB_TURNOVER_12M_MDIFF
    ,ROUND(CASE WHEN NVL(OFB_TURNOVER_12ML,0)!=0 THEN (NVL(OFB_TURNOVER_12M,0)/NVL(OFB_TURNOVER_12ML,0))-1 ELSE 0 END,4) AS OFB_TURNOVER_12M_RDIFF
FROM(
    SELECT DISTINCT A.CUSTOMER_ID
        ,A.YYYYMM
        ----公債淨流
        ,NVL(FBG_NET_TXN_M,0)FBG_NET_TXN_M
        ,CASE WHEN NVL(FBG_NET_TXN_M,0)=0 AND NVL(FBG_NET_TXN_L,0)=0 THEN NULL ELSE FBG_NET_TXN_M - FBG_NET_TXN_L END FBG_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FBG_NET_TXN_L,0)!=0 THEN (NVL(FBG_NET_TXN_M,0)-NVL(FBG_NET_TXN_L,0))/ABS(NVL(FBG_NET_TXN_L,0)) ELSE NULL END AS FBG_NET_TXN_M_RDIFF
        ,NVL(FBG_NET_TXN_3M,0)FBG_NET_TXN_3M
        ,CASE WHEN NVL(FBG_NET_TXN_3M,0)=0 AND NVL(FBG_NET_TXN_3ML,0)=0 THEN NULL ELSE FBG_NET_TXN_3M - FBG_NET_TXN_3ML END FBG_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FBG_NET_TXN_3ML,0)!=0 THEN (NVL(FBG_NET_TXN_3M,0)-NVL(FBG_NET_TXN_3ML,0))/ABS(NVL(FBG_NET_TXN_3ML,0)) ELSE NULL END AS FBG_NET_TXN_3M_RDIFF
        ,NVL(FBG_NET_TXN_6M,0)FBG_NET_TXN_6M
        ,CASE WHEN NVL(FBG_NET_TXN_6M,0)=0 AND NVL(FBG_NET_TXN_6ML,0)=0 THEN NULL ELSE FBG_NET_TXN_6M - FBG_NET_TXN_6ML END FBG_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FBG_NET_TXN_6ML,0)!=0 THEN (NVL(FBG_NET_TXN_6M,0)-NVL(FBG_NET_TXN_6ML,0))/ABS(NVL(FBG_NET_TXN_6ML,0)) ELSE NULL END AS FBG_NET_TXN_6M_RDIFF
        ,NVL(FBG_NET_TXN_12M,0)FBG_NET_TXN_12M
        ,CASE WHEN NVL(FBG_NET_TXN_12M,0)=0 AND NVL(FBG_NET_TXN_12ML,0)=0 THEN NULL ELSE FBG_NET_TXN_12M - FBG_NET_TXN_12ML END FBG_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FBG_NET_TXN_12ML,0)!=0 THEN (NVL(FBG_NET_TXN_12M,0)-NVL(FBG_NET_TXN_12ML,0))/ABS(NVL(FBG_NET_TXN_12ML,0)) ELSE NULL END AS FBG_NET_TXN_12M_RDIFF
        ----公債周轉率
        ,CASE WHEN NVL(FBG_AUM_M,0)!=0 THEN (NVL(FBG_TXN_M,0)/NVL(FBG_AUM_M,0)) ELSE NULL END AS FBG_TURNOVER_M
        ,CASE WHEN NVL(FBG_AUM_L,0)!=0 THEN (NVL(FBG_TXN_L,0)/NVL(FBG_AUM_L,0)) ELSE NULL END AS FBG_TURNOVER_L
        ,CASE WHEN NVL(FBG_AUM_3M,0)!=0 THEN (NVL(FBG_TXN_3M,0)/NVL(FBG_AUM_3M,0)) ELSE NULL END AS FBG_TURNOVER_3M
        ,CASE WHEN NVL(FBG_AUM_3ML,0)!=0 THEN (NVL(FBG_TXN_3ML,0)/NVL(FBG_AUM_3ML,0)) ELSE NULL END AS FBG_TURNOVER_3ML
        ,CASE WHEN NVL(FBG_AUM_6M,0)!=0 THEN (NVL(FBG_TXN_6M,0)/NVL(FBG_AUM_6M,0)) ELSE NULL END AS FBG_TURNOVER_6M
        ,CASE WHEN NVL(FBG_AUM_6ML,0)!=0 THEN (NVL(FBG_TXN_6ML,0)/NVL(FBG_AUM_6ML,0)) ELSE NULL END AS FBG_TURNOVER_6ML
        ,CASE WHEN NVL(FBG_AUM_12M,0)!=0 THEN (NVL(FBG_TXN_12M,0)/NVL(FBG_AUM_12M,0)) ELSE NULL END AS FBG_TURNOVER_12M
        ,CASE WHEN NVL(FBG_AUM_12ML,0)!=0 THEN (NVL(FBG_TXN_12ML,0)/NVL(FBG_AUM_12ML,0)) ELSE NULL END AS FBG_TURNOVER_12ML
        ----公司債淨流
        ,NVL(FBC_NET_TXN_M,0)FBC_NET_TXN_M
        ,CASE WHEN NVL(FBC_NET_TXN_M,0)=0 AND NVL(FBC_NET_TXN_L,0)=0 THEN NULL ELSE FBC_NET_TXN_M - FBC_NET_TXN_L END FBC_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FBC_NET_TXN_L,0)!=0 THEN (NVL(FBC_NET_TXN_M,0)-NVL(FBC_NET_TXN_L,0))/ABS(NVL(FBC_NET_TXN_L,0)) ELSE NULL END AS FBC_NET_TXN_M_RDIFF
        ,NVL(FBC_NET_TXN_3M,0)FBC_NET_TXN_3M
        ,CASE WHEN NVL(FBC_NET_TXN_3M,0)=0 AND NVL(FBC_NET_TXN_3ML,0)=0 THEN NULL ELSE FBC_NET_TXN_3M - FBC_NET_TXN_3ML END FBC_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FBC_NET_TXN_3ML,0)!=0 THEN (NVL(FBC_NET_TXN_3M,0)-NVL(FBC_NET_TXN_3ML,0))/ABS(NVL(FBC_NET_TXN_3ML,0)) ELSE NULL END AS FBC_NET_TXN_3M_RDIFF
        ,NVL(FBC_NET_TXN_6M,0)FBC_NET_TXN_6M
        ,CASE WHEN NVL(FBC_NET_TXN_6M,0)=0 AND NVL(FBC_NET_TXN_6ML,0)=0 THEN NULL ELSE FBC_NET_TXN_6M - FBC_NET_TXN_6ML END FBC_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FBC_NET_TXN_6ML,0)!=0 THEN (NVL(FBC_NET_TXN_6M,0)-NVL(FBC_NET_TXN_6ML,0))/ABS(NVL(FBC_NET_TXN_6ML,0)) ELSE NULL END AS FBC_NET_TXN_6M_RDIFF
        ,NVL(FBC_NET_TXN_12M,0)FBC_NET_TXN_12M
        ,CASE WHEN NVL(FBC_NET_TXN_12M,0)=0 AND NVL(FBC_NET_TXN_12ML,0)=0 THEN NULL ELSE FBC_NET_TXN_12M - FBC_NET_TXN_12ML END FBC_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FBC_NET_TXN_12ML,0)!=0 THEN (NVL(FBC_NET_TXN_12M,0)-NVL(FBC_NET_TXN_12ML,0))/ABS(NVL(FBC_NET_TXN_12ML,0)) ELSE NULL END AS FBC_NET_TXN_12M_RDIFF
        ----公司債周轉率
        ,CASE WHEN NVL(FBC_AUM_M,0)!=0 THEN (NVL(FBC_TXN_M,0)/NVL(FBC_AUM_M,0)) ELSE NULL END AS FBC_TURNOVER_M
        ,CASE WHEN NVL(FBC_AUM_L,0)!=0 THEN (NVL(FBC_TXN_L,0)/NVL(FBC_AUM_L,0)) ELSE NULL END AS FBC_TURNOVER_L
        ,CASE WHEN NVL(FBC_AUM_3M,0)!=0 THEN (NVL(FBC_TXN_3M,0)/NVL(FBC_AUM_3M,0)) ELSE NULL END AS FBC_TURNOVER_3M
        ,CASE WHEN NVL(FBC_AUM_3ML,0)!=0 THEN (NVL(FBC_TXN_3ML,0)/NVL(FBC_AUM_3ML,0)) ELSE NULL END AS FBC_TURNOVER_3ML
        ,CASE WHEN NVL(FBC_AUM_6M,0)!=0 THEN (NVL(FBC_TXN_6M,0)/NVL(FBC_AUM_6M,0)) ELSE NULL END AS FBC_TURNOVER_6M
        ,CASE WHEN NVL(FBC_AUM_6ML,0)!=0 THEN (NVL(FBC_TXN_6ML,0)/NVL(FBC_AUM_6ML,0)) ELSE NULL END AS FBC_TURNOVER_6ML
        ,CASE WHEN NVL(FBC_AUM_12M,0)!=0 THEN (NVL(FBC_TXN_12M,0)/NVL(FBC_AUM_12M,0)) ELSE NULL END AS FBC_TURNOVER_12M
        ,CASE WHEN NVL(FBC_AUM_12ML,0)!=0 THEN (NVL(FBC_TXN_12ML,0)/NVL(FBC_AUM_12ML,0)) ELSE NULL END AS FBC_TURNOVER_12ML
        ----金融債淨流
        ,NVL(FBF_NET_TXN_M,0)FBF_NET_TXN_M
        ,CASE WHEN NVL(FBF_NET_TXN_M,0)=0 AND NVL(FBF_NET_TXN_L,0)=0 THEN NULL ELSE FBF_NET_TXN_M - FBF_NET_TXN_L END FBF_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(FBF_NET_TXN_L,0)!=0 THEN (NVL(FBF_NET_TXN_M,0)-NVL(FBF_NET_TXN_L,0))/ABS(NVL(FBF_NET_TXN_L,0)) ELSE NULL END AS FBF_NET_TXN_M_RDIFF
        ,NVL(FBF_NET_TXN_3M,0)FBF_NET_TXN_3M
        ,CASE WHEN NVL(FBF_NET_TXN_3M,0)=0 AND NVL(FBF_NET_TXN_3ML,0)=0 THEN NULL ELSE FBF_NET_TXN_3M - FBF_NET_TXN_3ML END FBF_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(FBF_NET_TXN_3ML,0)!=0 THEN (NVL(FBF_NET_TXN_3M,0)-NVL(FBF_NET_TXN_3ML,0))/ABS(NVL(FBF_NET_TXN_3ML,0)) ELSE NULL END AS FBF_NET_TXN_3M_RDIFF
        ,NVL(FBF_NET_TXN_6M,0)FBF_NET_TXN_6M
        ,CASE WHEN NVL(FBF_NET_TXN_6M,0)=0 AND NVL(FBF_NET_TXN_6ML,0)=0 THEN NULL ELSE FBF_NET_TXN_6M - FBF_NET_TXN_6ML END FBF_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(FBF_NET_TXN_6ML,0)!=0 THEN (NVL(FBF_NET_TXN_6M,0)-NVL(FBF_NET_TXN_6ML,0))/ABS(NVL(FBF_NET_TXN_6ML,0)) ELSE NULL END AS FBF_NET_TXN_6M_RDIFF
        ,NVL(FBF_NET_TXN_12M,0)FBF_NET_TXN_12M
        ,CASE WHEN NVL(FBF_NET_TXN_12M,0)=0 AND NVL(FBF_NET_TXN_12ML,0)=0 THEN NULL ELSE FBF_NET_TXN_12M - FBF_NET_TXN_12ML END FBF_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(FBF_NET_TXN_12ML,0)!=0 THEN (NVL(FBF_NET_TXN_12M,0)-NVL(FBF_NET_TXN_12ML,0))/ABS(NVL(FBF_NET_TXN_12ML,0)) ELSE NULL END AS FBF_NET_TXN_12M_RDIFF
        ----金融債周轉率
        ,CASE WHEN NVL(FBF_AUM_M,0)!=0 THEN (NVL(FBF_TXN_M,0)/NVL(FBF_AUM_M,0)) ELSE NULL END AS FBF_TURNOVER_M
        ,CASE WHEN NVL(FBF_AUM_L,0)!=0 THEN (NVL(FBF_TXN_L,0)/NVL(FBF_AUM_L,0)) ELSE NULL END AS FBF_TURNOVER_L
        ,CASE WHEN NVL(FBF_AUM_3M,0)!=0 THEN (NVL(FBF_TXN_3M,0)/NVL(FBF_AUM_3M,0)) ELSE NULL END AS FBF_TURNOVER_3M
        ,CASE WHEN NVL(FBF_AUM_3ML,0)!=0 THEN (NVL(FBF_TXN_3ML,0)/NVL(FBF_AUM_3ML,0)) ELSE NULL END AS FBF_TURNOVER_3ML
        ,CASE WHEN NVL(FBF_AUM_6M,0)!=0 THEN (NVL(FBF_TXN_6M,0)/NVL(FBF_AUM_6M,0)) ELSE NULL END AS FBF_TURNOVER_6M
        ,CASE WHEN NVL(FBF_AUM_6ML,0)!=0 THEN (NVL(FBF_TXN_6ML,0)/NVL(FBF_AUM_6ML,0)) ELSE NULL END AS FBF_TURNOVER_6ML
        ,CASE WHEN NVL(FBF_AUM_12M,0)!=0 THEN (NVL(FBF_TXN_12M,0)/NVL(FBF_AUM_12M,0)) ELSE NULL END AS FBF_TURNOVER_12M
        ,CASE WHEN NVL(FBF_AUM_12ML,0)!=0 THEN (NVL(FBF_TXN_12ML,0)/NVL(FBF_AUM_12ML,0)) ELSE NULL END AS FBF_TURNOVER_12ML
        ----其他海外債淨流
        ,NVL(OFB_NET_TXN_M,0)OFB_NET_TXN_M
        ,CASE WHEN NVL(OFB_NET_TXN_M,0)=0 AND NVL(OFB_NET_TXN_L,0)=0 THEN NULL ELSE OFB_NET_TXN_M - OFB_NET_TXN_L END OFB_NET_TXN_M_MDIFF
        ,CASE WHEN NVL(OFB_NET_TXN_L,0)!=0 THEN (NVL(OFB_NET_TXN_M,0)-NVL(OFB_NET_TXN_L,0))/ABS(NVL(OFB_NET_TXN_L,0)) ELSE NULL END AS OFB_NET_TXN_M_RDIFF
        ,NVL(OFB_NET_TXN_3M,0)OFB_NET_TXN_3M
        ,CASE WHEN NVL(OFB_NET_TXN_3M,0)=0 AND NVL(OFB_NET_TXN_3ML,0)=0 THEN NULL ELSE OFB_NET_TXN_3M - OFB_NET_TXN_3ML END OFB_NET_TXN_3M_MDIFF
        ,CASE WHEN NVL(OFB_NET_TXN_3ML,0)!=0 THEN (NVL(OFB_NET_TXN_3M,0)-NVL(OFB_NET_TXN_3ML,0))/ABS(NVL(OFB_NET_TXN_3ML,0)) ELSE NULL END AS OFB_NET_TXN_3M_RDIFF
        ,NVL(OFB_NET_TXN_6M,0)OFB_NET_TXN_6M
        ,CASE WHEN NVL(OFB_NET_TXN_6M,0)=0 AND NVL(OFB_NET_TXN_6ML,0)=0 THEN NULL ELSE OFB_NET_TXN_6M - OFB_NET_TXN_6ML END OFB_NET_TXN_6M_MDIFF
        ,CASE WHEN NVL(OFB_NET_TXN_6ML,0)!=0 THEN (NVL(OFB_NET_TXN_6M,0)-NVL(OFB_NET_TXN_6ML,0))/ABS(NVL(OFB_NET_TXN_6ML,0)) ELSE NULL END AS OFB_NET_TXN_6M_RDIFF
        ,NVL(OFB_NET_TXN_12M,0)OFB_NET_TXN_12M
        ,CASE WHEN NVL(OFB_NET_TXN_12M,0)=0 AND NVL(OFB_NET_TXN_12ML,0)=0 THEN NULL ELSE OFB_NET_TXN_12M - OFB_NET_TXN_12ML END OFB_NET_TXN_12M_MDIFF
        ,CASE WHEN NVL(OFB_NET_TXN_12ML,0)!=0 THEN (NVL(OFB_NET_TXN_12M,0)-NVL(OFB_NET_TXN_12ML,0))/ABS(NVL(OFB_NET_TXN_12ML,0)) ELSE NULL END AS OFB_NET_TXN_12M_RDIFF
        ----其他海外債周轉率
        ,CASE WHEN NVL(OFB_AUM_M,0)!=0 THEN (NVL(OFB_TXN_M,0)/NVL(OFB_AUM_M,0)) ELSE NULL END AS OFB_TURNOVER_M
        ,CASE WHEN NVL(OFB_AUM_L,0)!=0 THEN (NVL(OFB_TXN_L,0)/NVL(OFB_AUM_L,0)) ELSE NULL END AS OFB_TURNOVER_L
        ,CASE WHEN NVL(OFB_AUM_3M,0)!=0 THEN (NVL(OFB_TXN_3M,0)/NVL(OFB_AUM_3M,0)) ELSE NULL END AS OFB_TURNOVER_3M
        ,CASE WHEN NVL(OFB_AUM_3ML,0)!=0 THEN (NVL(OFB_TXN_3ML,0)/NVL(OFB_AUM_3ML,0)) ELSE NULL END AS OFB_TURNOVER_3ML
        ,CASE WHEN NVL(OFB_AUM_6M,0)!=0 THEN (NVL(OFB_TXN_6M,0)/NVL(OFB_AUM_6M,0)) ELSE NULL END AS OFB_TURNOVER_6M
        ,CASE WHEN NVL(OFB_AUM_6ML,0)!=0 THEN (NVL(OFB_TXN_6ML,0)/NVL(OFB_AUM_6ML,0)) ELSE NULL END AS OFB_TURNOVER_6ML
        ,CASE WHEN NVL(OFB_AUM_12M,0)!=0 THEN (NVL(OFB_TXN_12M,0)/NVL(OFB_AUM_12M,0)) ELSE NULL END AS OFB_TURNOVER_12M
        ,CASE WHEN NVL(OFB_AUM_12ML,0)!=0 THEN (NVL(OFB_TXN_12ML,0)/NVL(OFB_AUM_12ML,0)) ELSE NULL END AS OFB_TURNOVER_12ML
    FROM DS_SEC.CF_CUSTID A
    LEFT JOIN(  
        SELECT PARTY_ID
            ------公債 FBG
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('031') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('031') AND TXN_YYYYMM = :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FBG_NET_TXN_M
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('031') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('031') AND TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FBG_NET_TXN_L
            ,SUM(CASE WHEN PROD_STYPE_CODE IN ('031') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END)
            -SUM(CASE WHEN PROD_STYPE_CODE IN ('031') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END)FBG_NET_TXN_3M
